update public.article_cache set translation = '{"texts": ["Australian criminal Mark Read became a hot topic after giving up a liver transplant. He was called by the nickname ''Chopper''.", "Read needed a liver transplant but did not put his name on the transplant waiting list. He said, ''I am 55 years old. I don''t want to compete with a 10-year-old child.''", "Many people are talking about his decision. Although he was a criminal, he showed compassion by thinking of children.", "In Korea, there are also many organ transplant candidates waiting. It is common for older patients to make way for younger patients."], "sentences": [{"text": "호주의 유명한 범죄자 마크 리드가 간 이식을 포기해서 화제가 되었어요.", "translation": "Mark Read, a famous Australian criminal, became a hot topic by giving up a liver transplant.", "vocab": [{"ko": "범죄자", "en": "criminal"}, {"ko": "간", "en": "liver"}, {"ko": "이식", "en": "transplant"}, {"ko": "포기하다", "en": "to give up"}], "analysis": [{"type": "grammar", "label": "~아/어서 (so, because)", "exp": "Gives the reason for the result that follows. 포기하다 → 포기해서 화제가 되었어요 = became a hot topic because (he) gave up.", "example_in_sentence": "포기해서 화제가 되었어요"}]}, {"text": "그는 ''초퍼(Chopper)''라는 별명으로 불렸어요.", "translation": "He was called by the nickname ''Chopper.''", "vocab": [{"ko": "별명", "en": "nickname"}, {"ko": "불리다", "en": "to be called"}], "analysis": [{"type": "grammar", "label": "~(이)라는 (called ~)", "exp": "Comes after a name to describe the noun that follows. ''초퍼''라는 별명 = the nickname ''Chopper''.", "example_in_sentence": "''초퍼(Chopper)''라는 별명"}, {"type": "grammar", "label": "~(으)로", "exp": "Particle marking means/manner. 별명 + 으로. Indicates ''by/with the nickname.''", "example_in_sentence": "별명으로 불렸어요"}, {"type": "grammar", "label": "불리다 (passive of 부르다)", "exp": "불리다 is the passive form of 부르다 (to call). 불리다 → 불렸어요 = was called.", "example_in_sentence": "불렸어요"}]}, {"text": "리드는 간 이식이 필요했지만 이식 대기자 명단에 이름을 올리지 않았어요.", "translation": "Read needed a liver transplant but did not put his name on the transplant waiting list.", "vocab": [{"ko": "필요하다", "en": "to need"}, {"ko": "대기자", "en": "person waiting"}, {"ko": "명단", "en": "list"}, {"ko": "올리다", "en": "to put (a name) on (a list)"}], "analysis": [{"type": "grammar", "label": "~지만", "exp": "Connective ending marking contrast. 필요했다 + 지만. Links two opposing clauses (needed BUT did not register).", "example_in_sentence": "필요했지만"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. 올리다 + 지 않다 → 올리지 않았어요. Standard negation in declarative past tense.", "example_in_sentence": "올리지 않았어요"}]}, {"text": "그는 \"나는 55세예요.", "translation": "He said, \"I am 55 years old.", "vocab": [{"ko": "세", "en": "years old (counter for age)"}], "analysis": []}, {"text": "10살 아이와 경쟁하고 싶지 않아요\"라고 말했어요.", "translation": "I don''t want to compete with a 10-year-old child,\" he said.", "vocab": [{"ko": "경쟁하다", "en": "to compete"}, {"ko": "싶다", "en": "to want"}], "analysis": [{"type": "grammar", "label": "~고 싶다", "exp": "Expression of desire/wish. 경쟁하다 + 고 싶다 → 경쟁하고 싶다. Expresses what speaker wants to do.", "example_in_sentence": "경쟁하고 싶지 않아요"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation. 싶다 + 지 않다 → 싶지 않다. Negates the desire.", "example_in_sentence": "싶지 않아요"}, {"type": "grammar", "label": "~(이)라고 말하다 (direct quote)", "exp": "Comes right after a direct quote. \"...\"라고 말했어요 = said, \"...\".", "example_in_sentence": "라고 말했어요"}]}, {"text": "많은 사람들이 그의 결정에 대해 이야기하고 있어요.", "translation": "Many people are talking about his decision.", "vocab": [{"ko": "결정", "en": "decision"}, {"ko": "이야기하다", "en": "to talk"}], "analysis": [{"type": "grammar", "label": "~에 대해", "exp": "Particle phrase marking topic/object of action. 결정 + 에 대해. Indicates ''about/concerning the decision.''", "example_in_sentence": "결정에 대해"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect. 이야기하다 + 고 있어요. Indicates ongoing/continuous action in present.", "example_in_sentence": "이야기하고 있어요"}]}, {"text": "범죄자였지만 어린이를 생각하는 마음을 보여줬기 때문이에요.", "translation": "Because although he was a criminal, he showed a heart that cares for children.", "vocab": [{"ko": "범죄자", "en": "criminal"}, {"ko": "어린이", "en": "child"}, {"ko": "생각하다", "en": "to think"}, {"ko": "마음", "en": "heart/mind"}], "analysis": [{"type": "grammar", "label": "~였지만 (was ~, but)", "exp": "Past tense of 이다 plus ~지만 (but). 범죄자이다 → 범죄자였지만 = although (he) was a criminal.", "example_in_sentence": "범죄자였지만"}, {"type": "grammar", "label": "~았/었기 때문이다 (it is because ~)", "exp": "Gives the reason for the previous sentence. 보여주다 → 보여줬기 때문이에요 = it is because (he) showed.", "example_in_sentence": "보여줬기 때문이에요"}, {"type": "grammar", "label": "~는 (attributive relative clause)", "exp": "Attributive marker on present/habitual verbs. 생각하다 + 는 modifies 마음. Means ''heart that thinks/cares.''", "example_in_sentence": "생각하는 마음"}]}, {"text": "한국에서도 장기 이식 대기자가 많아요.", "translation": "In Korea too, there are many people waiting for organ transplants.", "vocab": [{"ko": "장기", "en": "organ"}, {"ko": "대기자", "en": "person waiting"}], "analysis": []}, {"text": "나이가 많은 환자들이 젊은 환자들을 위해 양보하는 경우가 종종 있어요.", "translation": "There are often cases where older patients give way to younger patients.", "vocab": [{"ko": "나이", "en": "age"}, {"ko": "환자", "en": "patient"}, {"ko": "양보하다", "en": "to yield/defer"}, {"ko": "경우", "en": "case"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 나이가 많다 → 나이가 많은 환자들 = older patients; 젊다 → 젊은 환자들 = younger patients.", "example_in_sentence": "나이가 많은 환자들"}, {"type": "grammar", "label": "~을/를 위해", "exp": "Purpose/benefactive particle phrase. 환자들 + 을 위해. Means ''for the sake of/for the benefit of.''", "example_in_sentence": "젊은 환자들을 위해"}, {"type": "grammar", "label": "~는 경우가 있다 (there are cases where ~)", "exp": "Says that something sometimes happens. 양보하다 → 양보하는 경우가 있어요 = there are cases where (they) give way.", "example_in_sentence": "양보하는 경우가 종종 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "범죄자", "en": "criminal", "note": ""}, {"ko": "간", "en": "liver", "note": ""}, {"ko": "이식", "en": "transplant", "note": ""}, {"ko": "포기하다", "en": "to give up", "note": ""}, {"ko": "별명", "en": "nickname", "note": ""}, {"ko": "불리다", "en": "to be called", "note": ""}, {"ko": "필요하다", "en": "to need", "note": ""}, {"ko": "대기자", "en": "person waiting", "note": ""}, {"ko": "명단", "en": "list", "note": ""}, {"ko": "올리다", "en": "to put (a name) on (a list)", "note": ""}, {"ko": "세", "en": "years old (counter for age)", "note": ""}, {"ko": "경쟁하다", "en": "to compete", "note": ""}, {"ko": "싶다", "en": "to want", "note": ""}, {"ko": "결정", "en": "decision", "note": ""}, {"ko": "이야기하다", "en": "to talk", "note": ""}, {"ko": "어린이", "en": "child", "note": ""}, {"ko": "생각하다", "en": "to think", "note": ""}, {"ko": "마음", "en": "heart/mind", "note": ""}, {"ko": "장기", "en": "organ", "note": ""}, {"ko": "나이", "en": "age", "note": ""}, {"ko": "환자", "en": "patient", "note": ""}, {"ko": "양보하다", "en": "to yield/defer", "note": ""}, {"ko": "경우", "en": "case", "note": ""}, {"word": "간 이식", "reading": "gan isik", "meaning": "liver transplant", "context": "간 이식을 포기해서 화제가 되었어요"}, {"word": "대기자 명단", "reading": "daegi-ja myeongdan", "meaning": "waiting list", "context": "이식 대기자 명단에 이름을 올리지 않았어요"}, {"word": "장기 이식", "reading": "janggi isik", "meaning": "organ transplant", "context": "한국에서도 장기 이식 대기자가"}, {"word": "화제", "reading": "hwaje", "meaning": "topic of conversation; a hot issue", "context": "간 이식을 포기해서 화제가 되었어요"}]', grammar = '{"patterns": [{"name": "~아/어서 (so, because)", "level": "Intermediate", "exp": "Gives the reason for the result that follows. 포기하다 → 포기해서 화제가 되었어요 = became a hot topic because (he) gave up.", "ex_ko": "호주의 유명한 범죄자 마크 리드가 간 이식을 포기해서 화제가 되었어요.", "ex_en": "Mark Read, a famous Australian criminal, became a hot topic by giving up a liver transplant."}, {"name": "~(이)라는 (called ~)", "level": "Intermediate", "exp": "Comes after a name to describe the n