update public.article_cache set translation = '{"texts": ["Japan Airlines (JAL) announced that starting next month, it will officially use humanoid robots at Haneda Airport. These robots are scheduled to handle ground operations at the airport.", "The robots will end up taking on tasks such as passenger guidance and luggage handling. It plans to cooperate together with airport staff and provide better service.", "Due to its aging society, Japan has a serious labor shortage problem. In the aviation industry too, robot technology is being actively used to address the manpower shortage.", "Korea''s Incheon International Airport is also reviewing similar robot services. Going forward, encountering robots at airports is expected to become more common."], "sentences": [{"text": "일본항공(JAL)이 다음 달부터 하네다 공항에서 인간형 로봇(humanoid robot)을 정식으로 사용한다고 발표했어요.", "translation": "Japan Airlines (JAL) announced that starting next month, it will officially use humanoid robots at Haneda Airport.", "vocab": [{"ko": "공항", "en": "airport", "note": ""}, {"ko": "인간형", "en": "humanoid", "note": ""}, {"ko": "정식", "en": "official, formal", "note": ""}, {"ko": "발표하다", "en": "to announce", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (in a ~ way)", "exp": "Noun + (으)로 can describe how something is done. 정식 → 정식으로 = officially.", "example_in_sentence": "정식으로"}, {"type": "grammar", "label": "~부터 (from)", "exp": "starting from. 다음 달 → 다음 달부터 = \"starting next month\".", "example_in_sentence": "다음 달부터"}, {"type": "grammar", "label": "~ㄴ/는다고 발표하다 (to announce that ~)", "exp": "Reports what was announced. 사용하다 → 사용한다 → 사용한다고 발표했어요 = announced that (it) will use.", "example_in_sentence": "사용한다고 발표했어요"}]}, {"text": "이 로봇들은 공항 지상 업무를 담당할 예정입니다.", "translation": "These robots are scheduled to handle ground operations at the airport.", "vocab": [{"ko": "지상", "en": "ground (level)", "note": ""}, {"ko": "업무", "en": "work, duties", "note": ""}, {"ko": "담당하다", "en": "to be in charge of", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 예정이다 (is scheduled to)", "exp": "A formal way to talk about a plan. 담당하다 → 담당할 예정입니다 = is scheduled to handle.", "example_in_sentence": "담당할 예정입니다"}]}, {"text": "로봇들은 승객 안내와 짐 운반 등의 업무를 맡게 되어요.", "translation": "The robots will end up taking on tasks such as passenger guidance and luggage handling.", "vocab": [{"ko": "승객", "en": "passenger", "note": ""}, {"ko": "안내", "en": "guidance", "note": ""}, {"ko": "짐", "en": "luggage", "note": ""}, {"ko": "운반", "en": "transport, carrying", "note": ""}], "analysis": [{"type": "grammar", "label": "~게 되다 (will come to ~)", "exp": "Shows a new situation that comes about. 맡다 → 맡게 되어요 = will take on (the tasks).", "example_in_sentence": "맡게 되어요"}, {"type": "expression", "label": "~ 등(의) (such as ~)", "exp": "Lists examples. 승객 안내와 짐 운반 등의 업무 = tasks such as guiding passengers and moving luggage.", "example_in_sentence": "짐 운반 등의 업무"}]}, {"text": "공항 직원들과 함께 협력하여 더 나은 서비스를 제공할 계획입니다.", "translation": "They plan to work together with airport staff to provide better service.", "vocab": [{"ko": "직원", "en": "staff, employee", "note": ""}, {"ko": "협력하다", "en": "to cooperate", "note": ""}, {"ko": "낫다", "en": "to be better", "note": "ㅅ-irregular: 낫+은 → 나은"}, {"ko": "제공하다", "en": "to provide", "note": ""}], "analysis": [{"type": "grammar", "label": "~와/과 함께 (together with)", "exp": "Means doing something with someone. 직원들과 함께 = together with the staff.", "example_in_sentence": "직원들과 함께"}, {"type": "grammar", "label": "~(으)ㄹ 계획이다 (plans to)", "exp": "A formal way to state a plan. 제공하다 → 제공할 계획입니다 = plans to provide.", "example_in_sentence": "제공할 계획입니다"}, {"type": "expression", "label": "~하여 (formal form of ~해서)", "exp": "The written, formal form of 해서. 협력하다 → 협력하여 = by cooperating, and ...", "example_in_sentence": "협력하여"}]}, {"text": "일본은 고령화 사회로 인해 노동력 부족 문제가 심각해요.", "translation": "Due to its aging society, Japan has a serious labor shortage problem.", "vocab": [{"ko": "고령화", "en": "aging (of population)", "note": ""}, {"ko": "노동력", "en": "workforce, labor force", "note": ""}, {"ko": "부족", "en": "shortage", "note": ""}, {"ko": "심각하다", "en": "to be serious", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 인해 (due to)", "exp": "A formal way to give a cause. 고령화 사회로 인해 = due to the aging society.", "example_in_sentence": "고령화 사회로 인해"}]}, {"text": "항공업계에서도 인력난을 해결하기 위해 로봇 기술을 적극 활용하고 있습니다.", "translation": "In the aviation industry too, robot technology is being actively used to address the manpower shortage.", "vocab": [{"ko": "업계", "en": "industry", "note": ""}, {"ko": "인력난", "en": "manpower shortage", "note": ""}, {"ko": "해결하다", "en": "to solve", "note": ""}, {"ko": "활용하다", "en": "to utilize", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 활용하다 → 활용하고 있다 = \"is utilizing\".", "example_in_sentence": "활용하고 있습니다"}, {"type": "grammar", "label": "~기 위해(서) (in order to)", "exp": "purpose. 해결하다 → 해결하기 위해 = \"in order to solve\".", "example_in_sentence": "해결하기 위해"}]}, {"text": "한국의 인천국제공항도 비슷한 로봇 서비스를 검토하고 있어요.", "translation": "Korea''s Incheon International Airport is also reviewing similar robot services.", "vocab": [{"ko": "비슷하다", "en": "to be similar", "note": ""}, {"ko": "검토하다", "en": "to review, examine", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 검토하다 → 검토하고 있다 = \"is reviewing\".", "example_in_sentence": "검토하고 있어요"}]}, {"text": "앞으로 공항에서 로봇을 만나는 일이 더 흔해질 것으로 보입니다.", "translation": "Going forward, encountering robots at airports is expected to become more common.", "vocab": [{"ko": "앞으로", "en": "from now on, going forward", "note": ""}, {"ko": "만나다", "en": "to meet, encounter", "note": ""}, {"ko": "흔하다", "en": "to be common", "note": ""}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 것으로 보이다 (is expected to ~)", "exp": "A news phrase for predictions. 흔해지다 → 흔해질 것으로 보입니다 = is expected to become common.", "example_in_sentence": "흔해질 것으로 보입니다"}, {"type": "expression", "label": "~아/어지다 (become)", "exp": "change-of-state. 흔하다 → 흔해지다 → 흔해질 = \"will become common\".", "example_in_sentence": "흔해질"}]}], "version": "s5"}', vocab = '[{"ko": "공항", "en": "airport", "note": ""}, {"ko": "인간형", "en": "humanoid", "note": ""}, {"ko": "정식", "en": "official, formal", "note": ""}, {"ko": "발표하다", "en": "to announce", "note": ""}, {"ko": "지상", "en": "ground (level)", "note": ""}, {"ko": "업무", "en": "work, duties", "note": ""}, {"ko": "담당하다", "en": "to be in charge of", "note": ""}, {"ko": "승객", "en": "passenger", "note": ""}, {"ko": "안내", "en": "guidance", "note": ""}, {"ko": "짐", "en": "luggage", "note": ""}, {"ko": "운반", "en": "transport, carrying", "note": ""}, {"ko": "직원", "en": "staff, employee", "note": ""}, {"ko": "협력하다", "en": "to cooperate", "note": ""}, {"ko": "낫다", "en": "to be better", "note": "ㅅ-irregular: 낫+은 → 나은"}, {"ko": "제공하다", "en": "to provide", "note": ""}, {"ko": "고령화", "en": "aging (of population)", "note": ""}, {"ko": "노동력", "en": "workforce, labor force", "note": ""}, {"ko": "부족", "en": "shortage", "note": ""}, {"ko": "심각하다", "en": "to be serious", "note": ""}, {"ko": "업계", "en": "industry", "note": ""}, {"ko": "인력난", "en": "manpower shortage", "note": ""}, {"ko": "해결하다", "en": "to solve", "note": ""}, {"ko": "활용하다", "en": "to utilize", "note": ""}, {"ko": "비슷하다", "en": "to be similar", "note": ""}, {"ko": "검토하다", "en": "to review, examine", "note": ""}, {"ko": "앞으로", "en": "from now on, going forward", "note": ""}, {"ko": "만나다", "en": "to meet, encounter", "note": ""}, {"ko": "흔하다", "en": "to be common", "note": ""}]', grammar = '{"patterns": [{"name": "~(으)로 (in a ~ way)", "level": "Intermediate", "exp": "Noun + (으)로 can describe how something is done. 정식 → 정식으로 = officially.", "ex_ko": "일본항공(JAL)이 다음 달부터 하네다 공항에서 인간형 로봇(humanoid robot)을 정식으로 사용한다고 발표했어요.", "ex_en": "Japan Airlines (JAL) announced that starting next month, it will officially use humanoid robots at Haneda Airport."}, {"name": "~부터 (from)", "level": "Intermediate", "exp": "starting from. 다음 달 → 다음 달부터 = \"starting next month\".", "ex_ko": "일본항공(JAL)이 다음 달부터 하네다 공항에서 인간형 로봇(humanoid robot)을 정식으로 사용한다고 발표했어요.", "ex_en": "Japan Airlines (JAL) announced that starting next month, it will officially use humanoid robots at Haneda Airport."}, {"name": "~ㄴ/는다고 발표하다 (to announce that ~)", "level": "Intermediate", "exp": "Reports what was announced. 사용하다 → 사용한다 → 사용한다고 발표했어요 = announced that (it) will use.", "ex_ko": "일본항공(JAL)이 다음 달부터 하네다 공항에서 인간형 로봇(humanoid robot)을 정식으로 사용한다고 발표했어요.", "ex_en": "Japan Airlines (JAL) announced that starting next month, it will officially use humanoid robots at Haneda Airport."}, {"name": "~(으)ㄹ 예정이다 (is scheduled to)", "level": "Intermediate", "exp": "A formal way to talk about a plan. 담당하다 → 담당할 예정입니다 = is scheduled to handle.", "ex_ko": "이 로봇들은 공항 지상 업무를 담당할 예정입니다.", "ex_en": "These robots are scheduled to handle ground operations at the airport."}, {"name": "~게 되다 (will come to ~)", "level": "Intermediate", "exp": "Shows a new situation that comes about. 맡다 → 맡게 되어요 = will take on (the tasks).", "ex_ko": "로봇들은 승객 안내와 짐 운반 등의 업무를 맡게 되어요.", "ex_en": "The robots will end up taking on tasks such as passenger guidance and luggage handling."}, {"name": "~와/과 함께 (together with)", "level": "Intermediate", "exp": "Means doing something with someone. 직원들과 함께 = together with the staff.", "ex_ko": "공항 직원들과 함께 협력하여 더 나은 서비스를 제공할 계획입니다.", "ex_en": "They plan to work together with airport staff to provide better service."}, {"name": "~(으)ㄹ 계획이다 (plans to)", "level": "Intermediate", "exp": "A formal way to state a plan. 제공하다 → 제공할 계획입니다 = plans to provide.", "ex_ko": "공항 직원들과 함께 협력하여 더 나은 서비스를 제공할 계획입니다.", "ex_en": "They plan to work together with airport staff to provide better service."}, {"name": "~(으)로 인해 (due to)", "level": "Intermediate", "exp": "A formal way to give a cause. 고령화 사회로 인해 = due to the aging society.", "ex_ko": "일본은 고령화 사회로 인해 노동력 부족 문제가 심각해요.", "ex_en": "Due to its aging society, Japan has a serious labor shortage problem."}, {"name": "~고 있다 (continuous)", "level": "Intermediate", "exp": "progressive. 활용하다 → 활용하고 있다 = \"is utilizing\".", "ex_ko": "항공업계에서도 인력난을 해결하기 위해 로봇 기술을 적극 활용하고 있습니다.", "ex_en": "In the aviation industry too, robot technology is being actively used to address the manpower shortage."}, {"name": "~기 위해(서) (in order to)", "level": "Intermediate", "exp": "purpose. 해결하다 → 해결하기 위해 = \"in order to solve\".", "ex_ko": "항공업계에서도 인력난을 해결하기 위해 로봇 기술을 적극 활용하고 있습니다.", "ex_en": "In the aviation industry too, robot technology is being actively used to address the manpower shortage."}]}', updated_at = now() where article_id = 'moknthahfb0g' and md5(translation) = '11170162541ee027749b9cd28b8d6c95';
update public.article_cache set translation = '{"texts": ["A gorilla at an American zoo is communicating with visitors through sign language. This gorilla expresses the meaning of ''don''t do that'' in sign language when people try to give it food.", "A zoo official explained, ''This gorilla has been learning sign language for a long time.'' The gorilla shows a gesture of refusal when visitors try to hand it food. It is following the zoo rules on its own.", "Experts said, ''It is very amazing that the gorilla understands the rules and communicates them to other people.'' This behavior is an example that demonstrates the gorilla''s high intelligence.", "Several zoos in Korea are also operating communication programs with animals. In the future, more animals may be able to have conversations with humans."], "sentences": [{"text": "미국 동물원의 고릴라 한 마리가 수화(手話, sign language)로 관람객들과 대화를 나누고 있어요.", "translation": "A gorilla at a U.S. zoo is having a conversation with visitors using sign language.", "vocab": [{"ko": "수화", "en": "sign language"}, {"ko": "관람객", "en": "visitor"}, {"ko": "대화", "en": "conversation"}, {"ko": "나누다", "en": "to have/share"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker. The auxiliary ''있다'' with connective ''~고'' shows ongoing action in present time.", "example_in_sentence": "대화를 나누고 있어요"}]}, {"text": "이 고릴라는 사람들이 먹이를 주려고 할 때 ''안 된다''는 뜻을 수화로 표현합니다.", "translation": "When people try to give the gorilla food, it expresses the meaning ''you shouldn''t'' using sign language.", "vocab": [{"ko": "먹이", "en": "food/feed"}, {"ko": "뜻", "en": "meaning"}, {"ko": "표현하다", "en": "to express"}], "analysis": [{"type": "grammar", "label": "~(으)려고 하다 (to try to)", "exp": "Shows an attempt or intention. 주다 → 주려고 하다 = to try to give.", "example_in_sentence": "먹이를 주려고 할 때"}, {"type": "expression", "label": "~(으)ㄹ 때 (when)", "exp": "Marks the time when something happens. 하다 → 할 때 = when (people) do.", "example_in_sentence": "주려고 할 때"}]}, {"text": "동물원 관계자는 \"이 고릴라는 오랫동안 수화를 배워왔다\"고 설명했어요.", "translation": "A zoo official explained, \"This gorilla has been learning sign language for a long time.\"", "vocab": [{"ko": "관계자", "en": "official/personnel"}, {"ko": "오랫동안", "en": "for a long time"}, {"ko": "배우다", "en": "to learn"}], "analysis": [{"type": "grammar", "label": "~아/어 왔다", "exp": "Perfect progressive aspect. The auxiliary ''오다'' with past ''~았/었'' shows an action started in the past and continues to present.", "example_in_sentence": "배워왔다"}, {"type": "grammar", "label": "~고 설명하다", "exp": "Connective ''~고'' links quoted speech to the verb of saying. Pattern: \"[quote]\"고 설명했어요.", "example_in_sentence": "\"이 고릴라는 오랫동안 수화를 배워왔다\"고 설명했어요"}]}, {"text": "고릴라는 관람객들이 음식을 건네려고 하면 손짓으로 거절 의사를 보여줍니다.", "translation": "When visitors try to hand it food, the gorilla shows its refusal with hand gestures.", "vocab": [{"ko": "건네다", "en": "to hand/pass"}, {"ko": "손짓", "en": "gesture"}, {"ko": "거절", "en": "refusal"}, {"ko": "의사", "en": "intention/will"}], "analysis": [{"type": "grammar", "label": "~(으)면 (when, if)", "exp": "Sets up a condition or time. 건네려고 하다 → 건네려고 하면 = when (visitors) try to hand (food).", "example_in_sentence": "건네려고 하면"}]}, {"text": "동물원 규칙을 스스로 지키고 있는 거예요.", "translation": "It''s following the zoo''s rules on its own.", "vocab": [{"ko": "규칙", "en": "rule"}, {"ko": "스스로", "en": "by oneself/on one''s own"}, {"ko": "지키다", "en": "to follow/observe"}], "analysis": [{"type": "grammar", "label": "~고 있는 거예요 (it''s that ~ is ~ing)", "exp": "~는 거예요 explains what is really going on. 지키다 → 지키고 있는 거예요 = (it''s that) it is keeping (the rules).", "example_in_sentence": "지키고 있는 거예요"}]}, {"text": "전문가들은 \"고릴라가 규칙을 이해하고 다른 사람들에게 알리는 것은 매우 놀라운 일\"이라고 말했어요.", "translation": "Experts said, \"It is a very remarkable thing that a gorilla understands rules and communicates them to other people.\"", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "이해하다", "en": "to understand"}, {"ko": "알리다", "en": "to inform/communicate"}, {"ko": "놀랍다", "en": "to be remarkable; to be surprising"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Coordinate connective listing two actions. Connects ''이해하고'' to ''알리는'' (understand and inform).", "example_in_sentence": "이해하고"}, {"type": "expression", "label": "~는 것은 (that-clause/gerund)", "exp": "Nominalizer ''~는 것'' with topic marker ''은'' creates noun phrase as subject. Transforms verb phrase into noun.", "example_in_sentence": "알리는 것은"}]}, {"text": "이런 행동은 고릴라의 높은 지능을 보여주는 사례입니다.", "translation": "This kind of behavior is an example showing the gorilla''s high intelligence.", "vocab": [{"ko": "행동", "en": "behavior/action"}, {"ko": "지능", "en": "intelligence"}, {"ko": "보여주다", "en": "to show/demonstrate"}, {"ko": "사례", "en": "case/example"}], "analysis": [{"type": "grammar", "label": "~는 사례", "exp": "Attributive modifier ''~는'' modifies noun ''사례''. The relative clause shows the type of example.", "example_in_sentence": "보여주는 사례"}]}, {"text": "한국의 여러 동물원에서도 동물들과의 소통 프로그램을 운영하고 있어요.", "translation": "Multiple zoos in Korea are also operating communication programs with animals.", "vocab": [{"ko": "여러", "en": "several/multiple"}, {"ko": "소통", "en": "communication"}, {"ko": "운영하다", "en": "to operate/run"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive present tense. Shows ongoing habitual or current action.", "example_in_sentence": "운영하고 있어요"}]}, {"text": "앞으로 더 많은 동물들이 사람과 대화할 수 있게 될지도 모릅니다.", "translation": "In the future, it is possible that more animals will be able to have conversations with people.", "vocab": [{"ko": "앞으로", "en": "in the future/from now on"}, {"ko": "더", "en": "more"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있게 되다 (to become able to)", "exp": "Shows gaining an ability. 대화하다 → 대화할 수 있게 되다 = to become able to talk.", "example_in_sentence": "대화할 수 있게 될지도"}, {"type": "expression", "label": "~(으)ㄹ지도 모르다 (might)", "exp": "Says something might happen, without being sure. 되다 → 될지도 모릅니다 = (it) might happen.", "example_in_sentence": "될지도 모릅니다"}]}], "version": "s6"}', vocab = '[{"ko": "수화", "en": "sign language", "note": ""}, {"ko": "관람객", "en": "visitor", "note": ""}, {"ko": "대화", "en": "conversation", "note": ""}, {"ko": "나누다", "en": "to have/share", "note": ""}, {"ko": "먹이", "en": "food/feed", "note": ""}, {"ko": "뜻", "en": "meaning", "note": ""}, {"ko": "표현하다", "en": "to express", "note": ""}, {"ko": "관계자", "en": "official/personnel", "note": ""}, {"ko": "오랫동안", "en": "for a long time", "note": ""}, {"ko": "배우다", "en": "to learn", "note": ""}, {"ko": "건네다", "en": "to hand/pass", "note": ""}, {"ko": "손짓", "en": "gesture", "note": ""}, {"ko": "거절", "en": "refusal", "note": ""}, {"ko": "의사", "en": "intention/will", "note": ""}, {"ko": "규칙", "en": "rule", "note": ""}, {"ko": "스스로", "en": "by oneself/on one''s own", "note": ""}, {"ko": "지키다", "en": "to follow/observe", "note": ""}, {"ko": "전문가", "en": "expert", "note": ""}, {"ko": "이해하다", "en": "to understand", "note": ""}, {"ko": "알리다", "en": "to inform/communicate", "note": ""}, {"ko": "놀랍다", "en": "to be remarkable; to be surprising", "note": ""}, {"ko": "행동", "en": "behavior/action", "note": ""}, {"ko": "지능", "en": "intelligence", "note": ""}, {"ko": "보여주다", "en": "to show/demonstrate", "note": ""}, {"ko": "사례", "en": "case/example", "note": ""}, {"ko": "여러", "en": "several/multiple", "note": ""}, {"ko": "소통", "en": "communication", "note": ""}, {"ko": "운영하다", "en": "to operate/run", "note": ""}, {"ko": "앞으로", "en": "in the future/from now on", "note": ""}, {"ko": "더", "en": "more", "note": ""}]', grammar = '{"patterns": [{"name": "~고 있어요", "level": "Intermediate", "exp": "Progressive aspect marker. The auxiliary ''있다'' with connective ''~고'' shows ongoing action in present time.", "ex_ko": "미국 동물원의 고릴라 한 마리가 수화(手話, sign language)로 관람객들과 대화를 나누고 있어요.", "ex_en": "A gorilla at a U.S. zoo is having a conversation with visitors using sign language."}, {"name": "~(으)려고 하다 (to try to)", "level": "Intermediate", "exp": "Shows an attempt or intention. 주다 → 주려고 하다 = to try to give.", "ex_ko": "이 고릴라는 사람들이 먹이를 주려고 할 때 ''안 된다''는 뜻을 수화로 표현합니다.", "ex_en": "When people try to give the gorilla food, it expresses the meaning ''you shouldn''t'' using sign language."}, {"name": "~아/어 왔다", "level": "Intermediate", "exp": "Perfect progressive aspect. The auxiliary ''오다'' with past ''~았/었'' shows an action started in the past and continues to present.", "ex_ko": "동물원 관계자는 \"이 고릴라는 오랫동안 수화를 배워왔다\"고 설명했어요.", "ex_en": "A zoo official explained, \"This gorilla has been learning sign language for a long time.\""}, {"name": "~고 설명하다", "level": "Intermediate", "exp": "Connective ''~고'' links quoted speech to the verb of saying. Pattern: \"[quote]\"고 설명했어요.", "ex_ko": "동물원 관계자는 \"이 고릴라는 오랫동안 수화를 배워왔다\"고 설명했어요.", "ex_en": "A zoo official explained, \"This gorilla has been learning sign language for a long time.\""}, {"name": "~(으)면 (when, if)", "level": "Intermediate", "exp": "Sets up a condition or time. 건네려고 하다 → 건네려고 하면 = when (visitors) try to hand (food).", "ex_ko": "고릴라는 관람객들이 음식을 건네려고 하면 손짓으로 거절 의사를 보여줍니다.", "ex_en": "When visitors try to hand it food, the gorilla shows its refusal with hand gestures."}, {"name": "~고 있는 거예요 (it''s that ~ is ~ing)", "level": "Intermediate", "exp": "~는 거예요 explains what is really going on. 지키다 → 지키고 있는 거예요 = (it''s that) it is keeping (the rules).", "ex_ko": "동물원 규칙을 스스로 지키고 있는 거예요.", "ex_en": "It''s following the zoo''s rules on its own."}, {"name": "~고", "level": "Intermediate", "exp": "Coordinate connective listing two actions. Connects ''이해하고'' to ''알리는'' (understand and inform).", "ex_ko": "전문가들은 \"고릴라가 규칙을 이해하고 다른 사람들에게 알리는 것은 매우 놀라운 일\"이라고 말했어요.", "ex_en": "Experts said, \"It is a very remarkable thing that a gorilla understands rules and communicates them to other people.\""}, {"name": "~는 사례", "level": "Intermediate", "exp": "Attributive modifier ''~는'' modifies noun ''사례''. The relative clause shows the type of example.", "ex_ko": "이런 행동은 고릴라의 높은 지능을 보여주는 사례입니다.", "ex_en": "This kind of behavior is an example showing the gorilla''s high intelligence."}, {"name": "~(으)ㄹ 수 있게 되다 (to become able to)", "level": "Intermediate", "exp": "Shows gaining an ability. 대화하다 → 대화할 수 있게 되다 = to become able to talk.", "ex_ko": "앞으로 더 많은 동물들이 사람과 대화할 수 있게 될지도 모릅니다.", "ex_en": "In the future, it is possible that more animals will be able to have conversations with people."}]}', updated_at = now() where article_id = 'moknu4ll6k3p' and md5(translation) = '640ab67c8329b9d9824e938f13283342';
update public.article_cache set translation = '{"texts": ["There is a snake called chrysopelea. This snake is called a ''flying snake.'' It is a really amazing snake.", "This snake can fly in the sky. It moves from tree to tree. It moves just like a bird.", "The flying snake can go very far. It can fly up to 100 meters. It is a distance as long as a soccer field.", "This snake flattens its body. Then it glides through the air. It is a really smart animal."], "sentences": [{"text": "크리소펠레아(chrysopelea)라는 뱀이 있어요.", "translation": "There is a snake called chrysopelea.", "vocab": [{"ko": "뱀", "en": "snake"}, {"ko": "있다", "en": "there is; to exist"}], "analysis": [{"type": "grammar", "label": "~라는", "exp": "Quotative particle marking a name or label. Attached to nouns to indicate ''called'' or ''named''. Form: noun + 라는.", "example_in_sentence": "크리소펠레아(chrysopelea)라는"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending for statements. Conjugation: 있다 → 있어요.", "example_in_sentence": "있어요"}]}, {"text": "이 뱀은 ''날으는 뱀''이라고 불려요.", "translation": "This snake is called a ''flying snake.''", "vocab": [{"ko": "이", "en": "this"}, {"ko": "날다", "en": "to fly"}, {"ko": "불리다", "en": "to be called"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. The standard form is 날다 → 나는 뱀 (ㄹ drops before 는); 날으는 is a common nonstandard spelling.", "example_in_sentence": "날으는"}, {"type": "grammar", "label": "~이라고", "exp": "Quotative particle introducing reported speech or labels. Marks what something is called or said. Form: noun + 이라고.", "example_in_sentence": "''날으는 뱀''이라고"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 불리다 (to be called) → 불려요 = is called.", "example_in_sentence": "불려요"}]}, {"text": "정말 신기한 뱀이에요.", "translation": "It is a truly amazing snake.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "신기하다", "en": "to be amazing; to be wonderful"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 신기하다 → 신기한 뱀 = an amazing snake.", "example_in_sentence": "신기한"}, {"type": "grammar", "label": "~이에요", "exp": "Copula (linking verb) polite ending. Identifies or describes the subject. Form: noun + 이에요.", "example_in_sentence": "이에요"}]}, {"text": "이 뱀은 하늘을 날 수 있어요.", "translation": "This snake can fly through the sky.", "vocab": [{"ko": "하늘", "en": "sky"}, {"ko": "날다", "en": "to fly"}], "analysis": [{"type": "grammar", "label": "~을", "exp": "Object particle marking direct object. Used after nouns ending in consonants. Form: 하늘 (ends in consonant ㄹ) + 을.", "example_in_sentence": "하늘을"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 날다 → 날 수 있어요 = can fly.", "example_in_sentence": "날 수 있어요"}]}, {"text": "나무에서 나무로 이동해요.", "translation": "It moves from tree to tree.", "vocab": [{"ko": "나무", "en": "tree"}, {"ko": "이동하다", "en": "to move; to relocate"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Particle marking location of origin or action. ''From'' or ''at.'' Form: noun + 에서.", "example_in_sentence": "나무에서"}, {"type": "grammar", "label": "~로", "exp": "Particle marking destination or direction. ''To'' or ''toward.'' Form: noun + 로.", "example_in_sentence": "나무로"}, {"type": "grammar", "label": "~해요", "exp": "Present tense polite ending for action verbs. Conjugation: 이동하다 → 이동해요.", "example_in_sentence": "이동해요"}]}, {"text": "마치 새처럼 움직여요.", "translation": "It moves just like a bird.", "vocab": [{"ko": "마치", "en": "just; as if"}, {"ko": "새", "en": "bird"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "expression", "label": "~처럼", "exp": "Particle expressing similarity or manner. ''Like'' or ''as.'' Form: noun + 처럼.", "example_in_sentence": "새처럼"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 움직이다 → 움직여요 (이 + 어요 becomes 여요).", "example_in_sentence": "움직여요"}]}, {"text": "날으는 뱀은 아주 멀리 갈 수 있어요.", "translation": "The flying snake can go very far.", "vocab": [{"ko": "멀다", "en": "to be far"}, {"ko": "가다", "en": "to go"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. The standard form is 날다 → 나는 뱀 (ㄹ drops before 는); 날으는 is a common nonstandard spelling.", "example_in_sentence": "날으는"}, {"type": "grammar", "label": "멀리 (far)", "exp": "An adverb made from 멀다 (to be far). 멀리 가다 = to go far.", "example_in_sentence": "멀리"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility/ability. Form: 가다 → 갈 수 있어요.", "example_in_sentence": "갈 수 있어요"}]}, {"text": "100미터까지 날아갈 수 있어요.", "translation": "It can fly up to 100 meters.", "vocab": [{"ko": "미터", "en": "meter (unit)"}, {"ko": "날아가다", "en": "to fly away; to fly off"}], "analysis": [{"type": "grammar", "label": "~까지", "exp": "Particle marking extent or limit. ''Up to'' or ''until.'' Form: noun + 까지.", "example_in_sentence": "100미터까지"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility/ability. Form: 날아가다 → 날아갈 수 있어요.", "example_in_sentence": "날아갈 수 있어요"}]}, {"text": "축구장만큼 긴 거리예요.", "translation": "It is a distance as long as a soccer field.", "vocab": [{"ko": "축구장", "en": "soccer field"}, {"ko": "길다", "en": "to be long"}, {"ko": "거리", "en": "distance"}], "analysis": [{"type": "expression", "label": "~만큼", "exp": "Particle expressing comparison or degree. ''As much as'' or ''about.'' Form: noun + 만큼.", "example_in_sentence": "축구장만큼"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 길다 → 긴 거리 = a long distance (ㄹ drops before ㄴ).", "example_in_sentence": "긴 거리"}, {"type": "grammar", "label": "~예요", "exp": "Copula polite ending (contracted form of ~이에요). Form: noun + 예요.", "example_in_sentence": "예요"}]}, {"text": "이 뱀은 몸을 평평하게 만들어요.", "translation": "This snake flattens its body.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "평평하다", "en": "to be flat"}, {"ko": "만들다", "en": "to make; to create"}], "analysis": [{"type": "grammar", "label": "~을", "exp": "Object particle marking direct object after nouns ending in consonants. Form: 몸 + 을.", "example_in_sentence": "몸을"}, {"type": "grammar", "label": "~게 (adverb form)", "exp": "Turns a describing word into an adverb. 평평하다 → 평평하게 만들다 = to make (it) flat.", "example_in_sentence": "평평하게"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending. Conjugation: 만들다 → 만들어요.", "example_in_sentence": "만들어요"}]}, {"text": "그러면 공중에서 미끄러져 가요.", "translation": "Then it slides through the air.", "vocab": [{"ko": "공중", "en": "air; sky"}, {"ko": "미끄러지다", "en": "to slide; to slip"}], "analysis": [{"type": "grammar", "label": "그러면 (then, if so)", "exp": "A linking word at the start of a sentence meaning ''then'' or ''if so''.", "example_in_sentence": "그러면"}, {"type": "grammar", "label": "~에서", "exp": "Particle marking location of action. ''In'' or ''at.'' Form: noun + 에서.", "example_in_sentence": "공중에서"}, {"type": "grammar", "label": "~어 가다", "exp": "Auxiliary construction expressing action in progress/continuation. Form: verb stem + 어/아 + 가다. Here: 미끄러지다 → 미끄러져 가요.", "example_in_sentence": "미끄러져 가요"}]}, {"text": "정말 똑똑한 동물이에요.", "translation": "It is truly a smart animal.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent"}, {"ko": "동물", "en": "animal"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 똑똑하다 → 똑똑한 동물 = a smart animal.", "example_in_sentence": "똑똑한"}, {"type": "grammar", "label": "~이에요", "exp": "Copula polite ending. Identifies or describes the subject. Form: noun + 이에요.", "example_in_sentence": "이에요"}]}], "version": "s6"}', vocab = '[{"ko": "뱀", "en": "snake", "note": ""}, {"ko": "있다", "en": "there is; to exist", "note": ""}, {"ko": "이", "en": "this", "note": ""}, {"ko": "날다", "en": "to fly", "note": ""}, {"ko": "불리다", "en": "to be called", "note": ""}, {"ko": "정말", "en": "really; truly", "note": ""}, {"ko": "신기하다", "en": "to be amazing; to be wonderful", "note": ""}, {"ko": "하늘", "en": "sky", "note": ""}, {"ko": "나무", "en": "tree", "note": ""}, {"ko": "이동하다", "en": "to move; to relocate", "note": ""}, {"ko": "마치", "en": "just; as if", "note": ""}, {"ko": "새", "en": "bird", "note": ""}, {"ko": "움직이다", "en": "to move", "note": ""}, {"ko": "멀다", "en": "to be far", "note": ""}, {"ko": "가다", "en": "to go", "note": ""}, {"ko": "미터", "en": "meter (unit)", "note": ""}, {"ko": "날아가다", "en": "to fly away; to fly off", "note": ""}, {"ko": "축구장", "en": "soccer field", "note": ""}, {"ko": "길다", "en": "to be long", "note": ""}, {"ko": "거리", "en": "distance", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "평평하다", "en": "to be flat", "note": ""}, {"ko": "만들다", "en": "to make; to create", "note": ""}, {"ko": "공중", "en": "air; sky", "note": ""}, {"ko": "미끄러지다", "en": "to slide; to slip", "note": ""}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent", "note": ""}, {"ko": "동물", "en": "animal", "note": ""}]', grammar = '{"patterns": [{"name": "~라는", "level": "Starter", "exp": "Quotative particle marking a name or label. Attached to nouns to indicate ''called'' or ''named''. Form: noun + 라는.", "ex_ko": "크리소펠레아(chrysopelea)라는 뱀이 있어요.", "ex_en": "There is a snake called chrysopelea."}, {"name": "~어요", "level": "Starter", "exp": "Present tense polite ending for statements. Conjugation: 있다 → 있어요.", "ex_ko": "크리소펠레아(chrysopelea)라는 뱀이 있어요.", "ex_en": "There is a snake called chrysopelea."}, {"name": "~는 (noun modifier)", "level": "Starter", "exp": "Describes the noun that follows. The standard form is 날다 → 나는 뱀 (ㄹ drops before 는); 날으는 is a common nonstandard spelling.", "ex_ko": "이 뱀은 ''날으는 뱀''이라고 불려요.", "ex_en": "This snake is called a ''flying snake.''"}, {"name": "~이라고", "level": "Starter", "exp": "Quotative particle introducing reported speech or labels. Marks what something is called or said. Form: noun + 이라고.", "ex_ko": "이 뱀은 ''날으는 뱀''이라고 불려요.", "ex_en": "This snake is called a ''flying snake.''"}, {"name": "~아/어요 (polite ending)", "level": "Starter", "exp": "The everyday polite ending. 불리다 (to be called) → 불려요 = is called.", "ex_ko": "이 뱀은 ''날으는 뱀''이라고 불려요.", "ex_en": "This snake is called a ''flying snake.''"}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Starter", "exp": "Describing words take ~(으)ㄴ before a noun. 길다 → 긴 거리 = a long distance (ㄹ drops before ㄴ).", "ex_ko": "정말 신기한 뱀이에요.", "ex_en": "It is a truly amazing snake."}, {"name": "~이에요", "level": "Starter", "exp": "Copula (linking verb) polite ending. Identifies or describes the subject. Form: noun + 이에요.", "ex_ko": "정말 신기한 뱀이에요.", "ex_en": "It is a truly amazing snake."}, {"name": "~을", "level": "Starter", "exp": "Object particle marking direct object. Used after nouns ending in consonants. Form: 하늘 (ends in consonant ㄹ) + 을.", "ex_ko": "이 뱀은 하늘을 날 수 있어요.", "ex_en": "This snake can fly through the sky."}, {"name": "~(으)ㄹ 수 있다 (can)", "level": "Starter", "exp": "Says someone is able to do something. 날다 → 날 수 있어요 = can fly.", "ex_ko": "이 뱀은 하늘을 날 수 있어요.", "ex_en": "This snake can fly through the sky."}, {"name": "~에서", "level": "Starter", "exp": "Particle marking location of origin or action. ''From'' or ''at.'' Form: noun + 에서.", "ex_ko": "나무에서 나무로 이동해요.", "ex_en": "It moves from tree to tree."}, {"name": "~로", "level": "Starter", "exp": "Particle marking destination or direction. ''To'' or ''toward.'' Form: noun + 로.", "ex_ko": "나무에서 나무로 이동해요.", "ex_en": "It moves from tree to tree."}, {"name": "~해요", "level": "Starter", "exp": "Present tense polite ending for action verbs. Conjugation: 이동하다 → 이동해요.", "ex_ko": "나무에서 나무로 이동해요.", "ex_en": "It moves from tree to tree."}, {"name": "멀리 (far)", "level": "Starter", "exp": "An adverb made from 멀다 (to be far). 멀리 가다 = to go far.", "ex_ko": "날으는 뱀은 아주 멀리 갈 수 있어요.", "ex_en": "The flying snake can go very far."}, {"name": "~ㄹ 수 있다", "level": "Starter", "exp": "Auxiliary expressing possibility/ability. Form: 날아가다 → 날아갈 수 있어요.", "ex_ko": "날으는 뱀은 아주 멀리 갈 수 있어요.", "ex_en": "The flying snake can go very far."}, {"name": "~까지", "level": "Starter", "exp": "Particle marking extent or limit. ''Up to'' or ''until.'' Form: noun + 까지.", "ex_ko": "100미터까지 날아갈 수 있어요.", "ex_en": "It can fly up to 100 meters."}]}', updated_at = now() where article_id = 'moknuz8x5kiz' and md5(translation) = 'd8e01ff2eef5a6e2cb705d3ee86c7968';
update public.article_cache set translation = '{"texts": ["Snake teeth are different from ours. Snakes don''t chew their food. That''s why snake teeth are pointy. Venomous snake teeth are even more special. There are small holes inside their teeth. Venom comes out through these holes. Snakes are fine even if their teeth fall out. New teeth grow back. Snakes'' teeth keep changing throughout their entire lives. Venomous snakes also live in our country. If you meet a snake in the mountains, you need to be careful. It''s best to watch from a distance.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "뱀의 이빨은 우리와 달라요.", "translation": "A snake''s teeth are different from ours.", "vocab": [{"ko": "뱀", "en": "snake"}, {"ko": "이빨", "en": "tooth/teeth"}, {"ko": "다르다", "en": "to be different"}], "analysis": [{"type": "grammar", "label": "~와/과 다르다 (to be different from ~)", "exp": "와/과 marks what something is compared with. 우리와 달라요 = (they) are different from ours.", "example_in_sentence": "우리와 달라요"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 다르다 is a 르-irregular word: 다르다 → 달라요 = is different.", "example_in_sentence": "달라요"}]}, {"text": "뱀은 음식을 씹지 않아요.", "translation": "Snakes do not chew food.", "vocab": [{"ko": "음식", "en": "food"}, {"ko": "씹다", "en": "to chew"}], "analysis": [{"type": "grammar", "label": "~지 않다 (not)", "exp": "Makes a verb negative. 씹다 → 씹지 않아요 = do not chew. It means the same as 안 씹어요.", "example_in_sentence": "씹지 않아요"}]}, {"text": "그래서 뱀의 이빨은 뾰족해요.", "translation": "Therefore, a snake''s teeth are pointed.", "vocab": [{"ko": "뾰족하다", "en": "to be pointed/sharp"}], "analysis": [{"type": "expression", "label": "그래서 (therefore/so)", "exp": "Conjunction showing cause-and-effect relationship between two sentences.", "example_in_sentence": "그래서"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 하다 words become 해요: 뾰족하다 → 뾰족해요 = is pointed.", "example_in_sentence": "뾰족해요"}]}, {"text": "독뱀의 이빨은 더 특별해요.", "translation": "A venomous snake''s teeth are even more special.", "vocab": [{"ko": "독뱀", "en": "venomous snake"}, {"ko": "특별하다", "en": "to be special"}], "analysis": [{"type": "grammar", "label": "더 (more)", "exp": "더 before a describing word means ''more''. 더 특별해요 = is more special.", "example_in_sentence": "더 특별해요"}]}, {"text": "이빨 안에 작은 구멍이 있어요.", "translation": "Inside the teeth there is a small hole.", "vocab": [{"ko": "안", "en": "inside"}, {"ko": "작다", "en": "to be small"}, {"ko": "구멍", "en": "hole"}], "analysis": [{"type": "grammar", "label": "~안에 (location postposition)", "exp": "Postposition marking interior location. 이빨 (teeth) + 안에 (inside).", "example_in_sentence": "이빨 안에"}, {"type": "grammar", "label": "있다 (existential/possessive verb)", "exp": "Verb expressing existence or presence. Conjugates to 있어요 in present polite form.", "example_in_sentence": "있어요"}]}, {"text": "이 구멍으로 독이 나와요.", "translation": "Venom comes out through this hole.", "vocab": [{"ko": "독", "en": "venom/poison"}, {"ko": "나오다", "en": "to come out"}], "analysis": [{"type": "grammar", "label": "~(으)로 (through, by)", "exp": "Marks the way or path something goes. After a consonant use 으로: 구멍 → 구멍으로 = through the hole.", "example_in_sentence": "구멍으로"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 나오다 → 나와요 (오 + 아요 becomes 와요) = comes out.", "example_in_sentence": "나와요"}]}, {"text": "뱀은 이빨이 빠져도 괜찮아요.", "translation": "Even if a snake loses its teeth, it is fine.", "vocab": [{"ko": "빠지다", "en": "to fall out/be lost"}, {"ko": "괜찮다", "en": "to be okay/fine"}], "analysis": [{"type": "grammar", "label": "~아/어도 (even if)", "exp": "Means ''even if''. 빠지다 → 빠져도 = even if (the teeth) fall out.", "example_in_sentence": "빠져도"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 괜찮다 → 괜찮아요 = is okay.", "example_in_sentence": "괜찮아요"}]}, {"text": "새로운 이빨이 자라거든요.", "translation": "That''s because new teeth grow back.", "vocab": [{"ko": "새롭다", "en": "to be new"}, {"ko": "자라다", "en": "to grow"}], "analysis": [{"type": "grammar", "label": "~거든요 (causal/explanatory ending)", "exp": "Verb 자라다 + 거든요 provides reason/explanation with friendly tone. Connects to previous negation softly.", "example_in_sentence": "자라거든요"}]}, {"text": "뱀은 평생 이빨이 계속 바뀌어요.", "translation": "Snakes continuously change their teeth throughout their entire life.", "vocab": [{"ko": "평생", "en": "lifetime/whole life"}, {"ko": "계속", "en": "continuously/keep on"}, {"ko": "바뀌다", "en": "to change"}], "analysis": [{"type": "grammar", "label": "~이 (subject particle)", "exp": "Particle marking the subject of verb 바뀌다 within time-duration phrase. 이빨이 (teeth as subject).", "example_in_sentence": "이빨이"}, {"type": "grammar", "label": "~어요 (present tense polite)", "exp": "Verb 바뀌다 conjugates to 바뀌어요. With 계속, expresses habitual/continuous action.", "example_in_sentence": "바뀌어요"}]}, {"text": "우리나라에도 독뱀이 살아요.", "translation": "Venomous snakes also live in our country.", "vocab": [{"ko": "우리나라", "en": "our country"}, {"ko": "살다", "en": "to live/dwell"}], "analysis": [{"type": "grammar", "label": "~에도 (location + also/too postposition)", "exp": "Postposition 에 (location) + 도 (also/too) marks inclusive location. 우리나라에도 (in our country also).", "example_in_sentence": "우리나라에도"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 살다 has ㅏ, so it takes 아요: 살다 → 살아요 = live.", "example_in_sentence": "살아요"}]}, {"text": "산에서 뱀을 만나면 조심해야 해요.", "translation": "If you meet a snake in the mountains, you must be careful.", "vocab": [{"ko": "산", "en": "mountain"}, {"ko": "만나다", "en": "to meet"}, {"ko": "조심하다", "en": "to be careful"}], "analysis": [{"type": "grammar", "label": "~에서 (location postposition)", "exp": "Postposition marking location where action occurs. 산 (mountain) + 에서 (in/at).", "example_in_sentence": "산에서"}, {"type": "grammar", "label": "~(으)면 (if, when)", "exp": "Sets up a condition. 만나다 → 만나면 = if (you) meet.", "example_in_sentence": "만나면"}, {"type": "grammar", "label": "~아/어야 하다 (obligation/necessity)", "exp": "Verb 조심하다 + 아야 + 하다 expresses obligation/necessity. 조심하다 → 조심해야 하다 → 조심해야 해요.", "example_in_sentence": "조심해야 해요"}]}, {"text": "멀리서 지켜보는 것이 좋아요.", "translation": "It is good to watch from a distance.", "vocab": [{"ko": "멀리", "en": "far/at a distance"}, {"ko": "지켜보다", "en": "to watch/observe"}, {"ko": "좋다", "en": "to be good"}], "analysis": [{"type": "grammar", "label": "~는 것 (nominalization)", "exp": "Present participle form 지켜보는 + 것 (thing/act) nominalizes verb phrase into noun. ''watching'' becomes an entity.", "example_in_sentence": "지켜보는 것이"}, {"type": "grammar", "label": "~이 (subject particle)", "exp": "Particle marking subject 것 (thing/act of watching) for predicate adjective 좋다.", "example_in_sentence": "것이"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 좋다 → 좋아요 = is good.", "example_in_sentence": "좋아요"}]}], "version": "s6"}', vocab = '[{"ko": "뱀", "en": "snake", "note": ""}, {"ko": "이빨", "en": "tooth/teeth", "note": ""}, {"ko": "다르다", "en": "to be different", "note": ""}, {"ko": "음식", "en": "food", "note": ""}, {"ko": "씹다", "en": "to chew", "note": ""}, {"ko": "뾰족하다", "en": "to be pointed/sharp", "note": ""}, {"ko": "독뱀", "en": "venomous snake", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "안", "en": "inside", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "구멍", "en": "hole", "note": ""}, {"ko": "독", "en": "venom/poison", "note": ""}, {"ko": "나오다", "en": "to come out", "note": ""}, {"ko": "빠지다", "en": "to fall out/be lost", "note": ""}, {"ko": "괜찮다", "en": "to be okay/fine", "note": ""}, {"ko": "새롭다", "en": "to be new", "note": ""}, {"ko": "자라다", "en": "to grow", "note": ""}, {"ko": "평생", "en": "lifetime/whole life", "note": ""}, {"ko": "계속", "en": "continuously/keep on", "note": ""}, {"ko": "바뀌다", "en": "to change", "note": ""}, {"ko": "우리나라", "en": "our country", "note": ""}, {"ko": "살다", "en": "to live/dwell", "note": ""}, {"ko": "산", "en": "mountain", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "조심하다", "en": "to be careful", "note": ""}, {"ko": "멀리", "en": "far/at a distance", "note": ""}, {"ko": "지켜보다", "en": "to watch/observe", "note": ""}, {"ko": "좋다", "en": "to be good", "note": ""}]', grammar = '{"patterns": [{"name": "~와/과 다르다 (to be different from ~)", "level": "Starter", "exp": "와/과 marks what something is compared with. 우리와 달라요 = (they) are different from ours.", "ex_ko": "뱀의 이빨은 우리와 달라요.", "ex_en": "A snake''s teeth are different from ours."}, {"name": "~아/어요 (polite ending)", "level": "Starter", "exp": "The everyday polite ending. 다르다 is a 르-irregular word: 다르다 → 달라요 = is different.", "ex_ko": "뱀의 이빨은 우리와 달라요.", "ex_en": "A snake''s teeth are different from ours."}, {"name": "~지 않다 (not)", "level": "Starter", "exp": "Makes a verb negative. 씹다 → 씹지 않아요 = do not chew. It means the same as 안 씹어요.", "ex_ko": "뱀은 음식을 씹지 않아요.", "ex_en": "Snakes do not chew food."}, {"name": "더 (more)", "level": "Starter", "exp": "더 before a describing word means ''more''. 더 특별해요 = is more special.", "ex_ko": "독뱀의 이빨은 더 특별해요.", "ex_en": "A venomous snake''s teeth are even more special."}, {"name": "~안에 (location postposition)", "level": "Starter", "exp": "Postposition marking interior location. 이빨 (teeth) + 안에 (inside).", "ex_ko": "이빨 안에 작은 구멍이 있어요.", "ex_en": "Inside the teeth there is a small hole."}, {"name": "있다 (existential/possessive verb)", "level": "Starter", "exp": "Verb expressing existence or presence. Conjugates to 있어요 in present polite form.", "ex_ko": "이빨 안에 작은 구멍이 있어요.", "ex_en": "Inside the teeth there is a small hole."}, {"name": "~(으)로 (through, by)", "level": "Starter", "exp": "Marks the way or path something goes. After a consonant use 으로: 구멍 → 구멍으로 = through the hole.", "ex_ko": "이 구멍으로 독이 나와요.", "ex_en": "Venom comes out through this hole."}, {"name": "~아/어도 (even if)", "level": "Starter", "exp": "Means ''even if''. 빠지다 → 빠져도 = even if (the teeth) fall out.", "ex_ko": "뱀은 이빨이 빠져도 괜찮아요.", "ex_en": "Even if a snake loses its teeth, it is fine."}, {"name": "~거든요 (causal/explanatory ending)", "level": "Starter", "exp": "Verb 자라다 + 거든요 provides reason/explanation with friendly tone. Connects to previous negation softly.", "ex_ko": "새로운 이빨이 자라거든요.", "ex_en": "That''s because new teeth grow back."}, {"name": "~이 (subject particle)", "level": "Starter", "exp": "Particle marking the subject of verb 바뀌다 within time-duration phrase. 이빨이 (teeth as subject).", "ex_ko": "뱀은 평생 이빨이 계속 바뀌어요.", "ex_en": "Snakes continuously change their teeth throughout their entire life."}, {"name": "~어요 (present tense polite)", "level": "Starter", "exp": "Verb 바뀌다 conjugates to 바뀌어요. With 계속, expresses habitual/continuous action.", "ex_ko": "뱀은 평생 이빨이 계속 바뀌어요.", "ex_en": "Snakes continuously change their teeth throughout their entire life."}, {"name": "~에도 (location + also/too postposition)", "level": "Starter", "exp": "Postposition 에 (location) + 도 (also/too) marks inclusive location. 우리나라에도 (in our country also).", "ex_ko": "우리나라에도 독뱀이 살아요.", "ex_en": "Venomous snakes also live in our country."}, {"name": "~에서 (location postposition)", "level": "Starter", "exp": "Postposition marking location where action occurs. 산 (mountain) + 에서 (in/at).", "ex_ko": "산에서 뱀을 만나면 조심해야 해요.", "ex_en": "If you meet a snake in the mountains, you must be careful."}, {"name": "~(으)면 (if, when)", "level": "Starter", "exp": "Sets up a condition. 만나다 → 만나면 = if (you) meet.", "ex_ko": "산에서 뱀을 만나면 조심해야 해요.", "ex_en": "If you meet a snake in the mountains, you must be careful."}, {"name": "~아/어야 하다 (obligation/necessity)", "level": "Starter", "exp": "Verb 조심하다 + 아야 + 하다 expresses obligation/necessity. 조심하다 → 조심해야 하다 → 조심해야 해요.", "ex_ko": "산에서 뱀을 만나면 조심해야 해요.", "ex_en": "If you meet a snake in the mountains, you must be careful."}]}', updated_at = now() where article_id = 'mol551apob72' and md5(translation) = '867453a447e7f1de1e9effe0c9cf61d1';
update public.article_cache set translation = '{"texts": ["In Japan, fish is not eaten right after it is caught. Freshly caught fish is too fresh, so it doesn''t taste good.", "After fish is caught, it is kept in a cold place for several days. This makes the fish''s muscles become soft. The taste also becomes better.", "In Korea, fish restaurants also use this method. Good sushi restaurants don''t serve fish right away. They age it appropriately and then serve it to customers.", "Fish that is too fresh is tough and tasteless. It needs to take some time to become truly delicious sashimi. This is the secret of fish cooking."], "sentences": [{"text": "일본에서는 생선을 잡자마자 바로 먹지 않아요.", "translation": "In Japan, people don''t eat fish right after catching it.", "vocab": [{"ko": "생선", "en": "fish"}, {"ko": "잡다", "en": "to catch"}, {"ko": "바로", "en": "immediately, right away"}], "analysis": [{"type": "grammar", "label": "~자마자", "exp": "Connective suffix indicating ''immediately after'' or ''as soon as''. The action in the first clause is followed immediately by the action in the second clause.", "example_in_sentence": "잡자마자"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. Attached to verb stem to express ''do not'' or ''not do''. Here combined with ~아요 for polite present tense.", "example_in_sentence": "먹지 않아요"}]}, {"text": "갓 잡은 생선은 너무 신선해서 맛이 좋지 않거든요.", "translation": "That''s because freshly caught fish is too fresh and doesn''t taste good.", "vocab": [{"ko": "갓", "en": "just now, freshly"}, {"ko": "신선하다", "en": "to be fresh"}, {"ko": "맛", "en": "taste, flavor"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun with a past action. 잡다 → 잡은 생선 = fish that was caught.", "example_in_sentence": "잡은 생선"}, {"type": "grammar", "label": "~아/어서", "exp": "Connective suffix showing cause or reason. Indicates that the first clause leads to or causes the result in the second clause.", "example_in_sentence": "신선해서"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. Expresses ''is not'' or ''is not good'' when attached to adjective.", "example_in_sentence": "좋지 않거든요"}]}, {"text": "생선을 잡은 후에는 며칠 동안 차가운 곳에 두어요.", "translation": "After catching fish, people keep it in a cold place for several days.", "vocab": [{"ko": "후", "en": "after"}, {"ko": "며칠", "en": "several days, a few days"}, {"ko": "차갑다", "en": "to be cold"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후에 (after ~ing)", "exp": "Shows that one action comes after another. 잡다 → 잡은 후에 = after catching.", "example_in_sentence": "잡은 후에"}, {"type": "expression", "label": "~ 동안", "exp": "Temporal marker indicating duration; ''for'' or ''during'' a period of time.", "example_in_sentence": "며칠 동안"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 차갑다 (ㅂ irregular) → 차가운 곳 = a cold place.", "example_in_sentence": "차가운 곳"}]}, {"text": "이렇게 하면 생선의 근육이 부드러워져요.", "translation": "If done this way, the fish''s muscle becomes soft.", "vocab": [{"ko": "근육", "en": "muscle"}, {"ko": "부드럽다", "en": "to be soft, tender"}], "analysis": [{"type": "grammar", "label": "~(으)면 (if, when)", "exp": "Sets up a condition. 하다 → 이렇게 하면 = if (you) do it this way.", "example_in_sentence": "이렇게 하면"}, {"type": "grammar", "label": "~아/어지다 (to become ~)", "exp": "Shows a change of state. 부드럽다 (ㅂ irregular) → 부드러워지다 = to become soft → 부드러워져요.", "example_in_sentence": "부드러워져요"}]}, {"text": "맛도 더 좋아집니다.", "translation": "The taste also becomes better.", "vocab": [{"ko": "더", "en": "more, further"}], "analysis": [{"type": "grammar", "label": "~아/어지다", "exp": "Auxiliary expressing change of state: ''becomes good''. ~ㅂ니다 is formal polite ending.", "example_in_sentence": "좋아집니다"}]}, {"text": "한국에서도 횟집에서 이런 방법을 사용해요.", "translation": "In Korea too, sushi restaurants use this method.", "vocab": [{"ko": "횟집", "en": "sushi/raw fish restaurant"}, {"ko": "방법", "en": "method, way"}, {"ko": "사용하다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "도 (topic/focus particle)", "exp": "Additive particle meaning ''also'' or ''too''. Indicates that Korea is another place where this happens.", "example_in_sentence": "한국에서도"}]}, {"text": "좋은 횟집은 생선을 바로 내지 않아요.", "translation": "Good sushi restaurants don''t serve fish right away.", "vocab": [{"ko": "내다", "en": "to serve, to put out"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 좋다 → 좋은 횟집 = a good raw fish restaurant.", "example_in_sentence": "좋은 횟집"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. Expresses ''do not serve'' in polite present tense.", "example_in_sentence": "내지 않아요"}]}, {"text": "적당히 숙성시킨 후에 손님에게 줍니다.", "translation": "After aging it appropriately, they give it to customers.", "vocab": [{"ko": "적당하다", "en": "to be appropriate, moderate"}, {"ko": "숙성시키다", "en": "to age, to mature"}, {"ko": "손님", "en": "customer, guest"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후에 (after ~ing)", "exp": "Shows that one action comes after another. 숙성시키다 → 숙성시킨 후에 = after aging (it).", "example_in_sentence": "숙성시킨 후에"}, {"type": "grammar", "label": "~에게", "exp": "Dative particle marking the indirect object or recipient. Here: ''to customers''.", "example_in_sentence": "손님에게"}]}, {"text": "너무 신선한 생선은 질기고 맛이 없어요.", "translation": "Fish that is too fresh is tough and doesn''t taste good.", "vocab": [{"ko": "질기다", "en": "to be tough, chewy"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 신선하다 → 신선한 생선 = fresh fish.", "example_in_sentence": "신선한 생선"}, {"type": "grammar", "label": "~고", "exp": "Connective suffix listing multiple qualities or actions. Here links ''tough'' and ''has no taste''.", "example_in_sentence": "질기고"}]}, {"text": "조금 시간이 지나야 진짜 맛있는 회가 돼요.", "translation": "Some time must pass for raw fish to become truly delicious.", "vocab": [{"ko": "지나다", "en": "to pass (time)"}, {"ko": "회", "en": "raw fish, sashimi"}], "analysis": [{"type": "grammar", "label": "~아/어야 (only if, only when)", "exp": "Means the second part happens only after the first. 지나다 → 지나야 = only when (time) passes.", "example_in_sentence": "지나야"}, {"type": "grammar", "label": "~는 (modifier for 있다/없다 words)", "exp": "Words ending in 있다/없다 take ~는 before a noun. 맛있다 → 맛있는 회 = delicious raw fish.", "example_in_sentence": "맛있는 회"}]}, {"text": "이것이 생선 요리의 비밀이에요.", "translation": "This is the secret of fish cooking.", "vocab": [{"ko": "비밀", "en": "secret"}], "analysis": [{"type": "grammar", "label": "~이다", "exp": "Copula (linking verb) marking predicate nominative. ~이에요 is polite present form.", "example_in_sentence": "이에요"}]}], "version": "s6"}', vocab = '[{"ko": "생선", "en": "fish", "note": ""}, {"ko": "잡다", "en": "to catch", "note": ""}, {"ko": "바로", "en": "immediately, right away", "note": ""}, {"ko": "갓", "en": "just now, freshly", "note": ""}, {"ko": "신선하다", "en": "to be fresh", "note": ""}, {"ko": "맛", "en": "taste, flavor", "note": ""}, {"ko": "후", "en": "after", "note": ""}, {"ko": "며칠", "en": "several days, a few days", "note": ""}, {"ko": "차갑다", "en": "to be cold", "note": ""}, {"ko": "근육", "en": "muscle", "note": ""}, {"ko": "부드럽다", "en": "to be soft, tender", "note": ""}, {"ko": "더", "en": "more, further", "note": ""}, {"ko": "횟집", "en": "sushi/raw fish restaurant", "note": ""}, {"ko": "방법", "en": "method, way", "note": ""}, {"ko": "사용하다", "en": "to use", "note": ""}, {"ko": "내다", "en": "to serve, to put out", "note": ""}, {"ko": "적당하다", "en": "to be appropriate, moderate", "note": ""}, {"ko": "숙성시키다", "en": "to age, to mature", "note": ""}, {"ko": "손님", "en": "customer, guest", "note": ""}, {"ko": "질기다", "en": "to be tough, chewy", "note": ""}, {"ko": "지나다", "en": "to pass (time)", "note": ""}, {"ko": "회", "en": "raw fish, sashimi", "note": ""}, {"ko": "비밀", "en": "secret", "note": ""}]', grammar = '{"patterns": [{"name": "~자마자", "level": "Beginner", "exp": "Connective suffix indicating ''immediately after'' or ''as soon as''. The action in the first clause is followed immediately by the action in the second clause.", "ex_ko": "일본에서는 생선을 잡자마자 바로 먹지 않아요.", "ex_en": "In Japan, people don''t eat fish right after catching it."}, {"name": "~지 않다", "level": "Beginner", "exp": "Negation pattern. Attached to verb stem to express ''do not'' or ''not do''. Here combined with ~아요 for polite present tense.", "ex_ko": "일본에서는 생선을 잡자마자 바로 먹지 않아요.", "ex_en": "In Japan, people don''t eat fish right after catching it."}, {"name": "~(으)ㄴ (past noun modifier)", "level": "Beginner", "exp": "Describing words take ~(으)ㄴ before a noun. 차갑다 (ㅂ irregular) → 차가운 곳 = a cold place.", "ex_ko": "갓 잡은 생선은 너무 신선해서 맛이 좋지 않거든요.", "ex_en": "That''s because freshly caught fish is too fresh and doesn''t taste good."}, {"name": "~아/어서", "level": "Beginner", "exp": "Connective suffix showing cause or reason. Indicates that the first clause leads to or causes the result in the second clause.", "ex_ko": "갓 잡은 생선은 너무 신선해서 맛이 좋지 않거든요.", "ex_en": "That''s because freshly caught fish is too fresh and doesn''t taste good."}, {"name": "~(으)ㄴ 후에 (after ~ing)", "level": "Beginner", "exp": "Shows that one action comes after another. 숙성시키다 → 숙성시킨 후에 = after aging (it).", "ex_ko": "생선을 잡은 후에는 며칠 동안 차가운 곳에 두어요.", "ex_en": "After catching fish, people keep it in a cold place for several days."}, {"name": "~(으)면 (if, when)", "level": "Beginner", "exp": "Sets up a condition. 하다 → 이렇게 하면 = if (you) do it this way.", "ex_ko": "이렇게 하면 생선의 근육이 부드러워져요.", "ex_en": "If done this way, the fish''s muscle becomes soft."}, {"name": "~아/어지다 (to become ~)", "level": "Beginner", "exp": "Auxiliary expressing change of state: ''becomes good''. ~ㅂ니다 is formal polite ending.", "ex_ko": "이렇게 하면 생선의 근육이 부드러워져요.", "ex_en": "If done this way, the fish''s muscle becomes soft."}, {"name": "도 (topic/focus particle)", "level": "Beginner", "exp": "Additive particle meaning ''also'' or ''too''. Indicates that Korea is another place where this happens.", "ex_ko": "한국에서도 횟집에서 이런 방법을 사용해요.", "ex_en": "In Korea too, sushi restaurants use this method."}, {"name": "~에게", "level": "Beginner", "exp": "Dative particle marking the indirect object or recipient. Here: ''to customers''.", "ex_ko": "적당히 숙성시킨 후에 손님에게 줍니다.", "ex_en": "After aging it appropriately, they give it to customers."}, {"name": "~고", "level": "Beginner", "exp": "Connective suffix listing multiple qualities or actions. Here links ''tough'' and ''has no taste''.", "ex_ko": "너무 신선한 생선은 질기고 맛이 없어요.", "ex_en": "Fish that is too fresh is tough and doesn''t taste good."}, {"name": "~아/어야 (only if, only when)", "level": "Beginner", "exp": "Means the second part happens only after the first. 지나다 → 지나야 = only when (time) passes.", "ex_ko": "조금 시간이 지나야 진짜 맛있는 회가 돼요.", "ex_en": "Some time must pass for raw fish to become truly delicious."}, {"name": "~는 (modifier for 있다/없다 words)", "level": "Beginner", "exp": "Words ending in 있다/없다 take ~는 before a noun. 맛있다 → 맛있는 회 = delicious raw fish.", "ex_ko": "조금 시간이 지나야 진짜 맛있는 회가 돼요.", "ex_en": "Some time must pass for raw fish to become truly delicious."}, {"name": "~이다", "level": "Beginner", "exp": "Copula (linking verb) marking predicate nominative. ~이에요 is polite present form.", "ex_ko": "이것이 생선 요리의 비밀이에요.", "ex_en": "This is the secret of fish cooking."}]}', updated_at = now() where article_id = 'mol55or2yp3o' and md5(translation) = '3f6a037766aecd01b80c3e3c7a12d9d2';
update public.article_cache set translation = '{"texts": ["Recently, CEOs of overseas technology companies have been using robot dogs for work. These robot dogs are helping with various tasks in offices.", "Robot dogs move using artificial intelligence (AI) technology. They can walk and run like people, and they can also transport objects. Additionally, they can handle security tasks.", "Robot technology is also developing rapidly in Korea. Many companies are showing interest in business automation using robots.", "Experts predict that robots will be used in more fields in the future. However, research on how people and robots can work together is also necessary."], "sentences": [{"text": "최근 해외 기술 회사 최고경영자(CEO)들이 로봇 개를 업무에 활용하고 있어요.", "translation": "Recently, CEOs of foreign technology companies are utilizing robot dogs in their work.", "vocab": [{"ko": "최고경영자", "en": "CEO; chief executive officer"}, {"ko": "활용하다", "en": "to utilize; to make use of"}, {"ko": "업무", "en": "work; business; task"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Present continuous/progressive aspect. Indicates an ongoing action. Formed: verb stem + -고 있- + ending.", "example_in_sentence": "활용하고 있어요"}]}, {"text": "이 로봇 개들은 사무실에서 다양한 일을 도와주고 있습니다.", "translation": "These robot dogs are helping with various tasks in the office.", "vocab": [{"ko": "로봇", "en": "robot"}, {"ko": "사무실", "en": "office"}, {"ko": "다양하다", "en": "to be various; to be diverse"}], "analysis": [{"type": "grammar", "label": "~고 있습니다", "exp": "Formal present continuous. Same progressive aspect as ~고 있어요 but with formal ending -습니다.", "example_in_sentence": "도와주고 있습니다"}]}, {"text": "로봇 개는 인공지능(AI) 기술로 움직여요.", "translation": "Robot dogs move by artificial intelligence technology.", "vocab": [{"ko": "인공지능", "en": "artificial intelligence; AI"}, {"ko": "움직이다", "en": "to move; to operate"}], "analysis": [{"type": "grammar", "label": "~(으)로 (by means of)", "exp": "Marks the means used to do something. 기술로 움직여요 = moves using (AI) technology.", "example_in_sentence": "기술로 움직여요"}]}, {"text": "사람처럼 걷고 뛸 수 있고, 물건을 운반할 수도 있습니다.", "translation": "They can walk and run like humans, and can also transport objects.", "vocab": [{"ko": "걷다", "en": "to walk"}, {"ko": "뛰다", "en": "to run"}, {"ko": "운반하다", "en": "to transport; to carry"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Expresses ability. 뛰다 → 뛸 수 있다 = can run.", "example_in_sentence": "걷고 뛸 수 있고"}, {"type": "grammar", "label": "~(으)ㄹ 수도 있다 (can also)", "exp": "도 adds ''also'' to ~(으)ㄹ 수 있다. 운반하다 → 운반할 수도 있습니다 = can also carry.", "example_in_sentence": "운반할 수도 있습니다"}]}, {"text": "또한 보안 업무도 담당할 수 있어요.", "translation": "Also, they can handle security tasks.", "vocab": [{"ko": "보안", "en": "security"}, {"ko": "담당하다", "en": "to be in charge of; to handle"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Expresses ability. 담당하다 → 담당할 수 있어요 = can handle.", "example_in_sentence": "담당할 수 있어요"}]}, {"text": "한국에서도 로봇 기술이 빠르게 발전하고 있어요.", "translation": "Robot technology is also developing rapidly in Korea.", "vocab": [{"ko": "발전하다", "en": "to develop; to advance; to progress"}, {"ko": "빠르게", "en": "rapidly; quickly"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Present continuous/progressive aspect. Formed: verb stem + -고 있- + informal ending -어요.", "example_in_sentence": "발전하고 있어요"}]}, {"text": "많은 기업들이 로봇을 활용한 업무 자동화에 관심을 보이고 있습니다.", "translation": "Many companies are showing interest in task automation using robots.", "vocab": [{"ko": "자동화", "en": "automation"}, {"ko": "관심", "en": "interest; concern"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun that follows. 활용하다 → 로봇을 활용한 업무 자동화 = automation of work using robots.", "example_in_sentence": "로봇을 활용한 업무"}, {"type": "expression", "label": "관심을 보이다", "exp": "Collocation meaning ''to show interest; to display interest''. Direct object 관심 + 동사 보이다.", "example_in_sentence": "관심을 보이고 있습니다"}]}, {"text": "전문가들은 앞으로 로봇이 더 많은 분야에서 사용될 것이라고 예상해요.", "translation": "Experts anticipate that robots will be used in more fields in the future.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "분야", "en": "field; area; domain"}, {"ko": "예상하다", "en": "to anticipate; to expect; to forecast"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것이다", "exp": "Future tense/supposition. Expresses what will happen or what is expected. Formed: verb stem + -(으)ㄹ 것이- + ending.", "example_in_sentence": "사용될 것이라고"}, {"type": "grammar", "label": "~(이)라고 예상하다 (to expect that ~)", "exp": "Reports what someone expects. 것이다 → 것이라고 예상해요 = expect that (it) will ...", "example_in_sentence": "것이라고 예상해요"}]}, {"text": "하지만 사람과 로봇이 함께 일하는 방법에 대한 연구도 필요합니다.", "translation": "However, research on how humans and robots work together is also necessary.", "vocab": [{"ko": "함께", "en": "together; with"}, {"ko": "방법", "en": "method; way; means"}, {"ko": "연구", "en": "research; study"}], "analysis": [{"type": "grammar", "label": "~는 (present noun modifier)", "exp": "Describes the noun that follows. 일하다 → 함께 일하는 방법 = how (people and robots) work together.", "example_in_sentence": "일하는 방법"}, {"type": "grammar", "label": "~에 대한 (about; regarding; on)", "exp": "Expresses the target or topic of an action. ~에 대하다 → ~에 대한 (attributive). Here: 방법에 대한 연구 (research about/on the method).", "example_in_sentence": "방법에 대한 연구"}]}], "version": "s6"}', vocab = '[{"ko": "최고경영자", "en": "CEO; chief executive officer", "note": ""}, {"ko": "활용하다", "en": "to utilize; to make use of", "note": ""}, {"ko": "업무", "en": "work; business; task", "note": ""}, {"ko": "로봇", "en": "robot", "note": ""}, {"ko": "사무실", "en": "office", "note": ""}, {"ko": "다양하다", "en": "to be various; to be diverse", "note": ""}, {"ko": "인공지능", "en": "artificial intelligence; AI", "note": ""}, {"ko": "움직이다", "en": "to move; to operate", "note": ""}, {"ko": "걷다", "en": "to walk", "note": ""}, {"ko": "뛰다", "en": "to run", "note": ""}, {"ko": "운반하다", "en": "to transport; to carry", "note": ""}, {"ko": "보안", "en": "security", "note": ""}, {"ko": "담당하다", "en": "to be in charge of; to handle", "note": ""}, {"ko": "발전하다", "en": "to develop; to advance; to progress", "note": ""}, {"ko": "빠르게", "en": "rapidly; quickly", "note": ""}, {"ko": "자동화", "en": "automation", "note": ""}, {"ko": "관심", "en": "interest; concern", "note": ""}, {"ko": "전문가", "en": "expert; specialist", "note": ""}, {"ko": "분야", "en": "field; area; domain", "note": ""}, {"ko": "예상하다", "en": "to anticipate; to expect; to forecast", "note": ""}, {"ko": "함께", "en": "together; with", "note": ""}, {"ko": "방법", "en": "method; way; means", "note": ""}, {"ko": "연구", "en": "research; study", "note": ""}, {"word": "도와주다", "reading": "dowajuda", "meaning": "to help; to assist", "context": "로봇 개들은 사무실에서 다양한 일을 도와주고"}, {"word": "관심을 보이다", "reading": "gwansimeul boyida", "meaning": "to show interest", "context": "로봇을 활용한 업무 자동화에 관심을 보이고 있습니다"}]', grammar = '{"patterns": [{"name": "~고 있어요", "level": "Intermediate", "exp": "Present continuous/progressive aspect. Indicates an ongoing action. Formed: verb stem + -고 있- + ending.", "ex_ko": "최근 해외 기술 회사 최고경영자(CEO)들이 로봇 개를 업무에 활용하고 있어요.", "ex_en": "Recently, CEOs of foreign technology companies are utilizing robot dogs in their work."}, {"name": "~고 있습니다", "level": "Intermediate", "exp": "Formal present continuous. Same progressive aspect as ~고 있어요 but with formal ending -습니다.", "ex_ko": "이 로봇 개들은 사무실에서 다양한 일을 도와주고 있습니다.", "ex_en": "These robot dogs are helping with various tasks in the office."}, {"name": "~(으)로 (by means of)", "level": "Intermediate", "exp": "Marks the means used to do something. 기술로 움직여요 = moves using (AI) technology.", "ex_ko": "로봇 개는 인공지능(AI) 기술로 움직여요.", "ex_en": "Robot dogs move by artificial intelligence technology."}, {"name": "~(으)ㄹ 수 있다 (can)", "level": "Intermediate", "exp": "Expresses ability. 담당하다 → 담당할 수 있어요 = can handle.", "ex_ko": "사람처럼 걷고 뛸 수 있고, 물건을 운반할 수도 있습니다.", "ex_en": "They can walk and run like humans, and can also transport objects."}, {"name": "~(으)ㄹ 수도 있다 (can also)", "level": "Intermediate", "exp": "도 adds ''also'' to ~(으)ㄹ 수 있다. 운반하다 → 운반할 수도 있습니다 = can also carry.", "ex_ko": "사람처럼 걷고 뛸 수 있고, 물건을 운반할 수도 있습니다.", "ex_en": "They can walk and run like humans, and can also transport objects."}, {"name": "~(으)ㄴ (past noun modifier)", "level": "Intermediate", "exp": "Describes the noun that follows. 활용하다 → 로봇을 활용한 업무 자동화 = automation of work using robots.", "ex_ko": "많은 기업들이 로봇을 활용한 업무 자동화에 관심을 보이고 있습니다.", "ex_en": "Many companies are showing interest in task automation using robots."}, {"name": "~(으)ㄹ 것이다", "level": "Intermediate", "exp": "Future tense/supposition. Expresses what will happen or what is expected. Formed: verb stem + -(으)ㄹ 것이- + ending.", "ex_ko": "전문가들은 앞으로 로봇이 더 많은 분야에서 사용될 것이라고 예상해요.", "ex_en": "Experts anticipate that robots will be used in more fields in the future."}, {"name": "~(이)라고 예상하다 (to expect that ~)", "level": "Intermediate", "exp": "Reports what someone expects. 것이다 → 것이라고 예상해요 = expect that (it) will ...", "ex_ko": "전문가들은 앞으로 로봇이 더 많은 분야에서 사용될 것이라고 예상해요.", "ex_en": "Experts anticipate that robots will be used in more fields in the future."}, {"name": "~는 (present noun modifier)", "level": "Intermediate", "exp": "Describes the noun that follows. 일하다 → 함께 일하는 방법 = how (people and robots) work together.", "ex_ko": "하지만 사람과 로봇이 함께 일하는 방법에 대한 연구도 필요합니다.", "ex_en": "However, research on how humans and robots work together is also necessary."}, {"name": "~에 대한 (about; regarding; on)", "level": "Intermediate", "exp": "Expresses the target or topic of an action. ~에 대하다 → ~에 대한 (attributive). Here: 방법에 대한 연구 (research about/on the method).", "ex_ko": "하지만 사람과 로봇이 함께 일하는 방법에 대한 연구도 필요합니다.", "ex_en": "However, research on how humans and robots work together is also necessary."}]}', updated_at = now() where article_id = 'molixcm2wukl' and md5(translation) = 'e4dd08db93a3cf136ea83853bd2f283b';
update public.article_cache set translation = '{"texts": ["A person who was diving in the sea met an octopus. The diver played around by touching the octopus. However, the octopus didn''t stay still. The octopus grabbed the diver tightly. The octopus''s arms clung to the diver''s body. The diver tried to escape from the octopus. But the octopus didn''t let go easily. The octopus grabbed even more strongly. In the end, the diver managed to escape with difficulty. He learned that you shouldn''t carelessly touch sea animals. The octopus is a smart animal that knows how to protect itself.", "Korea''s teacher shortage becomes serious, causing disruption to school classes", "What is an \"anxiety bag\"? A popular trend", "The US and China resume talks over trade issues", "\"Talking pig\" becomes a social media star", "The \"nothing maxing\" trend of doing nothing spreads"], "sentences": [{"text": "바다에서 잠수를 하던 사람이 문어를 만났어요.", "translation": "A person who was diving in the sea met an octopus.", "vocab": [{"ko": "바다", "en": "sea"}, {"ko": "잠수", "en": "diving"}, {"ko": "문어", "en": "octopus"}, {"ko": "만나다", "en": "to meet"}], "analysis": [{"type": "grammar", "label": "~던", "exp": "Past progressive modifier. Describes an ongoing or habitual action in the past. 하다 (to do) + 던 = 하던 (was doing/used to do).", "example_in_sentence": "잠수를 하던"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. Marks completed action in informal-polite style. 만나다 → 만났어요.", "example_in_sentence": "만났어요"}]}, {"text": "잠수부는 문어를 건드리며 놀았어요.", "translation": "The diver played with the octopus, touching it.", "vocab": [{"ko": "잠수부", "en": "diver"}, {"ko": "건드리다", "en": "to touch"}, {"ko": "놀다", "en": "to play"}], "analysis": [{"type": "grammar", "label": "~며", "exp": "Connective suffix expressing simultaneous or sequential action. 건드리다 + 며 = 건드리며 (while touching / and then).", "example_in_sentence": "건드리며"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 놀다 → 놀았어요.", "example_in_sentence": "놀았어요"}]}, {"text": "하지만 문어는 가만히 있지 않았어요.", "translation": "However, the octopus did not stay still.", "vocab": [{"ko": "하지만", "en": "but; however"}, {"ko": "가만히", "en": "quietly; still; calmly"}, {"ko": "있다", "en": "to stay"}], "analysis": [{"type": "expression", "label": "~지 않다", "exp": "Negation pattern. Negates the preceding predicate. 있다 + 지 않다 = 있지 않다 (not to be/stay).", "example_in_sentence": "있지 않았어요"}]}, {"text": "문어가 잠수부를 꽉 붙잡았어요.", "translation": "The octopus firmly grabbed the diver.", "vocab": [{"ko": "꽉", "en": "firmly; tightly"}, {"ko": "붙잡다", "en": "to grab; to hold"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 붙잡다 → 붙잡았어요.", "example_in_sentence": "붙잡았어요"}]}, {"text": "문어의 다리가 잠수부 몸에 달라붙었어요.", "translation": "The octopus''s legs clung to the diver''s body.", "vocab": [{"ko": "다리", "en": "leg; arm (of octopus/squid)"}, {"ko": "몸", "en": "body"}, {"ko": "달라붙다", "en": "to cling; to stick"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 달라붙다 → 달라붙었어요.", "example_in_sentence": "달라붙었어요"}]}, {"text": "잠수부는 문어에서 벗어나려고 했어요.", "translation": "The diver tried to escape from the octopus.", "vocab": [{"ko": "벗어나다", "en": "to escape; to get away"}], "analysis": [{"type": "grammar", "label": "~(으)려고 하다 (to try to)", "exp": "Shows an attempt or intention. 벗어나다 → 벗어나려고 했어요 = tried to escape.", "example_in_sentence": "벗어나려고 했어요"}]}, {"text": "하지만 문어는 쉽게 놓아주지 않았어요.", "translation": "However, the octopus did not let go easily.", "vocab": [{"ko": "쉽게", "en": "easily"}, {"ko": "놓아주다", "en": "to let go; to release"}], "analysis": [{"type": "expression", "label": "~지 않다", "exp": "Negation pattern. 놓아주다 + 지 않다 = 놓아주지 않다 (not to let go).", "example_in_sentence": "놓아주지 않았어요"}]}, {"text": "문어가 더 세게 붙잡았어요.", "translation": "The octopus grabbed even harder.", "vocab": [{"ko": "더", "en": "more; even"}, {"ko": "세게", "en": "strongly; hard"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 붙잡다 → 붙잡았어요.", "example_in_sentence": "붙잡았어요"}]}, {"text": "결국 잠수부는 힘들게 도망쳤어요.", "translation": "Eventually, the diver escaped with difficulty.", "vocab": [{"ko": "결국", "en": "eventually; in the end"}, {"ko": "힘들게", "en": "with difficulty; struggling"}, {"ko": "도망치다", "en": "to escape; to flee"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 도망치다 → 도망쳤어요.", "example_in_sentence": "도망쳤어요"}]}, {"text": "바다 동물들을 함부로 건드리면 안 된다는 걸 배웠어요.", "translation": "The diver learned that one should not carelessly touch sea animals.", "vocab": [{"ko": "함부로", "en": "carelessly; recklessly"}, {"ko": "배우다", "en": "to learn"}], "analysis": [{"type": "expression", "label": "~(으)면 안 되다 (must not)", "exp": "Says something is not allowed. 건드리다 → 건드리면 안 된다 = (you) must not touch.", "example_in_sentence": "건드리면 안 된다"}, {"type": "grammar", "label": "~다는 것 (the fact that ~)", "exp": "Turns a statement into a noun. 안 된다 → 안 된다는 걸 (= 것을) 배웠어요 = learned that (you) must not.", "example_in_sentence": "안 된다는 걸"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 배우다 → 배웠어요.", "example_in_sentence": "배웠어요"}]}, {"text": "문어도 자기를 지킬 줄 아는 똑똑한 동물이에요.", "translation": "The octopus is also a smart animal that knows how to protect itself.", "vocab": [{"ko": "자기", "en": "self; oneself"}, {"ko": "지키다", "en": "to protect; to guard"}, {"ko": "똑똑하다", "en": "to be smart"}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 줄 알다 (to know how to)", "exp": "Says someone knows how to do something. 지키다 → 지킬 줄 아는 동물 = an animal that knows how to protect (itself).", "example_in_sentence": "지킬 줄 아는"}, {"type": "grammar", "label": "이에요", "exp": "Polite present tense copula. Links subject and predicate noun. 동물 + 이에요 = 동물이에요 (is an animal).", "example_in_sentence": "동물이에요"}]}], "version": "s6"}', vocab = '[{"ko": "바다", "en": "sea", "note": ""}, {"ko": "잠수", "en": "diving", "note": ""}, {"ko": "문어", "en": "octopus", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "잠수부", "en": "diver", "note": ""}, {"ko": "건드리다", "en": "to touch", "note": ""}, {"ko": "놀다", "en": "to play", "note": ""}, {"ko": "하지만", "en": "but; however", "note": ""}, {"ko": "가만히", "en": "quietly; still; calmly", "note": ""}, {"ko": "있다", "en": "to stay", "note": ""}, {"ko": "꽉", "en": "firmly; tightly", "note": ""}, {"ko": "붙잡다", "en": "to grab; to hold", "note": ""}, {"ko": "다리", "en": "leg; arm (of octopus/squid)", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "달라붙다", "en": "to cling; to stick", "note": ""}, {"ko": "벗어나다", "en": "to escape; to get away", "note": ""}, {"ko": "쉽게", "en": "easily", "note": ""}, {"ko": "놓아주다", "en": "to let go; to release", "note": ""}, {"ko": "더", "en": "more; even", "note": ""}, {"ko": "세게", "en": "strongly; hard", "note": ""}, {"ko": "결국", "en": "eventually; in the end", "note": ""}, {"ko": "힘들게", "en": "with difficulty; struggling", "note": ""}, {"ko": "도망치다", "en": "to escape; to flee", "note": ""}, {"ko": "함부로", "en": "carelessly; recklessly", "note": ""}, {"ko": "배우다", "en": "to learn", "note": ""}, {"ko": "자기", "en": "self; oneself", "note": ""}, {"ko": "지키다", "en": "to protect; to guard", "note": ""}, {"ko": "똑똑하다", "en": "to be smart", "note": ""}]', grammar = '{"patterns": [{"name": "~던", "level": "Beginner", "exp": "Past progressive modifier. Describes an ongoing or habitual action in the past. 하다 (to do) + 던 = 하던 (was doing/used to do).", "ex_ko": "바다에서 잠수를 하던 사람이 문어를 만났어요.", "ex_en": "A person who was diving in the sea met an octopus."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense polite ending. Marks completed action in informal-polite style. 만나다 → 만났어요.", "ex_ko": "바다에서 잠수를 하던 사람이 문어를 만났어요.", "ex_en": "A person who was diving in the sea met an octopus."}, {"name": "~며", "level": "Beginner", "exp": "Connective suffix expressing simultaneous or sequential action. 건드리다 + 며 = 건드리며 (while touching / and then).", "ex_ko": "잠수부는 문어를 건드리며 놀았어요.", "ex_en": "The diver played with the octopus, touching it."}, {"name": "~(으)려고 하다 (to try to)", "level": "Beginner", "exp": "Shows an attempt or intention. 벗어나다 → 벗어나려고 했어요 = tried to escape.", "ex_ko": "잠수부는 문어에서 벗어나려고 했어요.", "ex_en": "The diver tried to escape from the octopus."}, {"name": "~다는 것 (the fact that ~)", "level": "Beginner", "exp": "Turns a statement into a noun. 안 된다 → 안 된다는 걸 (= 것을) 배웠어요 = learned that (you) must not.", "ex_ko": "바다 동물들을 함부로 건드리면 안 된다는 걸 배웠어요.", "ex_en": "The diver learned that one should not carelessly touch sea animals."}, {"name": "이에요", "level": "Beginner", "exp": "Polite present tense copula. Links subject and predicate noun. 동물 + 이에요 = 동물이에요 (is an animal).", "ex_ko": "문어도 자기를 지킬 줄 아는 똑똑한 동물이에요.", "ex_en": "The octopus is also a smart animal that knows how to protect itself."}]}', updated_at = now() where article_id = 'molixxu9o718' and md5(translation) = 'd9105afc822b8db34e8ffa29da948d56';
update public.article_cache set translation = '{"texts": ["A chicken''s head is truly amazing. Even when its body shakes, its head stays in place. It''s like magic. People who make cameras found this out. A chicken''s head is more stable than a camera tool that costs 5 million won. It''s really surprising. This camera tool is called a gimbal. It''s a tool for taking photos without shaking. But chickens do it better. Animals have many special abilities that we don''t know about. A chicken is one of them. Nature is truly amazing.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "닭의 머리는 정말 신기해요.", "translation": "A chicken''s head is really amazing.", "vocab": [{"ko": "닭", "en": "chicken"}, {"ko": "머리", "en": "head"}, {"ko": "신기하다", "en": "to be amazing/fascinating"}], "analysis": [{"type": "grammar", "label": "~해요 (polite form of 하다 words)", "exp": "하다 words become 해요 in the everyday polite form. 신기하다 → 신기해요 = is amazing.", "example_in_sentence": "신기해요"}, {"type": "grammar", "label": "~의 (possessive particle)", "exp": "Shows possession or belonging. Connects noun to noun. 닭 + 의 = 닭의 (chicken''s).", "example_in_sentence": "닭의"}]}, {"text": "몸이 흔들려도 머리는 그대로 있어요.", "translation": "Even if the body sways, the head stays still.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "흔들리다", "en": "to sway/shake"}, {"ko": "그대로", "en": "as is/unchanged"}], "analysis": [{"type": "grammar", "label": "~어도 / ~아도", "exp": "Concessive/contrastive suffix meaning ''even if'' or ''even though''. Indicates an action/state happens regardless of the condition. 흔들리 + 어도 = 흔들려도.", "example_in_sentence": "흔들려도"}, {"type": "grammar", "label": "그대로 있다 (to stay as it is)", "exp": "그대로 (as it is) + 있다 (to stay) = to stay still. 있다 → 있어요.", "example_in_sentence": "그대로 있어요"}]}, {"text": "마치 마법 같아요.", "translation": "It''s like magic.", "vocab": [{"ko": "마치", "en": "as if/just like"}, {"ko": "마법", "en": "magic"}], "analysis": [{"type": "grammar", "label": "~ 같다 (to be like ~)", "exp": "Noun + 같다 means ''to be like''. 마법 같아요 = it''s like magic. 마치 adds ''just as if''.", "example_in_sentence": "마법 같아요"}]}, {"text": "카메라를 만드는 사람들이 알아냈어요.", "translation": "People who make cameras found out.", "vocab": [{"ko": "카메라", "en": "camera"}, {"ko": "만들다", "en": "to make"}, {"ko": "사람", "en": "person"}, {"ko": "알아내다", "en": "to find out/discover"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. 만들다 → 만드는 사람들 = people who make (cameras); ㄹ drops before 는.", "example_in_sentence": "만드는"}, {"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 알아내다 → 알아냈어요 = found out.", "example_in_sentence": "알아냈어요"}]}, {"text": "닭의 머리가 500만원짜리 카메라 도구보다 더 안정하다고 해요.", "translation": "They say that a chicken''s head is more stable than a 5-million-won camera tool.", "vocab": [{"ko": "안정하다", "en": "to be stable"}, {"ko": "도구", "en": "tool"}], "analysis": [{"type": "grammar", "label": "~보다", "exp": "Comparative particle meaning ''more than'' or ''compared to''. Shows comparison between two things. 도구 + 보다.", "example_in_sentence": "도구보다"}, {"type": "grammar", "label": "~다고 하다", "exp": "Indirect speech construction meaning ''they say that'' or ''it is said that''. Reports information. 안정하 + 다고 + 해요 = 안정하다고 해요.", "example_in_sentence": "안정하다고 해요"}, {"type": "grammar", "label": "더", "exp": "Adverb meaning ''more''. Intensifies comparison or degree.", "example_in_sentence": "더"}]}, {"text": "정말 놀라운 일이에요.", "translation": "It''s a truly surprising thing.", "vocab": [{"ko": "놀랍다", "en": "to be surprising"}, {"ko": "일", "en": "thing/matter"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 놀랍다 is ㅂ irregular: 놀랍다 → 놀라운 일 = a surprising thing.", "example_in_sentence": "놀라운"}]}, {"text": "이 카메라 도구를 짐벌(gimbal)이라고 해요.", "translation": "This camera tool is called a gimbal.", "vocab": [{"ko": "짐벌", "en": "gimbal"}], "analysis": [{"type": "grammar", "label": "~(이)라고 하다 (to be called ~)", "exp": "Gives the name of something. After a consonant use 이라고: 짐벌이라고 해요 = it is called a gimbal.", "example_in_sentence": "짐벌(gimbal)이라고 해요"}]}, {"text": "사진을 흔들리지 않게 찍는 도구예요.", "translation": "It''s a tool for taking photographs without shaking.", "vocab": [{"ko": "사진", "en": "photograph"}, {"ko": "찍다", "en": "to take/shoot"}], "analysis": [{"type": "grammar", "label": "~지 않게 (so that ~ not)", "exp": "Describes how something is done so a thing does not happen. 흔들리다 → 흔들리지 않게 찍다 = to take (photos) so they don''t shake.", "example_in_sentence": "흔들리지 않게"}]}, {"text": "하지만 닭이 더 잘해요.", "translation": "But chickens do it better.", "vocab": [{"ko": "하지만", "en": "but/however"}, {"ko": "잘하다", "en": "to do well"}], "analysis": [{"type": "grammar", "label": "더 (more)", "exp": "더 before a verb means ''more'' or ''better''. 더 잘해요 = does it better.", "example_in_sentence": "더 잘해요"}]}, {"text": "동물들은 우리가 모르는 특별한 능력이 많아요.", "translation": "Animals have many special abilities that we don''t know about.", "vocab": [{"ko": "동물", "en": "animal"}, {"ko": "능력", "en": "ability"}, {"ko": "많다", "en": "to be many"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Describes the noun that follows. 모르다 → 우리가 모르는 능력 = abilities we don''t know about.", "example_in_sentence": "모르는"}, {"type": "grammar", "label": "~이", "exp": "Subject particle marking the subject of the sentence. 능력 + 이.", "example_in_sentence": "능력이"}]}, {"text": "닭도 그중 하나예요.", "translation": "Chickens are one of them too.", "vocab": [{"ko": "그중", "en": "among them"}], "analysis": [{"type": "grammar", "label": "~도 (inclusive particle)", "exp": "Particle meaning ''also'' or ''too''. Shows inclusion. 닭 + 도.", "example_in_sentence": "닭도"}]}, {"text": "자연은 정말 대단해요.", "translation": "Nature is really amazing.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "대단하다", "en": "to be amazing/great"}], "analysis": [{"type": "grammar", "label": "~해요", "exp": "Informal polite present tense ending for adjectives. 대단하 + 어요 = 대단해요.", "example_in_sentence": "대단해요"}]}], "version": "s6"}', vocab = '[{"ko": "닭", "en": "chicken", "note": ""}, {"ko": "머리", "en": "head", "note": ""}, {"ko": "신기하다", "en": "to be amazing/fascinating", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "흔들리다", "en": "to sway/shake", "note": ""}, {"ko": "그대로", "en": "as is/unchanged", "note": ""}, {"ko": "마치", "en": "as if/just like", "note": ""}, {"ko": "마법", "en": "magic", "note": ""}, {"ko": "카메라", "en": "camera", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "알아내다", "en": "to find out/discover", "note": ""}, {"ko": "안정하다", "en": "to be stable", "note": ""}, {"ko": "도구", "en": "tool", "note": ""}, {"ko": "놀랍다", "en": "to be surprising", "note": ""}, {"ko": "일", "en": "thing/matter", "note": ""}, {"ko": "짐벌", "en": "gimbal", "note": ""}, {"ko": "사진", "en": "photograph", "note": ""}, {"ko": "찍다", "en": "to take/shoot", "note": ""}, {"ko": "하지만", "en": "but/however", "note": ""}, {"ko": "잘하다", "en": "to do well", "note": ""}, {"ko": "동물", "en": "animal", "note": ""}, {"ko": "능력", "en": "ability", "note": ""}, {"ko": "많다", "en": "to be many", "note": ""}, {"ko": "그중", "en": "among them", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "대단하다", "en": "to be amazing/great", "note": ""}]', grammar = '{"patterns": [{"name": "~해요 (polite form of 하다 words)", "level": "Starter", "exp": "하다 words become 해요 in the everyday polite form. 신기하다 → 신기해요 = is amazing.", "ex_ko": "닭의 머리는 정말 신기해요.", "ex_en": "A chicken''s head is really amazing."}, {"name": "~의 (possessive particle)", "level": "Starter", "exp": "Shows possession or belonging. Connects noun to noun. 닭 + 의 = 닭의 (chicken''s).", "ex_ko": "닭의 머리는 정말 신기해요.", "ex_en": "A chicken''s head is really amazing."}, {"name": "~어도 / ~아도", "level": "Starter", "exp": "Concessive/contrastive suffix meaning ''even if'' or ''even though''. Indicates an action/state happens regardless of the condition. 흔들리 + 어도 = 흔들려도.", "ex_ko": "몸이 흔들려도 머리는 그대로 있어요.", "ex_en": "Even if the body sways, the head stays still."}, {"name": "그대로 있다 (to stay as it is)", "level": "Starter", "exp": "그대로 (as it is) + 있다 (to stay) = to stay still. 있다 → 있어요.", "ex_ko": "몸이 흔들려도 머리는 그대로 있어요.", "ex_en": "Even if the body sways, the head stays still."}, {"name": "~ 같다 (to be like ~)", "level": "Starter", "exp": "Noun + 같다 means ''to be like''. 마법 같아요 = it''s like magic. 마치 adds ''just as if''.", "ex_ko": "마치 마법 같아요.", "ex_en": "It''s like magic."}, {"name": "~는 (noun modifier)", "level": "Starter", "exp": "Describes the noun that follows. 만들다 → 만드는 사람들 = people who make (cameras); ㄹ drops before 는.", "ex_ko": "카메라를 만드는 사람들이 알아냈어요.", "ex_en": "People who make cameras found out."}, {"name": "~았/었어요 (past tense)", "level": "Starter", "exp": "Marks a completed past action. 알아내다 → 알아냈어요 = found out.", "ex_ko": "카메라를 만드는 사람들이 알아냈어요.", "ex_en": "People who make cameras found out."}, {"name": "~보다", "level": "Starter", "exp": "Comparative particle meaning ''more than'' or ''compared to''. Shows comparison between two things. 도구 + 보다.", "ex_ko": "닭의 머리가 500만원짜리 카메라 도구보다 더 안정하다고 해요.", "ex_en": "They say that a chicken''s head is more stable than a 5-million-won camera tool."}, {"name": "~다고 하다", "level": "Starter", "exp": "Indirect speech construction meaning ''they say that'' or ''it is said that''. Reports information. 안정하 + 다고 + 해요 = 안정하다고 해요.", "ex_ko": "닭의 머리가 500만원짜리 카메라 도구보다 더 안정하다고 해요.", "ex_en": "They say that a chicken''s head is more stable than a 5-million-won camera tool."}, {"name": "더 (more)", "level": "Starter", "exp": "더 before a verb means ''more'' or ''better''. 더 잘해요 = does it better.", "ex_ko": "닭의 머리가 500만원짜리 카메라 도구보다 더 안정하다고 해요.", "ex_en": "They say that a chicken''s head is more stable than a 5-million-won camera tool."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Starter", "exp": "Describing words take ~(으)ㄴ before a noun. 놀랍다 is ㅂ irregular: 놀랍다 → 놀라운 일 = a surprising thing.", "ex_ko": "정말 놀라운 일이에요.", "ex_en": "It''s a truly surprising thing."}, {"name": "~(이)라고 하다 (to be called ~)", "level": "Starter", "exp": "Gives the name of something. After a consonant use 이라고: 짐벌이라고 해요 = it is called a gimbal.", "ex_ko": "이 카메라 도구를 짐벌(gimbal)이라고 해요.", "ex_en": "This camera tool is called a gimbal."}, {"name": "~지 않게 (so that ~ not)", "level": "Starter", "exp": "Describes how something is done so a thing does not happen. 흔들리다 → 흔들리지 않게 찍다 = to take (photos) so they don''t shake.", "ex_ko": "사진을 흔들리지 않게 찍는 도구예요.", "ex_en": "It''s a tool for taking photographs without shaking."}, {"name": "~이", "level": "Starter", "exp": "Subject particle marking the subject of the sentence. 능력 + 이.", "ex_ko": "동물들은 우리가 모르는 특별한 능력이 많아요.", "ex_en": "Animals have many special abilities that we don''t know about."}, {"name": "~도 (inclusive particle)", "level": "Starter", "exp": "Particle meaning ''also'' or ''too''. Shows inclusion. 닭 + 도.", "ex_ko": "닭도 그중 하나예요.", "ex_en": "Chickens are one of them too."}]}', updated_at = now() where article_id = 'moliygnypvia' and md5(translation) = 'fe27745cb1ae9ba268d17454e947be1c';
update public.article_cache set translation = '{"texts": ["Scientists discovered a very special frog. This frog has a transparent body.", "The frog''s skin is clear like glass. So all the organs inside the body are visible. You can also see the heart and liver.", "This type of frog is called a glass frog. It lives in the forests of South America. It lives on top of leaves.", "The transparent body is to hide from predators (animals that eat them). It looks similar to leaves. It is a mysterious appearance of nature."], "sentences": [{"text": "과학자들이 아주 특별한 개구리를 발견했어요.", "translation": "Scientists discovered a very special frog.", "vocab": [{"ko": "과학자", "en": "scientist"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "개구리", "en": "frog"}, {"ko": "발견하다", "en": "to discover"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending expressing completed action in polite/casual tone. 발견하다 (base) → 발견했어요 (past).", "example_in_sentence": "발견했어요"}]}, {"text": "이 개구리는 몸이 투명해요.", "translation": "This frog has a transparent body.", "vocab": [{"ko": "투명하다", "en": "to be transparent"}, {"ko": "몸", "en": "body"}], "analysis": [{"type": "grammar", "label": "~어/아요", "exp": "Present tense descriptive ending in polite/casual tone. 투명하다 (base) → 투명해요 (present).", "example_in_sentence": "투명해요"}, {"type": "grammar", "label": "N이 (subject particle)", "exp": "Subject marker used when the preceding noun ends in a consonant. Marks 몸 as the subject.", "example_in_sentence": "몸이"}]}, {"text": "개구리의 피부가 유리처럼 맑아요.", "translation": "The frog''s skin is clear like glass.", "vocab": [{"ko": "피부", "en": "skin"}, {"ko": "유리", "en": "glass"}, {"ko": "맑다", "en": "to be clear/clean"}], "analysis": [{"type": "grammar", "label": "N의 (possessive particle)", "exp": "Possessive marker indicating ownership or relationship. Shows 개구리의 피부 (the frog''s skin).", "example_in_sentence": "개구리의"}, {"type": "expression", "label": "N처럼 (like N)", "exp": "Comparison pattern meaning ''like'' or ''similar to''. 유리처럼 = like glass.", "example_in_sentence": "유리처럼"}]}, {"text": "그래서 몸 안의 장기들이 다 보여요.", "translation": "So the organs inside the body are all visible.", "vocab": [{"ko": "장기", "en": "organ"}, {"ko": "보이다", "en": "to be visible/to show"}], "analysis": [{"type": "grammar", "label": "N 안의 (inside N)", "exp": "Postposition phrase 안의 indicating ''inside'' or ''within''. 몸 안의 = inside the body.", "example_in_sentence": "몸 안의"}, {"type": "grammar", "label": "~어/아요", "exp": "Present tense ending. 보이다 (base) → 보여요 (present).", "example_in_sentence": "보여요"}]}, {"text": "심장과 간도 볼 수 있어요.", "translation": "The heart and liver can be seen too.", "vocab": [{"ko": "심장", "en": "heart"}, {"ko": "간", "en": "liver"}], "analysis": [{"type": "grammar", "label": "N과/와 (and)", "exp": "Conjunction particle connecting nouns. 심장과 간 = heart and liver.", "example_in_sentence": "심장과"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says something is possible. 보다 → 볼 수 있어요 = can see.", "example_in_sentence": "볼 수 있어요"}]}, {"text": "이런 개구리를 유리개구리라고 불러요.", "translation": "This kind of frog is called a glass frog.", "vocab": [{"ko": "부르다", "en": "to call/to name"}], "analysis": [{"type": "grammar", "label": "N이라고 (be called N)", "exp": "Quotative particle + copula. Used for naming or labeling. 유리개구리라고 불러요 = called/named glass frog.", "example_in_sentence": "유리개구리라고"}, {"type": "grammar", "label": "~어/아요", "exp": "Present tense ending. 부르다 (base) → 불러요 (present).", "example_in_sentence": "불러요"}]}, {"text": "남미의 숲에서 살고 있어요.", "translation": "It lives in the forests of South America.", "vocab": [{"ko": "남미", "en": "South America"}, {"ko": "숲", "en": "forest"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. 살다 (base) → 살고 있어요 (is living/does live as ongoing state).", "example_in_sentence": "살고 있어요"}, {"type": "grammar", "label": "N에서 (at/in location)", "exp": "Locative particle marking where an action occurs. 숲에서 = in the forest.", "example_in_sentence": "숲에서"}]}, {"text": "나뭇잎 위에서 생활해요.", "translation": "It lives on leaves.", "vocab": [{"ko": "나뭇잎", "en": "leaf"}, {"ko": "위", "en": "top/on"}, {"ko": "생활하다", "en": "to live/to dwell"}], "analysis": [{"type": "grammar", "label": "N 위에서 (on/on top of N)", "exp": "Locative phrase indicating surface position where action occurs. 나뭇잎 위에서 = on the leaves.", "example_in_sentence": "나뭇잎 위에서"}]}, {"text": "투명한 몸은 천적(자신을 잡아먹는 동물)으로부터 숨기 위해서예요.", "translation": "The transparent body is for hiding from predators (animals that eat it).", "vocab": [{"ko": "투명하다", "en": "to be transparent"}, {"ko": "천적", "en": "predator/natural enemy"}, {"ko": "숨다", "en": "to hide (oneself)"}], "analysis": [{"type": "grammar", "label": "~으로부터 (from)", "exp": "Source/origin particle. 천적으로부터 = from predators.", "example_in_sentence": "천적(자신을 잡아먹는 동물)으로부터"}, {"type": "grammar", "label": "~기 위해서 (in order to)", "exp": "Shows purpose. 숨다 → 숨기 위해서 = in order to hide.", "example_in_sentence": "숨기 위해서"}, {"type": "grammar", "label": "~이에요/예요 (is)", "exp": "The polite form of 이다 (to be). After a vowel use 예요: 위해서 → 위해서예요 = it is (in order to ...).", "example_in_sentence": "위해서예요"}]}, {"text": "나뭇잎과 비슷해 보이거든요.", "translation": "Because it looks similar to leaves.", "vocab": [{"ko": "비슷하다", "en": "to be similar"}, {"ko": "보이다", "en": "to look/to appear"}], "analysis": [{"type": "grammar", "label": "~어/아 보이다 (look/appear)", "exp": "Auxiliary meaning ''to appear/to look like''. 비슷해 보이다 = looks similar.", "example_in_sentence": "비슷해 보이거든요"}, {"type": "grammar", "label": "~거든요 (because/that''s why)", "exp": "Causal/explanatory ending in polite tone. Provides reason for prior statement.", "example_in_sentence": "거든요"}]}, {"text": "자연의 신비로운 모습이에요.", "translation": "It is a mysterious aspect of nature.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "신비롭다", "en": "to be mysterious"}, {"ko": "모습", "en": "appearance/form"}], "analysis": [{"type": "grammar", "label": "~이에요/예요 (is)", "exp": "The polite form of 이다 (to be). After a consonant use 이에요: 모습 → 모습이에요.", "example_in_sentence": "이에요"}]}], "version": "s6"}', vocab = '[{"ko": "과학자", "en": "scientist", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "개구리", "en": "frog", "note": ""}, {"ko": "발견하다", "en": "to discover", "note": ""}, {"ko": "투명하다", "en": "to be transparent", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "피부", "en": "skin", "note": ""}, {"ko": "유리", "en": "glass", "note": ""}, {"ko": "맑다", "en": "to be clear/clean", "note": ""}, {"ko": "장기", "en": "organ", "note": ""}, {"ko": "보이다", "en": "to be visible/to show", "note": ""}, {"ko": "심장", "en": "heart", "note": ""}, {"ko": "간", "en": "liver", "note": ""}, {"ko": "부르다", "en": "to call/to name", "note": ""}, {"ko": "남미", "en": "South America", "note": ""}, {"ko": "숲", "en": "forest", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"ko": "나뭇잎", "en": "leaf", "note": ""}, {"ko": "위", "en": "top/on", "note": ""}, {"ko": "생활하다", "en": "to live/to dwell", "note": ""}, {"ko": "천적", "en": "predator/natural enemy", "note": ""}, {"ko": "숨다", "en": "to hide (oneself)", "note": ""}, {"ko": "비슷하다", "en": "to be similar", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "신비롭다", "en": "to be mysterious", "note": ""}, {"ko": "모습", "en": "appearance/form", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Starter", "exp": "Past tense ending expressing completed action in polite/casual tone. 발견하다 (base) → 발견했어요 (past).", "ex_ko": "과학자들이 아주 특별한 개구리를 발견했어요.", "ex_en": "Scientists discovered a very special frog."}, {"name": "~어/아요", "level": "Starter", "exp": "Present tense descriptive ending in polite/casual tone. 투명하다 (base) → 투명해요 (present).", "ex_ko": "이 개구리는 몸이 투명해요.", "ex_en": "This frog has a transparent body."}, {"name": "N이 (subject particle)", "level": "Starter", "exp": "Subject marker used when the preceding noun ends in a consonant. Marks 몸 as the subject.", "ex_ko": "이 개구리는 몸이 투명해요.", "ex_en": "This frog has a transparent body."}, {"name": "N의 (possessive particle)", "level": "Starter", "exp": "Possessive marker indicating ownership or relationship. Shows 개구리의 피부 (the frog''s skin).", "ex_ko": "개구리의 피부가 유리처럼 맑아요.", "ex_en": "The frog''s skin is clear like glass."}, {"name": "N 안의 (inside N)", "level": "Starter", "exp": "Postposition phrase 안의 indicating ''inside'' or ''within''. 몸 안의 = inside the body.", "ex_ko": "그래서 몸 안의 장기들이 다 보여요.", "ex_en": "So the organs inside the body are all visible."}, {"name": "N과/와 (and)", "level": "Starter", "exp": "Conjunction particle connecting nouns. 심장과 간 = heart and liver.", "ex_ko": "심장과 간도 볼 수 있어요.", "ex_en": "The heart and liver can be seen too."}, {"name": "~(으)ㄹ 수 있다 (can)", "level": "Starter", "exp": "Says something is possible. 보다 → 볼 수 있어요 = can see.", "ex_ko": "심장과 간도 볼 수 있어요.", "ex_en": "The heart and liver can be seen too."}, {"name": "N이라고 (be called N)", "level": "Starter", "exp": "Quotative particle + copula. Used for naming or labeling. 유리개구리라고 불러요 = called/named glass frog.", "ex_ko": "이런 개구리를 유리개구리라고 불러요.", "ex_en": "This kind of frog is called a glass frog."}, {"name": "~고 있다", "level": "Starter", "exp": "Progressive aspect marker. 살다 (base) → 살고 있어요 (is living/does live as ongoing state).", "ex_ko": "남미의 숲에서 살고 있어요.", "ex_en": "It lives in the forests of South America."}, {"name": "N에서 (at/in location)", "level": "Starter", "exp": "Locative particle marking where an action occurs. 숲에서 = in the forest.", "ex_ko": "남미의 숲에서 살고 있어요.", "ex_en": "It lives in the forests of South America."}, {"name": "N 위에서 (on/on top of N)", "level": "Starter", "exp": "Locative phrase indicating surface position where action occurs. 나뭇잎 위에서 = on the leaves.", "ex_ko": "나뭇잎 위에서 생활해요.", "ex_en": "It lives on leaves."}, {"name": "~으로부터 (from)", "level": "Starter", "exp": "Source/origin particle. 천적으로부터 = from predators.", "ex_ko": "투명한 몸은 천적(자신을 잡아먹는 동물)으로부터 숨기 위해서예요.", "ex_en": "The transparent body is for hiding from predators (animals that eat it)."}, {"name": "~기 위해서 (in order to)", "level": "Starter", "exp": "Shows purpose. 숨다 → 숨기 위해서 = in order to hide.", "ex_ko": "투명한 몸은 천적(자신을 잡아먹는 동물)으로부터 숨기 위해서예요.", "ex_en": "The transparent body is for hiding from predators (animals that eat it)."}, {"name": "~이에요/예요 (is)", "level": "Starter", "exp": "The polite form of 이다 (to be). After a vowel use 예요: 위해서 → 위해서예요 = it is (in order to ...).", "ex_ko": "투명한 몸은 천적(자신을 잡아먹는 동물)으로부터 숨기 위해서예요.", "ex_en": "The transparent body is for hiding from predators (animals that eat it)."}, {"name": "~어/아 보이다 (look/appear)", "level": "Starter", "exp": "Auxiliary meaning ''to appear/to look like''. 비슷해 보이다 = looks similar.", "ex_ko": "나뭇잎과 비슷해 보이거든요.", "ex_en": "Because it looks similar to leaves."}]}', updated_at = now() where article_id = 'moliz0ae6h66' and md5(translation) = '449690114934d6080274fb550eef7ded';
update public.article_cache set translation = '{"texts": ["Animals are really strong. Elephants can lift heavy trees. Lions can run fast.", "Ants are small but can lift things heavier than their own body. Bears can even push large rocks. The strength of animals is truly amazing.", "There are many animals much stronger than humans. Gorillas are 10 times stronger than humans. The power of nature is amazing.", "Animals use this strength to survive. They need it when finding food or building homes. We can also learn from the strength of animals."], "sentences": [{"text": "동물들은 정말 힘이 세요.", "translation": "Animals are really strong.", "vocab": [{"ko": "동물", "en": "animal"}, {"ko": "힘", "en": "strength; power"}, {"ko": "세다", "en": "to be strong"}], "analysis": [{"type": "grammar", "label": "~이/가 (subject particle)", "exp": "Marks the subject. After a consonant use 이: 힘 → 힘이. 힘이 세다 = to be strong.", "example_in_sentence": "힘이"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 세다 → 세어요, shortened to 세요 = is strong.", "example_in_sentence": "세요"}]}, {"text": "코끼리는 무거운 나무를 들 수 있어요.", "translation": "Elephants can lift heavy wood.", "vocab": [{"ko": "코끼리", "en": "elephant"}, {"ko": "무겁다", "en": "to be heavy"}, {"ko": "나무", "en": "wood; tree"}, {"ko": "들다", "en": "to lift; to hold"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic particle)", "exp": "Marks the topic. After a vowel use 는: 코끼리 → 코끼리는.", "example_in_sentence": "코끼리는"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 무겁다 is ㅂ irregular: 무겁다 → 무거운 나무 = heavy wood.", "example_in_sentence": "무거운"}, {"type": "grammar", "label": "~을/를 (object particle)", "exp": "Marks the object. After a vowel use 를: 나무 → 나무를.", "example_in_sentence": "나무를"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 들다 → 들 수 있어요 = can lift.", "example_in_sentence": "들 수 있어요"}]}, {"text": "사자는 빠르게 달릴 수 있어요.", "translation": "Lions can run fast.", "vocab": [{"ko": "사자", "en": "lion"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "달리다", "en": "to run"}], "analysis": [{"type": "grammar", "label": "~게 (adverb form)", "exp": "Turns a describing word into an adverb. 빠르다 → 빠르게 = fast, quickly.", "example_in_sentence": "빠르게"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 달리다 → 달릴 수 있어요 = can run.", "example_in_sentence": "달릴 수 있어요"}]}, {"text": "개미는 작지만 자기 몸보다 무거운 것을 들어요.", "translation": "Ants are small, but they lift things heavier than their own bodies.", "vocab": [{"ko": "개미", "en": "ant"}, {"ko": "작다", "en": "to be small"}, {"ko": "몸", "en": "body"}, {"ko": "것", "en": "thing"}], "analysis": [{"type": "grammar", "label": "~지만 (contrasting connective)", "exp": "Connects two contrasting ideas. Converts adjective 작다 into ~지만 form: 작다 → 작지만.", "example_in_sentence": "작지만"}, {"type": "grammar", "label": "~보다 (comparison particle)", "exp": "Marks the comparative standard. Indicates ''more than'' or ''compared to''. Follows the noun 몸.", "example_in_sentence": "몸보다"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 무겁다 is ㅂ irregular: 무겁다 → 무거운 것 = something heavy.", "example_in_sentence": "무거운 것"}]}, {"text": "곰은 큰 바위도 밀 수 있어요.", "translation": "Bears can even push large rocks.", "vocab": [{"ko": "곰", "en": "bear"}, {"ko": "크다", "en": "to be big; to be large"}, {"ko": "바위", "en": "rock"}, {"ko": "밀다", "en": "to push"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 크다 → 큰 바위 = a big rock.", "example_in_sentence": "큰"}, {"type": "grammar", "label": "~도 (inclusive particle; ''even'')", "exp": "Adds emphasis meaning ''even'' or ''also''. Marks 바위 as an extreme example.", "example_in_sentence": "바위도"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 밀다 → 밀 수 있어요 = can push.", "example_in_sentence": "밀 수 있어요"}]}, {"text": "동물들의 힘은 정말 대단해요.", "translation": "The power of animals is truly amazing.", "vocab": [{"ko": "대단하다", "en": "to be amazing; to be impressive"}], "analysis": [{"type": "grammar", "label": "~의 (possessive particle)", "exp": "Marks possession or attribution. Connects 동물들 with 힘, indicating ''the power of animals''.", "example_in_sentence": "동물들의"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 하다 words become 해요: 대단하다 → 대단해요 = is amazing.", "example_in_sentence": "대단해요"}]}, {"text": "사람보다 훨씬 힘이 센 동물이 많아요.", "translation": "There are many animals that are much stronger than humans.", "vocab": [{"ko": "사람", "en": "human; person"}, {"ko": "훨씬", "en": "much; far; significantly"}, {"ko": "많다", "en": "to be many; to be much"}], "analysis": [{"type": "grammar", "label": "~보다 (comparison particle)", "exp": "Marks the comparative standard meaning ''compared to'' or ''more than''. Follows the noun 사람.", "example_in_sentence": "사람보다"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 세다 → 힘이 센 동물 = a strong animal.", "example_in_sentence": "센"}, {"type": "grammar", "label": "~이/가 (subject particle)", "exp": "Marks the subject. After a consonant use 이: 동물 → 동물이.", "example_in_sentence": "동물이"}]}, {"text": "고릴라는 사람보다 10배나 힘이 세요.", "translation": "Gorillas are 10 times stronger than humans.", "vocab": [{"ko": "고릴라", "en": "gorilla"}, {"ko": "배", "en": "times (multiplier); fold"}], "analysis": [{"type": "grammar", "label": "~보다 (comparison particle)", "exp": "Marks the comparative standard. Indicates ''compared to'' or ''more than''. Follows the noun 사람.", "example_in_sentence": "사람보다"}, {"type": "grammar", "label": "~나 (emphasizing particle)", "exp": "Emphasizes the quantity or degree. After a number/amount, it strengthens the comparison meaning ''as much as'' or ''up to''.", "example_in_sentence": "10배나"}]}, {"text": "자연의 힘은 놀라워요.", "translation": "The power of nature is surprising.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "놀랍다", "en": "to be surprising; to be amazing"}], "analysis": [{"type": "grammar", "label": "~의 (possessive particle)", "exp": "Marks possession or attribution. Connects 자연 with 힘, indicating ''the power of nature''.", "example_in_sentence": "자연의"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 놀랍다 is ㅂ irregular: 놀랍다 → 놀라워요 = is surprising.", "example_in_sentence": "놀라워요"}]}, {"text": "동물들은 살기 위해 이런 힘을 써요.", "translation": "Animals use this power in order to live.", "vocab": [{"ko": "살다", "en": "to live"}, {"ko": "이런", "en": "like this; such"}, {"ko": "쓰다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "~기 위해 (in order to)", "exp": "Shows purpose. 살다 → 살기 위해 = in order to live.", "example_in_sentence": "살기 위해"}, {"type": "grammar", "label": "~을/를 (direct object particle)", "exp": "Marks 힘 as the direct object. After a final consonant, use 을.", "example_in_sentence": "힘을"}]}, {"text": "먹이를 찾거나 집을 만들 때 필요해요.", "translation": "It is needed when finding food or building a home.", "vocab": [{"ko": "먹이", "en": "food; prey"}, {"ko": "찾다", "en": "to find; to look for"}, {"ko": "집", "en": "house; home"}, {"ko": "만들다", "en": "to make; to build"}], "analysis": [{"type": "grammar", "label": "~거나 (alternative connective)", "exp": "Connects two alternative actions. Converts verb 찾다 into 찾거나, indicating ''or'' between two options.", "example_in_sentence": "찾거나"}, {"type": "grammar", "label": "~(으)ㄹ 때 (when)", "exp": "Marks the time when something happens. 만들다 → 만들 때 = when making.", "example_in_sentence": "만들 때"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 하다 words become 해요: 필요하다 → 필요해요 = is needed.", "example_in_sentence": "필요해요"}]}, {"text": "우리도 동물의 힘을 배울 수 있어요.", "translation": "We can also learn the power of animals.", "vocab": [{"ko": "우리", "en": "we; us"}, {"ko": "배우다", "en": "to learn"}], "analysis": [{"type": "grammar", "label": "~도 (inclusive particle; ''also'')", "exp": "Adds emphasis meaning ''also'' or ''too''. Marks 우리 as included in the group that can learn.", "example_in_sentence": "우리도"}, {"type": "grammar", "label": "~의 (possessive particle)", "exp": "Marks possession or attribution. Connects 동물 with 힘, indicating ''the power of animals''.", "example_in_sentence": "동물의"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 배우다 → 배울 수 있어요 = can learn.", "example_in_sentence": "배울 수 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "동물", "en": "animal", "note": ""}, {"ko": "힘", "en": "strength; power", "note": ""}, {"ko": "세다", "en": "to be strong", "note": ""}, {"ko": "코끼리", "en": "elephant", "note": ""}, {"ko": "무겁다", "en": "to be heavy", "note": ""}, {"ko": "나무", "en": "wood; tree", "note": ""}, {"ko": "들다", "en": "to lift; to hold", "note": ""}, {"ko": "사자", "en": "lion", "note": ""}, {"ko": "빠르다", "en": "to be fast", "note": ""}, {"ko": "달리다", "en": "to run", "note": ""}, {"ko": "개미", "en": "ant", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "것", "en": "thing", "note": ""}, {"ko": "곰", "en": "bear", "note": ""}, {"ko": "크다", "en": "to be big; to be large", "note": ""}, {"ko": "바위", "en": "rock", "note": ""}, {"ko": "밀다", "en": "to push", "note": ""}, {"ko": "대단하다", "en": "to be amazing; to be impressive", "note": ""}, {"ko": "사람", "en": "human; person", "note": ""}, {"ko": "훨씬", "en": "much; far; significantly", "note": ""}, {"ko": "많다", "en": "to be many; to be much", "note": ""}, {"ko": "고릴라", "en": "gorilla", "note": ""}, {"ko": "배", "en": "times (multiplier); fold", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "놀랍다", "en": "to be surprising; to be amazing", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"ko": "이런", "en": "like this; such", "note": ""}