update public.article_cache set translation = '{"sentences": [{"text": "일본에서는 음식 포장이 특별해요.", "idx": 0, "translation": "In Japan, food packaging is special.", "vocab": [{"ko": "일본", "en": "Japan", "note": "proper noun"}, {"ko": "음식", "en": "food"}, {"ko": "포장", "en": "packaging"}], "grammar": [{"pattern": "~에서는", "exp": "marks a location as the topic of contrast or focus", "example_in_sentence": "일본에서는"}], "analysis": []}, {"text": "포장지에 그린 그림과 실제 음식이 똑같아야 해요.", "idx": 1, "translation": "The picture drawn on the packaging must be exactly the same as the actual food.", "vocab": [{"ko": "포장지", "en": "packaging material"}, {"ko": "그리다", "en": "to draw"}, {"ko": "그림", "en": "picture"}, {"ko": "실제", "en": "actual, real"}], "grammar": [{"pattern": "~ㄴ 것", "exp": "nominalizes an action; turns a verb into a noun phrase", "example_in_sentence": "포장지에 그린 그림"}, {"pattern": "~아/어야 하다", "exp": "must do; expresses obligation or necessity", "example_in_sentence": "똑같아야 해요"}], "analysis": []}, {"text": "한국에서는 가끔 포장과 다른 음식이 나와요.", "idx": 2, "translation": "In Korea, the food inside is sometimes different from the packaging.", "vocab": [{"ko": "한국", "en": "Korea", "note": "proper noun"}, {"ko": "가끔", "en": "sometimes"}, {"ko": "다르다", "en": "to be different"}], "grammar": [{"pattern": "~과/와 다르다", "exp": "to be different from something", "example_in_sentence": "포장과 다른"}, {"pattern": "~ㄴ 것이 나오다", "exp": "nominalizer + copula + come out; a thing that is X comes out", "example_in_sentence": "포장과 다른 음식이 나와요"}], "analysis": []}, {"text": "하지만 일본은 법으로 이것을 금지해요.", "idx": 3, "translation": "However, Japan prohibits this by law.", "vocab": [{"ko": "하지만", "en": "however, but"}, {"ko": "법", "en": "law"}, {"ko": "금지하다", "en": "to prohibit"}], "grammar": [{"pattern": "~으로", "exp": "by means of; with the tool/method of", "example_in_sentence": "법으로"}, {"pattern": "~다", "exp": "plain polite declarative; ends statement", "example_in_sentence": "금지해요"}], "analysis": []}, {"text": "일본 사람들은 정직한 포장을 좋아해요.", "idx": 4, "translation": "Japanese people like honest packaging.", "vocab": [{"ko": "일본 사람", "en": "Japanese person"}, {"ko": "정직하다", "en": "to be honest"}], "grammar": [{"pattern": "~ㄴ", "exp": "modifies a noun with a past or completed adjective", "example_in_sentence": "정직한 포장"}], "analysis": []}, {"text": "그래서 음식을 살 때 안심할 수 있어요.", "idx": 5, "translation": "So you can feel at ease when you buy food.", "vocab": [{"ko": "그래서", "en": "so, therefore"}, {"ko": "사다", "en": "to buy"}, {"ko": "안심하다", "en": "to feel at ease, reassured"}], "grammar": [{"pattern": "~을/를 때", "exp": "at the time of; when doing something", "example_in_sentence": "음식을 살 때"}, {"pattern": "~을/를 수 있다", "exp": "can do; expresses ability or possibility", "example_in_sentence": "안심할 수 있어요"}], "analysis": []}, {"text": "우리나라도 이런 법이 있으면 좋겠어요.", "idx": 6, "translation": "It would be nice if our country had a law like this too.", "vocab": [{"ko": "우리나라", "en": "our country"}, {"ko": "이런", "en": "this kind of, such"}], "grammar": [{"pattern": "~으면 좋겠어요", "exp": "I wish / it would be nice if; expresses a desire", "example_in_sentence": "이런 법이 있으면 좋겠어요"}], "analysis": []}, {"text": "소비자들이 더 행복할 거예요.", "idx": 7, "translation": "Consumers would be happier.", "vocab": [{"ko": "소비자", "en": "consumer"}, {"ko": "행복하다", "en": "to be happy"}], "grammar": [{"pattern": "~ㄹ 것이다", "exp": "will do; future supposition or prediction", "example_in_sentence": "행복할 거예요"}], "analysis": []}], "version": "p2"}', vocab = '[{"ko": "일본", "en": "Japan", "note": "proper noun"}, {"ko": "음식", "en": "food", "note": ""}, {"ko": "포장", "en": "packaging", "note": ""}, {"ko": "포장지", "en": "packaging material", "note": ""}, {"ko": "그리다", "en": "to draw", "note": ""}, {"ko": "그림", "en": "picture", "note": ""}, {"ko": "실제", "en": "actual, real", "note": ""}, {"ko": "한국", "en": "Korea", "note": "proper noun"}, {"ko": "가끔", "en": "sometimes", "note": ""}, {"ko": "다르다", "en": "to be different", "note": ""}, {"ko": "하지만", "en": "however, but", "note": ""}, {"ko": "법", "en": "law", "note": ""}, {"ko": "금지하다", "en": "to prohibit", "note": ""}, {"ko": "일본 사람", "en": "Japanese person", "note": ""}, {"ko": "정직하다", "en": "to be honest", "note": ""}, {"ko": "그래서", "en": "so, therefore", "note": ""}, {"ko": "사다", "en": "to buy", "note": ""}, {"ko": "안심하다", "en": "to feel at ease, reassured", "note": ""}, {"ko": "우리나라", "en": "our country", "note": ""}, {"ko": "이런", "en": "this kind of, such", "note": ""}, {"ko": "소비자", "en": "consumer", "note": ""}, {"ko": "행복하다", "en": "to be happy", "note": ""}, {"word": "똑같다", "reading": "ttokgatda", "meaning": "to be identical, to be the same", "context": "그린 그림과 실제 음식이 똑같아야"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mom3upnu1cof' and md5(translation) = 'b0b6655f69199f832c7cd2945082c4a4';
update public.article_cache set translation = '{"texts": ["An elephant family spotted danger. Something scary was approaching. The elephants moved quickly. The adult elephants stood in a circle. They placed the baby elephant in the middle. They prevented the danger from reaching the baby. Elephants help each other. They try to protect their family. They shield the baby so it doesn''t get hurt. Animals love their families too. It''s similar to us humans. Elephants are really intelligent animals.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "코끼리 가족이 위험을 봤어요.", "translation": "The elephant family saw danger.", "vocab": [{"ko": "코끼리", "en": "elephant"}, {"ko": "가족", "en": "family"}, {"ko": "위험", "en": "danger"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending indicating completed action in informal polite speech. 보다 (see) → 봤어요 (saw).", "example_in_sentence": "봤어요"}]}, {"text": "무서운 것이 다가왔어요.", "translation": "Something scary came closer.", "vocab": [{"ko": "무섭다", "en": "to be scary; to be frightening"}, {"ko": "것", "en": "thing"}, {"ko": "다가오다", "en": "to approach; to come near"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 무섭다 (scary) → 무서운 것 (a scary thing).", "example_in_sentence": "무서운 것"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 다가오다 → 다가왔어요 (came closer).", "example_in_sentence": "다가왔어요"}]}, {"text": "코끼리들은 빨리 움직였어요.", "translation": "The elephants moved quickly.", "vocab": [{"ko": "빨리", "en": "quickly"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 움직이다 → 움직였어요 (moved).", "example_in_sentence": "움직였어요"}]}, {"text": "어른 코끼리들이 둥글게 섰어요.", "translation": "Adult elephants stood in a circle.", "vocab": [{"ko": "어른", "en": "adult"}, {"ko": "둥글다", "en": "to be round; circular"}, {"ko": "서다", "en": "to stand"}], "analysis": [{"type": "grammar", "label": "~게 (adverbial derivation)", "exp": "Converts adjective to adverb. 둥글다 (round) → 둥글게 (in a circular manner).", "example_in_sentence": "둥글게"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 서다 → 섰어요 (stood).", "example_in_sentence": "섰어요"}]}, {"text": "아기 코끼리를 가운데 두었어요.", "translation": "They put the baby elephant in the middle.", "vocab": [{"ko": "아기", "en": "baby"}, {"ko": "가운데", "en": "middle; center"}, {"ko": "두다", "en": "to place; to put"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 두다 → 두었어요 (placed; put).", "example_in_sentence": "두었어요"}]}, {"text": "위험한 것이 아기에게 오지 못하게 했어요.", "translation": "They prevented the dangerous thing from reaching the baby.", "vocab": [{"ko": "위험하다", "en": "to be dangerous"}, {"ko": "오다", "en": "to come"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 위험하다 (dangerous) → 위험한 것 (a dangerous thing).", "example_in_sentence": "위험한 것"}, {"type": "grammar", "label": "~지 못하다", "exp": "Negation of ability/possibility. 오다 → 오지 못하다 (cannot come; unable to reach).", "example_in_sentence": "오지 못하"}, {"type": "grammar", "label": "~게 하다", "exp": "Causative construction. Makes someone/something do or be in a state. 오지 못하다 → 오지 못하게 하다 (to cause/make unable to reach).", "example_in_sentence": "오지 못하게 했어요"}]}, {"text": "코끼리들은 서로 도와요.", "translation": "The elephants help each other.", "vocab": [{"ko": "서로", "en": "each other; mutually"}, {"ko": "돕다", "en": "to help"}], "analysis": [{"type": "grammar", "label": "~아/어요", "exp": "Present tense ending (informal polite). 돕다 → 도와요 (help).", "example_in_sentence": "도와요"}]}, {"text": "가족을 지키려고 해요.", "translation": "They try to protect their family.", "vocab": [{"ko": "가족", "en": "family"}, {"ko": "지키다", "en": "to protect; to keep"}], "analysis": [{"type": "grammar", "label": "~려고 하다", "exp": "Expresses intention or effort to do something. 지키다 → 지키려고 하다 (try to protect; aim to protect).", "example_in_sentence": "지키려고 해요"}]}, {"text": "아기가 다치지 않게 보호해요.", "translation": "They protect the baby so that it does not get hurt.", "vocab": [{"ko": "아기", "en": "baby"}, {"ko": "다치다", "en": "to get hurt; to be injured"}, {"ko": "보호하다", "en": "to protect"}], "analysis": [{"type": "grammar", "label": "~지 않다 (negation)", "exp": "Negates action/state. 다치다 → 다치지 않다 (not get hurt).", "example_in_sentence": "다치지 않"}, {"type": "grammar", "label": "~게 (adverbial purpose/result)", "exp": "Marks purpose or result. 다치지 않다 → 다치지 않게 (so as not to be hurt; in order not to be hurt).", "example_in_sentence": "다치지 않게"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense. 보호하다 → 보호해요 (protect).", "example_in_sentence": "보호해요"}]}, {"text": "동물들도 가족을 사랑해요.", "translation": "Animals also love their family.", "vocab": [{"ko": "동물", "en": "animal"}, {"ko": "가족", "en": "family"}, {"ko": "사랑하다", "en": "to love"}], "analysis": [{"type": "grammar", "label": "~도 (inclusive particle)", "exp": "Marks inclusive meaning ''also; too''. 동물도 (animals too).", "example_in_sentence": "동물들도"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense. 사랑하다 → 사랑해요 (love).", "example_in_sentence": "사랑해요"}]}, {"text": "우리 사람과 비슷해요.", "translation": "They are similar to us humans.", "vocab": [{"ko": "우리", "en": "us; we; our"}, {"ko": "사람", "en": "person; human"}, {"ko": "비슷하다", "en": "to be similar; to resemble"}], "analysis": [{"type": "grammar", "label": "~아/어요", "exp": "Present tense (informal polite). 비슷하다 → 비슷해요 (is similar).", "example_in_sentence": "비슷해요"}]}, {"text": "코끼리는 정말 똑똑한 동물이에요.", "translation": "Elephants are really intelligent animals.", "vocab": [{"ko": "코끼리", "en": "elephant"}, {"ko": "정말", "en": "really; truly"}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 똑똑하다 (smart) → 똑똑한 동물 (a smart animal).", "example_in_sentence": "똑똑한 동물"}, {"type": "grammar", "label": "이에요 (copula)", "exp": "Copula used after noun ending in consonant. Indicates ''is'' or ''to be''. 동물 + 이에요 (is an animal).", "example_in_sentence": "동물이에요"}]}], "version": "s6"}', vocab = '[{"ko": "코끼리", "en": "elephant", "note": ""}, {"ko": "가족", "en": "family", "note": ""}, {"ko": "위험", "en": "danger", "note": ""}, {"ko": "무섭다", "en": "to be scary; to be frightening", "note": ""}, {"ko": "것", "en": "thing", "note": ""}, {"ko": "다가오다", "en": "to approach; to come near", "note": ""}, {"ko": "빨리", "en": "quickly", "note": ""}, {"ko": "움직이다", "en": "to move", "note": ""}, {"ko": "어른", "en": "adult", "note": ""}, {"ko": "둥글다", "en": "to be round; circular", "note": ""}, {"ko": "서다", "en": "to stand", "note": ""}, {"ko": "아기", "en": "baby", "note": ""}, {"ko": "가운데", "en": "middle; center", "note": ""}, {"ko": "두다", "en": "to place; to put", "note": ""}, {"ko": "위험하다", "en": "to be dangerous", "note": ""}, {"ko": "오다", "en": "to come", "note": ""}, {"ko": "서로", "en": "each other; mutually", "note": ""}, {"ko": "돕다", "en": "to help", "note": ""}, {"ko": "지키다", "en": "to protect; to keep", "note": ""}, {"ko": "다치다", "en": "to get hurt; to be injured", "note": ""}, {"ko": "보호하다", "en": "to protect", "note": ""}, {"ko": "동물", "en": "animal", "note": ""}, {"ko": "사랑하다", "en": "to love", "note": ""}, {"ko": "우리", "en": "us; we; our", "note": ""}, {"ko": "사람", "en": "person; human", "note": ""}, {"ko": "비슷하다", "en": "to be similar; to resemble", "note": ""}, {"ko": "정말", "en": "really; truly", "note": ""}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Starter", "exp": "Past tense ending indicating completed action in informal polite speech. 보다 (see) → 봤어요 (saw).", "ex_ko": "코끼리 가족이 위험을 봤어요.", "ex_en": "The elephant family saw danger."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Starter", "exp": "Turns an adjective into a word that describes a noun. 위험하다 (dangerous) → 위험한 것 (a dangerous thing).", "ex_ko": "무서운 것이 다가왔어요.", "ex_en": "Something scary came closer."}, {"name": "~게 (adverbial purpose/result)", "level": "Starter", "exp": "Marks purpose or result. 다치지 않다 → 다치지 않게 (so as not to be hurt; in order not to be hurt).", "ex_ko": "어른 코끼리들이 둥글게 섰어요.", "ex_en": "Adult elephants stood in a circle."}, {"name": "~지 못하다", "level": "Starter", "exp": "Negation of ability/possibility. 오다 → 오지 못하다 (cannot come; unable to reach).", "ex_ko": "위험한 것이 아기에게 오지 못하게 했어요.", "ex_en": "They prevented the dangerous thing from reaching the baby."}, {"name": "~게 하다", "level": "Starter", "exp": "Causative construction. Makes someone/something do or be in a state. 오지 못하다 → 오지 못하게 하다 (to cause/make unable to reach).", "ex_ko": "위험한 것이 아기에게 오지 못하게 했어요.", "ex_en": "They prevented the dangerous thing from reaching the baby."}, {"name": "~아/어요", "level": "Starter", "exp": "Present tense (informal polite). 비슷하다 → 비슷해요 (is similar).", "ex_ko": "코끼리들은 서로 도와요.", "ex_en": "The elephants help each other."}, {"name": "~려고 하다", "level": "Starter", "exp": "Expresses intention or effort to do something. 지키다 → 지키려고 하다 (try to protect; aim to protect).", "ex_ko": "가족을 지키려고 해요.", "ex_en": "They try to protect their family."}, {"name": "~지 않다 (negation)", "level": "Starter", "exp": "Negates action/state. 다치다 → 다치지 않다 (not get hurt).", "ex_ko": "아기가 다치지 않게 보호해요.", "ex_en": "They protect the baby so that it does not get hurt."}, {"name": "~도 (inclusive particle)", "level": "Starter", "exp": "Marks inclusive meaning ''also; too''. 동물도 (animals too).", "ex_ko": "동물들도 가족을 사랑해요.", "ex_en": "Animals also love their family."}, {"name": "이에요 (copula)", "level": "Starter", "exp": "Copula used after noun ending in consonant. Indicates ''is'' or ''to be''. 동물 + 이에요 (is an animal).", "ex_ko": "코끼리는 정말 똑똑한 동물이에요.", "ex_en": "Elephants are really intelligent animals."}]}', updated_at = now() where article_id = 'mom3v8318vpi' and md5(translation) = 'fb48aab61471e64e977c0ce3ec3a7236';
update public.article_cache set translation = '{"texts": ["Yesterday was April 30th. Eighty-one years ago on this day, Adolf Hitler, a leader of Germany, died. Hitler passed away on April 30th, 1945. That was when World War II was almost coming to an end. Hitler was a person who started many wars. Many people all around the world suffered. He particularly tormented many Jewish people. Now I hope that such things never happen again. I want to live in a peaceful world.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "어제는 4월 30일이었어요.", "translation": "Yesterday was April 30th.", "vocab": [{"ko": "어제", "en": "yesterday"}, {"ko": "4월", "en": "April"}], "analysis": [{"type": "grammar", "label": "~였어요/이었어요 (past of 이다)", "exp": "Past tense of 이다 (to be). After a consonant use 이었어요: 30일 → 30일이었어요 (was the 30th).", "example_in_sentence": "이었어요"}]}, {"text": "81년 전 이날, 독일의 지도자였던 아돌프 히틀러가 죽었어요.", "translation": "On this day 81 years ago, Adolf Hitler, who was the leader of Germany, died.", "vocab": [{"ko": "지도자", "en": "leader"}, {"ko": "죽다", "en": "to die"}], "analysis": [{"type": "grammar", "label": "~았/었던", "exp": "Describes a noun by a past state that is no longer true. 지도자이다 → 지도자였던 (who was the leader).", "example_in_sentence": "지도자였던"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 죽다 + 었어요 → 죽었어요.", "example_in_sentence": "죽었어요"}]}, {"text": "히틀러는 1945년 4월 30일에 세상을 떠났어요.", "translation": "Hitler passed away on April 30th, 1945.", "vocab": [{"ko": "세상", "en": "world; life"}, {"ko": "떠나다", "en": "to leave; to pass away"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 떠나다 + 았어요 → 떠났어요.", "example_in_sentence": "떠났어요"}]}, {"text": "그때는 제2차 세계 대전이 거의 끝날 때였어요.", "translation": "At that time, the Second World War was almost over.", "vocab": [{"ko": "제2차", "en": "second (ordinal)"}, {"ko": "세계 대전", "en": "world war"}, {"ko": "거의", "en": "almost; nearly"}, {"ko": "끝나다", "en": "to end"}], "analysis": [{"type": "grammar", "label": "~ㄹ 때", "exp": "Temporal expression marking ''the time when''. Prospective modifier + 때 (time). 끝나다 + ㄹ → 끝날 때.", "example_in_sentence": "끝날 때"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 이다 + 었어요 → 였어요.", "example_in_sentence": "였어요"}]}, {"text": "히틀러는 많은 전쟁을 일으킨 사람이에요.", "translation": "Hitler is a person who caused many wars.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "전쟁", "en": "war"}, {"ko": "일으키다", "en": "to cause; to start"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 일으키다 (to cause) → 일으킨 사람 (a person who caused).", "example_in_sentence": "일으킨 사람"}]}, {"text": "전 세계 많은 사람들이 힘들어했어요.", "translation": "Many people around the world suffered.", "vocab": [{"ko": "전 세계", "en": "whole world; worldwide"}, {"ko": "힘들어하다", "en": "to have a hard time; to struggle"}], "analysis": [{"type": "grammar", "label": "~아/어하다", "exp": "Turns a feeling adjective into a verb that describes how someone feels or acts. 힘들다 (hard) → 힘들어하다 (to have a hard time).", "example_in_sentence": "힘들어했어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 힘들어하다 + 었어요 → 힘들어했어요.", "example_in_sentence": "힘들어했어요"}]}, {"text": "특히 유대인들을 많이 괴롭혔어요.", "translation": "He especially tormented many Jewish people.", "vocab": [{"ko": "특히", "en": "especially; particularly"}, {"ko": "유대인", "en": "Jewish person"}, {"ko": "괴롭히다", "en": "to torment; to harass"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 괴롭히다 + 었어요 → 괴롭혔어요.", "example_in_sentence": "괴롭혔어요"}]}, {"text": "지금은 그런 일이 다시 일어나지 않기를 바라요.", "translation": "Now I hope that such things do not happen again.", "vocab": [{"ko": "그런", "en": "such; that kind of"}, {"ko": "다시", "en": "again"}, {"ko": "일어나다", "en": "to happen; to occur"}, {"ko": "바라다", "en": "to hope; to wish"}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Negation. 일어나다 + 지 않다 → 일어나지 않다.", "example_in_sentence": "일어나지 않기"}, {"type": "grammar", "label": "~기를 바라다", "exp": "Expression of hope/wish. Nominalizer ~기 + object marker 를 + 바라다 (to hope). Indicates wishing for a certain action or state.", "example_in_sentence": "일어나지 않기를 바라요"}]}, {"text": "평화로운 세상에서 살고 싶어요.", "translation": "I want to live in a peaceful world.", "vocab": [{"ko": "평화롭다", "en": "to be peaceful"}, {"ko": "세상", "en": "world"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~고 싶다", "exp": "Auxiliary expression of desire/wish. ~고 싶어요 indicates wanting to do something.", "example_in_sentence": "살고 싶어요"}]}], "version": "s6"}', vocab = '[{"ko": "어제", "en": "yesterday", "note": ""}, {"ko": "4월", "en": "April", "note": ""}, {"ko": "지도자", "en": "leader", "note": ""}, {"ko": "죽다", "en": "to die", "note": ""}, {"ko": "세상", "en": "world; life", "note": ""}, {"ko": "떠나다", "en": "to leave; to pass away", "note": ""}, {"ko": "제2차", "en": "second (ordinal)", "note": ""}, {"ko": "세계 대전", "en": "world war", "note": ""}, {"ko": "거의", "en": "almost; nearly", "note": ""}, {"ko": "끝나다", "en": "to end", "note": ""}, {"ko": "많다", "en": "to be many; to be a lot", "note": ""}, {"ko": "전쟁", "en": "war", "note": ""}, {"ko": "일으키다", "en": "to cause; to start", "note": ""}, {"ko": "전 세계", "en": "whole world; worldwide", "note": ""}, {"ko": "힘들어하다", "en": "to have a hard time; to struggle", "note": ""}, {"ko": "특히", "en": "especially; particularly", "note": ""}, {"ko": "유대인", "en": "Jewish person", "note": ""}, {"ko": "괴롭히다", "en": "to torment; to harass", "note": ""}, {"ko": "그런", "en": "such; that kind of", "note": ""}, {"ko": "다시", "en": "again", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}, {"ko": "바라다", "en": "to hope; to wish", "note": ""}, {"ko": "평화롭다", "en": "to be peaceful", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"word": "제2차 세계 대전", "reading": "je2cha segyae daejeon", "meaning": "World War II; the second world war", "context": "제2차 세계 대전이 거의 끝날 때였어요"}, {"word": "평화", "reading": "pyeonghwa", "meaning": "peace; a state of tranquility and absence of conflict", "context": "평화로운 세상에서 살고 싶어요"}]', grammar = '{"patterns": [{"name": "~였어요/이었어요 (past of 이다)", "level": "Beginner", "exp": "Past tense of 이다 (to be). After a consonant use 이었어요: 30일 → 30일이었어요 (was the 30th).", "ex_ko": "어제는 4월 30일이었어요.", "ex_en": "Yesterday was April 30th."}, {"name": "~았/었던", "level": "Beginner", "exp": "Describes a noun by a past state that is no longer true. 지도자이다 → 지도자였던 (who was the leader).", "ex_ko": "81년 전 이날, 독일의 지도자였던 아돌프 히틀러가 죽었어요.", "ex_en": "On this day 81 years ago, Adolf Hitler, who was the leader of Germany, died."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending. 힘들어하다 + 었어요 → 힘들어했어요.", "ex_ko": "81년 전 이날, 독일의 지도자였던 아돌프 히틀러가 죽었어요.", "ex_en": "On this day 81 years ago, Adolf Hitler, who was the leader of Germany, died."}, {"name": "~ㄹ 때", "level": "Beginner", "exp": "Temporal expression marking ''the time when''. Prospective modifier + 때 (time). 끝나다 + ㄹ → 끝날 때.", "ex_ko": "그때는 제2차 세계 대전이 거의 끝날 때였어요.", "ex_en": "At that time, the Second World War was almost over."}, {"name": "~(으)ㄴ (past verb modifier)", "level": "Beginner", "exp": "Describes a noun with a completed action. 일으키다 (to cause) → 일으킨 사람 (a person who caused).", "ex_ko": "히틀러는 많은 전쟁을 일으킨 사람이에요.", "ex_en": "Hitler is a person who caused many wars."}, {"name": "~아/어하다", "level": "Beginner", "exp": "Turns a feeling adjective into a verb that describes how someone feels or acts. 힘들다 (hard) → 힘들어하다 (to have a hard time).", "ex_ko": "전 세계 많은 사람들이 힘들어했어요.", "ex_en": "Many people around the world suffered."}, {"name": "~지 않다", "level": "Beginner", "exp": "Negation. 일어나다 + 지 않다 → 일어나지 않다.", "ex_ko": "지금은 그런 일이 다시 일어나지 않기를 바라요.", "ex_en": "Now I hope that such things do not happen again."}, {"name": "~기를 바라다", "level": "Beginner", "exp": "Expression of hope/wish. Nominalizer ~기 + object marker 를 + 바라다 (to hope). Indicates wishing for a certain action or state.", "ex_ko": "지금은 그런 일이 다시 일어나지 않기를 바라요.", "ex_en": "Now I hope that such things do not happen again."}, {"name": "~고 싶다", "level": "Beginner", "exp": "Auxiliary expression of desire/wish. ~고 싶어요 indicates wanting to do something.", "ex_ko": "평화로운 세상에서 살고 싶어요.", "ex_en": "I want to live in a peaceful world."}]}', updated_at = now() where article_id = 'mom3vpwtppus' and md5(translation) = '4c0f191fdeb66665ec95bd33898c9f6a';
update public.article_cache set translation = '{"texts": ["A major earthquake occurred in Izmir, Turkey in 2020. Many buildings collapsed and people were trapped. At this time, one man saved many lives.", "That man''s name is Rıdvan Çelik. He was born without arms. However, he did not think of this as a problem.", "When the earthquake occurred, Mr. Çelik entered between the collapsed buildings. His small body could pass through narrow spaces. Without arms, he could move more easily.", "He found people trapped inside the collapsed buildings. He saved many people''s lives. People call him a hero. He turned his uniqueness into an advantage."], "sentences": [{"text": "2020년 터키 이즈미르에서 큰 지진이 일어났어요.", "translation": "A large earthquake occurred in Izmir, Turkey in 2020.", "vocab": [{"ko": "지진", "en": "earthquake"}, {"ko": "일어나다", "en": "to occur, happen"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for completed action. 일어나다 (occur) + 았어요 = 일어났어요 (occurred).", "example_in_sentence": "일어났어요"}]}, {"text": "많은 건물이 무너지고 사람들이 갇혔어요.", "translation": "Many buildings collapsed and people became trapped.", "vocab": [{"ko": "건물", "en": "building"}, {"ko": "무너지다", "en": "to collapse"}, {"ko": "갇히다", "en": "to be trapped"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending that links two sequential or concurrent actions. 무너지고 = collapsed and (then).", "example_in_sentence": "무너지고"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 갇히다 + 었어요 = 갇혔어요 (became trapped).", "example_in_sentence": "갇혔어요"}]}, {"text": "이때 한 남성이 많은 생명을 구했어요.", "translation": "At this time, one man saved many lives.", "vocab": [{"ko": "남성", "en": "man, male"}, {"ko": "생명", "en": "life"}, {"ko": "구하다", "en": "to save, rescue"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 구하다 + 았어요 = 구했어요 (saved).", "example_in_sentence": "구했어요"}]}, {"text": "그 사람의 이름은 리드반 첼리크예요.", "translation": "That person''s name is Rıdvan Çelik.", "vocab": [{"ko": "이름", "en": "name"}], "analysis": [{"type": "grammar", "label": "~예요/이에요", "exp": "Polite form of 이다 (to be). After a vowel use 예요: 첼리크 → 첼리크예요 (is Çelik).", "example_in_sentence": "첼리크예요"}]}, {"text": "그는 태어날 때부터 팔이 없었어요.", "translation": "He had no arms from the time of birth.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "팔", "en": "arm"}, {"ko": "없다", "en": "to not have, to be absent"}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 때부터", "exp": "Means ''from the time when''. 태어나다 (to be born) → 태어날 때부터 (since he was born).", "example_in_sentence": "태어날 때부터"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 없다 + 었어요 = 없었어요 (was absent, had not).", "example_in_sentence": "없었어요"}]}, {"text": "하지만 이것을 문제라고 생각하지 않았어요.", "translation": "However, he did not think of this as a problem.", "vocab": [{"ko": "하지만", "en": "however, but"}, {"ko": "문제", "en": "problem"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~(이)라고 생각하다", "exp": "Says what you think something is. 문제 + 라고 생각하다 → to think of it as a problem.", "example_in_sentence": "문제라고 생각하지"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation suffix. 생각하다 + 지 않았어요 = did not think.", "example_in_sentence": "생각하지 않았어요"}]}, {"text": "지진이 일어났을 때 첼리크 씨는 무너진 건물 사이로 들어갔어요.", "translation": "When the earthquake occurred, Mr. Çelik went into the space between collapsed buildings.", "vocab": [{"ko": "지진", "en": "earthquake"}, {"ko": "일어나다", "en": "to occur"}, {"ko": "무너지다", "en": "to collapse"}, {"ko": "들어가다", "en": "to go in, enter"}], "analysis": [{"type": "expression", "label": "~ 사이로", "exp": "Through/into the space/gap between. 건물 사이 (space between buildings) + 로 (motion into).", "example_in_sentence": "건물 사이로"}, {"type": "grammar", "label": "~았/었을 때", "exp": "When a past action occurred. 일어나다 + 았을 때 = when occurred.", "example_in_sentence": "일어났을 때"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 들어가다 (to go in) → 들어갔어요 (went in).", "example_in_sentence": "들어갔어요"}]}, {"text": "그의 작은 몸은 좁은 공간을 통과할 수 있었어요.", "translation": "His small body was able to pass through narrow spaces.", "vocab": [{"ko": "작다", "en": "to be small"}, {"ko": "좁다", "en": "to be narrow"}, {"ko": "공간", "en": "space"}, {"ko": "통과하다", "en": "to pass through"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability or possibility marker. 통과하다 + ㄹ 수 있었어요 = was able to pass through.", "example_in_sentence": "통과할 수 있었어요"}]}, {"text": "팔이 없어서 더 쉽게 움직일 수 있었어요.", "translation": "Because he had no arms, he was able to move more easily.", "vocab": [{"ko": "팔", "en": "arm"}, {"ko": "없다", "en": "to not have"}, {"ko": "쉽다", "en": "to be easy"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "grammar", "label": "~어서", "exp": "Causal or sequential connective. 없어서 = because (he had no arms).", "example_in_sentence": "없어서"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability or possibility. 움직이다 + ㄹ 수 있었어요 = was able to move.", "example_in_sentence": "움직일 수 있었어요"}]}, {"text": "그는 무너진 건물 안에 갇힌 사람들을 찾았어요.", "translation": "He found people trapped inside the collapsed building.", "vocab": [{"ko": "무너지다", "en": "to collapse"}, {"ko": "건물", "en": "building"}, {"ko": "갇히다", "en": "to be trapped"}, {"ko": "찾다", "en": "to find"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 갇히다 (to be trapped) → 갇힌 사람들 (people who were trapped).", "example_in_sentence": "갇힌 사람들"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 찾다 + 았어요 = 찾았어요 (found).", "example_in_sentence": "찾았어요"}]}, {"text": "많은 사람들의 생명을 구했어요.", "translation": "He saved the lives of many people.", "vocab": [{"ko": "사람", "en": "person, people"}, {"ko": "생명", "en": "life"}, {"ko": "구하다", "en": "to save, rescue"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 구하다 + 았어요 = 구했어요 (saved).", "example_in_sentence": "구했어요"}]}, {"text": "사람들은 그를 영웅이라고 불러요.", "translation": "People call him a hero.", "vocab": [{"ko": "사람", "en": "person, people"}, {"ko": "영웅", "en": "hero"}, {"ko": "부르다", "en": "to call"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다", "exp": "Says what someone is called. 영웅 + 이라고 부르다 → to call (him) a hero.", "example_in_sentence": "영웅이라고 불러요"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 부르다 is a 르-irregular verb: 부르다 → 불러요 (call).", "example_in_sentence": "불러요"}]}, {"text": "그는 자신의 특별함을 장점으로 만들었어요.", "translation": "He turned his uniqueness into an advantage.", "vocab": [{"ko": "특별함", "en": "uniqueness; specialness"}, {"ko": "장점", "en": "advantage, strength"}, {"ko": "만들다", "en": "to make"}], "analysis": [{"type": "grammar", "label": "~으로", "exp": "Into/as (transformation marker). 장점 + 으로 = into an advantage.", "example_in_sentence": "장점으로"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 만들다 + 었어요 = 만들었어요 (made, turned into).", "example_in_sentence": "만들었어요"}]}], "version": "s6"}', vocab = '[{"ko": "지진", "en": "earthquake", "note": ""}, {"ko": "일어나다", "en": "to occur, happen", "note": ""}, {"ko": "건물", "en": "building", "note": ""}, {"ko": "무너지다", "en": "to collapse", "note": ""}, {"ko": "갇히다", "en": "to be trapped", "note": ""}, {"ko": "남성", "en": "man, male", "note": ""}, {"ko": "생명", "en": "life", "note": ""}, {"ko": "구하다", "en": "to save, rescue", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "태어나다", "en": "to be born", "note": ""}, {"ko": "팔", "en": "arm", "note": ""}, {"ko": "없다", "en": "to not have, to be absent", "note": ""}, {"ko": "하지만", "en": "however, but", "note": ""}, {"ko": "문제", "en": "problem", "note": ""}, {"ko": "생각하다", "en": "to think", "note": ""}, {"ko": "들어가다", "en": "to go in, enter", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "좁다", "en": "to be narrow", "note": ""}, {"ko": "공간", "en": "space", "note": ""}, {"ko": "통과하다", "en": "to pass through", "note": ""}, {"ko": "쉽다", "en": "to be easy", "note": ""}, {"ko": "움직이다", "en": "to move", "note": ""}, {"ko": "찾다", "en": "to find", "note": ""}, {"ko": "사람", "en": "person, people", "note": ""}, {"ko": "영웅", "en": "hero", "note": ""}, {"ko": "부르다", "en": "to call", "note": ""}, {"ko": "특별함", "en": "uniqueness; specialness", "note": ""}, {"ko": "장점", "en": "advantage, strength", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending for completed action. 일어나다 (occur) + 았어요 = 일어났어요 (occurred).", "ex_ko": "2020년 터키 이즈미르에서 큰 지진이 일어났어요.", "ex_en": "A large earthquake occurred in Izmir, Turkey in 2020."}, {"name": "~고", "level": "Beginner", "exp": "Connective ending that links two sequential or concurrent actions. 무너지고 = collapsed and (then).", "ex_ko": "많은 건물이 무너지고 사람들이 갇혔어요.", "ex_en": "Many buildings collapsed and people became trapped."}, {"name": "~예요/이에요", "level": "Beginner", "exp": "Polite form of 이다 (to be). After a vowel use 예요: 첼리크 → 첼리크예요 (is Çelik).", "ex_ko": "그 사람의 이름은 리드반 첼리크예요.", "ex_en": "That person''s name is Rıdvan Çelik."}, {"name": "~(이)라고 생각하다", "level": "Beginner", "exp": "Says what you think something is. 문제 + 라고 생각하다 → to think of it as a problem.", "ex_ko": "하지만 이것을 문제라고 생각하지 않았어요.", "ex_en": "However, he did not think of this as a problem."}, {"name": "~지 않다", "level": "Beginner", "exp": "Negation suffix. 생각하다 + 지 않았어요 = did not think.", "ex_ko": "하지만 이것을 문제라고 생각하지 않았어요.", "ex_en": "However, he did not think of this as a problem."}, {"name": "~았/었을 때", "level": "Beginner", "exp": "When a past action occurred. 일어나다 + 았을 때 = when occurred.", "ex_ko": "지진이 일어났을 때 첼리크 씨는 무너진 건물 사이로 들어갔어요.", "ex_en": "When the earthquake occurred, Mr. Çelik went into the space between collapsed buildings."}, {"name": "~ㄹ 수 있다", "level": "Beginner", "exp": "Ability or possibility marker. 통과하다 + ㄹ 수 있었어요 = was able to pass through.", "ex_ko": "그의 작은 몸은 좁은 공간을 통과할 수 있었어요.", "ex_en": "His small body was able to pass through narrow spaces."}, {"name": "~어서", "level": "Beginner", "exp": "Causal or sequential connective. 없어서 = because (he had no arms).", "ex_ko": "팔이 없어서 더 쉽게 움직일 수 있었어요.", "ex_en": "Because he had no arms, he was able to move more easily."}, {"name": "~(이)라고 부르다", "level": "Beginner", "exp": "Says what someone is called. 영웅 + 이라고 부르다 → to call (him) a hero.", "ex_ko": "사람들은 그를 영웅이라고 불러요.", "ex_en": "People call him a hero."}, {"name": "~아/어요", "level": "Beginner", "exp": "Polite present ending. 부르다 is a 르-irregular verb: 부르다 → 불러요 (call).", "ex_ko": "사람들은 그를 영웅이라고 불러요.", "ex_en": "People call him a hero."}, {"name": "~으로", "level": "Beginner", "exp": "Into/as (transformation marker). 장점 + 으로 = into an advantage.", "ex_ko": "그는 자신의 특별함을 장점으로 만들었어요.", "ex_en": "He turned his uniqueness into an advantage."}]}', updated_at = now() where article_id = 'mom3wbgtgfsc' and md5(translation) = '0c3eafc1e06a3d3c636865fb3aae143b';
update public.article_cache set translation = '{"texts": ["Bulgaria has the Prohodna Cave. This cave has a very special appearance.", "There are two large holes in the cave ceiling. These holes look like a person''s eyes. That''s why people call it the ''Eyes of the Cave.''", "This cave is a work created by nature. Over a long time, rain and wind carved the rocks, and it became this way.", "Many tourists come to see this mysterious cave. Especially when sunlight enters through the holes, it is really beautiful. You can understand how great the power of nature is."], "sentences": [{"text": "불가리아에는 프로호드나 동굴이 있어요.", "translation": "Bulgaria has the Prohodna Cave.", "vocab": [{"ko": "불가리아", "en": "Bulgaria"}, {"ko": "동굴", "en": "cave"}, {"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "The place particle 에 plus the topic marker 는, making the place the topic. 불가리아에는 = in Bulgaria (as for Bulgaria).", "example_in_sentence": "불가리아에는"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 있다 (to exist) → 있어요 (there is).", "example_in_sentence": "있어요"}]}, {"text": "이 동굴은 매우 특별한 모습을 하고 있어요.", "translation": "This cave has a very special appearance.", "vocab": [{"ko": "매우", "en": "very; extremely"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "모습", "en": "appearance; look"}, {"ko": "하다", "en": "to do; to have (with certain nouns)"}], "analysis": [{"type": "grammar", "label": "~은", "exp": "Topic-marking particle for subjects after consonants. Marks the topic of the sentence.", "example_in_sentence": "동굴은"}, {"type": "expression", "label": "모습을 하다", "exp": "Collocation meaning ''to have an appearance'' or ''to look like.'' 모습 (appearance) + 을 (object particle) + 하다 (to do).", "example_in_sentence": "모습을 하고"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect: describes ongoing state or action. 고 (connective suffix) + 있다 (to be in a state) + ~어요 (polite ending).", "example_in_sentence": "하고 있어요"}]}, {"text": "동굴 천장에 두 개의 큰 구멍이 있어요.", "translation": "There are two large holes in the cave ceiling.", "vocab": [{"ko": "천장", "en": "ceiling"}, {"ko": "두 개", "en": "two (items)"}, {"ko": "크다", "en": "to be large; big"}, {"ko": "구멍", "en": "hole"}], "analysis": [{"type": "grammar", "label": "~에", "exp": "Locative particle indicating location (in/at/on). Attaches to nouns marking where something exists.", "example_in_sentence": "천장에"}, {"type": "grammar", "label": "~의", "exp": "Links a number to its noun. 두 개의 구멍 = two holes (also said 구멍 두 개).", "example_in_sentence": "두 개의"}]}, {"text": "이 구멍들이 사람의 눈처럼 보여요.", "translation": "These holes look like human eyes.", "vocab": [{"ko": "구멍", "en": "hole"}, {"ko": "사람", "en": "person; human"}, {"ko": "눈", "en": "eye"}, {"ko": "보이다", "en": "to look; to appear"}], "analysis": [{"type": "grammar", "label": "~처럼", "exp": "Postposition meaning ''like'' or ''similar to.'' Attaches to nouns to indicate comparison.", "example_in_sentence": "눈처럼"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending. 보이다 (to look/appear) + ~어요.", "example_in_sentence": "보여요"}]}, {"text": "그래서 사람들이 ''동굴의 눈''이라고 불러요.", "translation": "That is why people call it ''the eyes of the cave.''", "vocab": [{"ko": "그래서", "en": "so; therefore"}, {"ko": "사람들", "en": "people"}, {"ko": "부르다", "en": "to call; to name"}], "analysis": [{"type": "grammar", "label": "~이라고", "exp": "Quotative particle indicating reported speech or naming. Used to introduce what something is called or said to be.", "example_in_sentence": "''동굴의 눈''이라고"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending. 부르다 (to call) + ~어요.", "example_in_sentence": "불러요"}]}, {"text": "이 동굴은 자연이 만든 작품이에요.", "translation": "This cave is a work created by nature.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "만들다", "en": "to make; to create"}, {"ko": "작품", "en": "work (of art); masterpiece"}], "analysis": [{"type": "grammar", "label": "~은", "exp": "Topic-marking particle after consonants. Marks the subject.", "example_in_sentence": "동굴은"}, {"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 만들다 drops ㄹ: 만들다 → 만든 작품 (a work that was made).", "example_in_sentence": "만든 작품"}, {"type": "grammar", "label": "~이에요", "exp": "Copula (to be) with polite ending. Indicates identity/classification after consonant-final nouns.", "example_in_sentence": "작품이에요"}]}, {"text": "오랜 시간 동안 비와 바람이 바위를 깎아서 이런 모습이 되었어요.", "translation": "Over a long time, rain and wind carved the rock into this shape.", "vocab": [{"ko": "오랜", "en": "long (duration)"}, {"ko": "시간", "en": "time"}, {"ko": "비", "en": "rain"}, {"ko": "바람", "en": "wind"}], "analysis": [{"type": "expression", "label": "~ 동안", "exp": "Means ''for / during (a period of time)''. 오랜 시간 동안 = for a long time.", "example_in_sentence": "오랜 시간 동안"}, {"type": "grammar", "label": "~와", "exp": "Conjunction particle meaning ''and.'' Connects two nouns as coordinate subjects/objects.", "example_in_sentence": "비와"}, {"type": "grammar", "label": "~를", "exp": "Object particle after vowel-final nouns. Marks the direct object of the verb.", "example_in_sentence": "바위를"}, {"type": "grammar", "label": "~아서", "exp": "Connective suffix indicating sequential/causal relationship. 깎다 (to carve) + ~아서 + following clause with 되다 (to become).", "example_in_sentence": "깎아서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 되다 (to become) → 되었어요 (became).", "example_in_sentence": "되었어요"}]}, {"text": "많은 관광객들이 이 신비한 동굴을 보러 와요.", "translation": "Many tourists come to see this mysterious cave.", "vocab": [{"ko": "많다", "en": "to be many; numerous"}, {"ko": "관광객", "en": "tourist"}, {"ko": "신비하다", "en": "to be mysterious"}, {"ko": "보다", "en": "to see; to watch"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 많다 (many) → 많은 관광객들 (many tourists).", "example_in_sentence": "많은 관광객들"}, {"type": "grammar", "label": "~을", "exp": "Object particle after consonant-final nouns. Marks direct object of 보다 (to see).", "example_in_sentence": "동굴을"}, {"type": "grammar", "label": "~(으)러 오다", "exp": "Shows the purpose of coming or going. 보다 (to see) → 보러 와요 (come to see).", "example_in_sentence": "보러 와요"}]}, {"text": "특히 햇빛이 구멍을 통해 들어올 때 정말 아름다워요.", "translation": "Especially when sunlight enters through the holes, it is truly beautiful.", "vocab": [{"ko": "특히", "en": "especially; in particular"}, {"ko": "햇빛", "en": "sunlight"}, {"ko": "구멍", "en": "hole"}, {"ko": "통하다", "en": "to pass through"}], "analysis": [{"type": "expression", "label": "~을 통해", "exp": "Postposition phrase meaning ''through'' or ''via.'' Indicates a medium or path.", "example_in_sentence": "구멍을 통해"}, {"type": "grammar", "label": "~(으)ㄹ 때", "exp": "Means ''when''. 들어오다 (to come in) → 들어올 때 (when it comes in).", "example_in_sentence": "들어올 때"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 아름답다 is ㅂ-irregular: 아름답다 → 아름다워요 (is beautiful).", "example_in_sentence": "아름다워요"}]}, {"text": "자연의 힘이 얼마나 대단한지 알 수 있어요.", "translation": "You can see how great the power of nature is.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "힘", "en": "power; strength"}, {"ko": "얼마나", "en": "how much; how great"}, {"ko": "대단하다", "en": "to be great; remarkable"}], "analysis": [{"type": "grammar", "label": "~의", "exp": "Possessive particle linking two nouns. 자연 (nature) + ~의 + 힘 (power).", "example_in_sentence": "자연의"}, {"type": "grammar", "label": "~이/가 (subject particle)", "exp": "Marks the subject. After a consonant use 이: 힘 → 힘이.", "example_in_sentence": "힘이"}, {"type": "grammar", "label": "~(으)ㄴ지", "exp": "Turns a question into part of the sentence: ''how / whether''. 대단하다 → 대단한지 알다 (to know how great it is).", "example_in_sentence": "대단한지"}, {"type": "expression", "label": "~ㄹ 수 있다", "exp": "Capability/possibility expression ''can; able to.'' 알다 (to know) + ~ㄹ 수 있다.", "example_in_sentence": "알 수 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "불가리아", "en": "Bulgaria", "note": ""}, {"ko": "동굴", "en": "cave", "note": ""}, {"ko": "있다", "en": "to exist; to have", "note": ""}, {"ko": "매우", "en": "very; extremely", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "모습", "en": "appearance; look", "note": ""}, {"ko": "하다", "en": "to do; to have (with certain nouns)", "note": ""}, {"ko": "천장", "en": "ceiling", "note": ""}, {"ko": "두 개", "en": "two (items)", "note": ""}, {"ko": "크다", "en": "to be large; big", "note": ""}, {"ko": "구멍", "en": "hole", "note": ""}, {"ko": "사람", "en": "person; human", "note": ""}, {"ko": "눈", "en": "eye", "note": ""}, {"ko": "보이다", "en": "to look; to appear", "note": ""}, {"ko": "그래서", "en": "so; therefore", "note": ""}, {"ko": "사람들", "en": "people", "note": ""}, {"ko": "부르다", "en": "to call; to name", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "만들다", "en": "to make; to create", "note": ""}, {"ko": "작품", "en": "work (of art); masterpiece", "note": ""}, {"ko": "오랜", "en": "long (duration)", "note": ""}, {"ko": "시간", "en": "time", "note": ""}, {"ko": "비", "en": "rain", "note": ""}, {"ko": "바람", "en": "wind", "note": ""}, {"ko": "많다", "en": "to be many; numerous", "note": ""}, {"ko": "관광객", "en": "tourist", "note": ""}, {"ko": "신비하다", "en": "to be mysterious", "note": ""}, {"ko": "보다", "en": "to see; to watch", "note": ""}, {"ko": "특히", "en": "especially; in particular", "note": ""}, {"ko": "햇빛", "en": "sunlight", "note": ""}, {"ko": "통하다", "en": "to pass through", "note": ""}, {"ko": "힘", "en": "power; strength", "note": ""}, {"ko": "얼마나", "en": "how much; how great", "note": ""}, {"ko": "대단하다", "en": "to be great; remarkable", "note": ""}, {"word": "바위", "reading": "bawi", "meaning": "rock; stone", "context": "비와 바람이 바위를 깎아서 이런 모습이 되었어요"}]', grammar = '{"patterns": [{"name": "~에는", "level": "Beginner", "exp": "The place particle 에 plus the topic marker 는, making the place the topic. 불가리아에는 = in Bulgaria (as for Bulgaria).", "ex_ko": "불가리아에는 프로호드나 동굴이 있어요.", "ex_en": "Bulgaria has the Prohodna Cave."}, {"name": "~아/어요", "level": "Beginner", "exp": "Polite present ending. 아름답다 is ㅂ-irregular: 아름답다 → 아름다워요 (is beautiful).", "ex_ko": "불가리아에는 프로호드나 동굴이 있어요.", "ex_en": "Bulgaria has the Prohodna Cave."}, {"name": "~은", "level": "Beginner", "exp": "Topic-marking particle for subjects after consonants. Marks the topic of the sentence.", "ex_ko": "이 동굴은 매우 특별한 모습을 하고 있어요.", "ex_en": "This cave has a very special appearance."}, {"name": "~고 있어요", "level": "Beginner", "exp": "Progressive aspect: describes ongoing state or action. 고 (connective suffix) + 있다 (to be in a state) + ~어요 (polite ending).", "ex_ko": "이 동굴은 매우 특별한 모습을 하고 있어요.", "ex_en": "This cave has a very special appearance."}, {"name": "~에", "level": "Beginner", "exp": "Locative particle indicating location (in/at/on). Attaches to nouns marking where something exists.", "ex_ko": "동굴 천장에 두 개의 큰 구멍이 있어요.", "ex_en": "There are two large holes in the cave ceiling."}, {"name": "~의", "level": "Beginner", "exp": "Possessive particle linking two nouns. 자연 (nature) + ~의 + 힘 (power).", "ex_ko": "동굴 천장에 두 개의 큰 구멍이 있어요.", "ex_en": "There are two large holes in the cave ceiling."}, {"name": "~처럼", "level": "Beginner", "exp": "Postposition meaning ''like'' or ''similar to.'' Attaches to nouns to indicate comparison.", "ex_ko": "이 구멍들이 사람의 눈처럼 보여요.", "ex_en": "These holes look like human eyes."}, {"name": "~어요", "level": "Beginner", "exp": "Present tense polite ending. 보이다 (to look/appear) + ~어요.", "ex_ko": "이 구멍들이 사람의 눈처럼 보여요.", "ex_en": "These holes look like human eyes."}, {"name": "~이라고", "level": "Beginner", "exp": "Quotative particle indicating reported speech or naming. Used to introduce what something is called or said to be.", "ex_ko": "그래서 사람들이 ''동굴의 눈''이라고 불러요.", "ex_en": "That is why people call it ''the eyes of the cave.''"}, {"name": "~(으)ㄴ (past verb modifier)", "level": "Beginner", "exp": "Describes a noun with a completed action. 만들다 drops ㄹ: 만들다 → 만든 작품 (a work that was made).", "ex_ko": "이 동굴은 자연이 만든 작품이에요.", "ex_en": "This cave is a work created by nature."}, {"name": "~이에요", "level": "Beginner", "exp": "Copula (to be) with polite ending. Indicates identity/classification after consonant-final nouns.", "ex_ko": "이 동굴은 자연이 만든 작품이에요.", "ex_en": "This cave is a work created by nature."}, {"name": "~와", "level": "Beginner", "exp": "Conjunction particle meaning ''and.'' Connects two nouns as coordinate subjects/objects.", "ex_ko": "오랜 시간 동안 비와 바람이 바위를 깎아서 이런 모습이 되었어요.", "ex_en": "Over a long time, rain and wind carved the rock into this shape."}, {"name": "~를", "level": "Beginner", "exp": "Object particle after vowel-final nouns. Marks the direct object of the verb.", "ex_ko": "오랜 시간 동안 비와 바람이 바위를 깎아서 이런 모습이 되었어요.", "ex_en": "Over a long time, rain and wind carved the rock into this shape."}, {"name": "~아서", "level": "Beginner", "exp": "Connective suffix indicating sequential/causal relationship. 깎다 (to carve) + ~아서 + following clause with 되다 (to become).", "ex_ko": "오랜 시간 동안 비와 바람이 바위를 깎아서 이런 모습이 되었어요.", "ex_en": "Over a long time, rain and wind carved the rock into this shape."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense. 되다 (to become) → 되었어요 (became).", "ex_ko": "오랜 시간 동안 비와 바람이 바위를 깎아서 이런 모습이 되었어요.", "ex_en": "Over a long time, rain and wind carved the rock into this shape."}]}', updated_at = now() where article_id = 'mom3ww92kk9d' and md5(translation) = '0a2ea7f4010181447647296189cdea69';
update public.article_cache set translation = '{"texts": ["Parents in the United States are receiving criticism for throwing a baby shower for their 12-year-old daughter. A baby shower is a celebratory party held before a baby is born.", "The parents posted news of their daughter''s pregnancy and baby shower photos on social media. Many people were shocked after seeing this post.", "Netizens expressed concern, saying \"she is too young.\" There were many opinions asking, \"Is it right to celebrate pregnancy and childbirth when she is only 12 years old?\"", "Experts say that pregnancy at a young age can be dangerous to health. They also say it is not good for the child''s mental and physical development."], "sentences": [{"text": "미국에서 12살 딸의 베이비샤워를 열어준 부모가 비판을 받고 있어요.", "translation": "Parents in the United States who held a baby shower for their 12-year-old daughter are receiving criticism.", "vocab": [{"ko": "베이비샤워", "en": "baby shower"}, {"ko": "비판", "en": "criticism"}, {"ko": "받다", "en": "to receive"}], "analysis": [{"type": "grammar", "label": "~아/어 주다", "exp": "Doing something for someone. 열다 (to hold) → 열어 주다 (to hold for someone); 열어준 부모 = parents who held (it) for her.", "example_in_sentence": "열어준"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. Shows an ongoing action. Auxiliary 있다 attached to gerund ~고.", "example_in_sentence": "받고 있어요"}, {"type": "grammar", "label": "~에서", "exp": "Locative particle marking location where an action occurs.", "example_in_sentence": "미국에서"}]}, {"text": "베이비샤워는 아기가 태어나기 전에 하는 축하 파티예요.", "translation": "A baby shower is a celebration party held before a baby is born.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "축하", "en": "celebration"}, {"ko": "파티", "en": "party"}], "analysis": [{"type": "grammar", "label": "~기 전에", "exp": "Temporal expression meaning ''before'' an action. Nominalized verb form ~기 + noun 전 (before) + particle 에.", "example_in_sentence": "태어나기 전에"}, {"type": "grammar", "label": "~는 (present participle)", "exp": "Relative clause marker for present/general actions. Modifies the noun 파티.", "example_in_sentence": "하는 축하 파티"}, {"type": "grammar", "label": "예요", "exp": "Copula in polite present tense. Links the subject 베이비샤워 to the predicate nominative.", "example_in_sentence": "파티예요"}]}, {"text": "부모는 딸의 임신 소식과 베이비샤워 사진을 소셜미디어에 올렸어요.", "translation": "The parents posted news of their daughter''s pregnancy and baby shower photos on social media.", "vocab": [{"ko": "임신", "en": "pregnancy"}, {"ko": "소식", "en": "news"}, {"ko": "올리다", "en": "to post; to upload"}], "analysis": [{"type": "grammar", "label": "~과/와", "exp": "Conjunction particle linking two nouns. Connects 임신 소식 and 베이비샤워 사진.", "example_in_sentence": "소식과 베이비샤워 사진을"}, {"type": "grammar", "label": "~에", "exp": "Locative particle indicating destination or location of action.", "example_in_sentence": "소셜미디어에"}, {"type": "grammar", "label": "~었어요", "exp": "Past tense marker. Attached to 올리다 stem to form 올렸어요.", "example_in_sentence": "올렸어요"}]}, {"text": "많은 사람들이 이 게시물을 보고 놀랐어요.", "translation": "Many people saw this post and were surprised.", "vocab": [{"ko": "많다", "en": "many; a lot"}, {"ko": "게시물", "en": "post; article"}, {"ko": "놀라다", "en": "to be surprised"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending linking two actions in sequence. Shows 보고 (seeing) followed by 놀랐어요 (being surprised).", "example_in_sentence": "보고 놀랐어요"}, {"type": "grammar", "label": "~었어요", "exp": "Past tense. The stem 놀라다 + ~었어요 forms 놀랐어요.", "example_in_sentence": "놀랐어요"}]}, {"text": "네티즌들은 \"너무 어린 나이\"라며 걱정을 표했어요.", "translation": "Netizens expressed concern, saying she is \"too young.\"", "vocab": [{"ko": "네티즌", "en": "netizen; internet user"}, {"ko": "어리다", "en": "to be young"}, {"ko": "걱정", "en": "concern; worry"}], "analysis": [{"type": "grammar", "label": "~(이)라며", "exp": "Quotes what people say while they do the next action: ''saying (that) ...''. 나이 + 라며 = saying it is (too young) an age.", "example_in_sentence": "\"너무 어린 나이\"라며"}, {"type": "grammar", "label": "~을 표하다", "exp": "Expression: ''to express/show (emotion)''. Object particle ~을 marks the object 걱정.", "example_in_sentence": "걱정을 표했어요"}]}, {"text": "\"12살은 아직 아이인데 임신과 출산을 축하하는 것이 맞나요?\"라는 의견이 많았어요.", "translation": "Many people commented, \"A 12-year-old is still a child, so is it right to celebrate pregnancy and childbirth?\"", "vocab": [{"ko": "아직", "en": "still; yet"}, {"ko": "출산", "en": "childbirth"}, {"ko": "맞다", "en": "to be right; to be correct"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ데 / 인데", "exp": "Gives background before the main point. 아이이다 → 아이인데 (is a child, so...).", "example_in_sentence": "아이인데"}, {"type": "grammar", "label": "~는 것", "exp": "Nominalized verb form. 축하하다 + ~는 것 creates a noun phrase (the act of celebrating).", "example_in_sentence": "축하하는 것"}, {"type": "grammar", "label": "~라는", "exp": "Quotative + relative marker. Indicates reported opinion/statement that modifies 의견.", "example_in_sentence": "맞나요?\"라는 의견"}, {"type": "grammar", "label": "~었어요", "exp": "Past tense. Stem 많다 becomes 많았어요 in past tense.", "example_in_sentence": "많았어요"}]}, {"text": "전문가들은 어린 나이의 임신은 건강에 위험할 수 있다고 말해요.", "translation": "Experts say that pregnancy at a young age can be dangerous to health.", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "위험하다", "en": "to be dangerous; to be risky"}, {"ko": "건강", "en": "health"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Expresses possibility: ''can / may''. 위험하다 → 위험할 수 있다 (can be dangerous).", "example_in_sentence": "위험할 수 있다"}, {"type": "grammar", "label": "~다고 말하다", "exp": "Quotative + verb. ~다고 reports direct/indirect speech, 말하다 (say) is the main verb.", "example_in_sentence": "위험할 수 있다고 말해요"}, {"type": "grammar", "label": "~에", "exp": "Locative particle indicating target or destination of harm/risk.", "example_in_sentence": "건강에"}]}, {"text": "또한 아이의 정신적, 신체적 발달에도 좋지 않다고 해요.", "translation": "Also, it is said to be bad for the child''s mental and physical development.", "vocab": [{"ko": "또한", "en": "also; furthermore"}, {"ko": "정신적", "en": "mental; psychological"}, {"ko": "신체적", "en": "physical; bodily"}, {"ko": "발달", "en": "development"}], "analysis": [{"type": "grammar", "label": "~에도", "exp": "Particle ~에 (locative) + ~도 (also/too). Emphasizes ''also to development''.", "example_in_sentence": "발달에도"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation. 좋다 (good) → 좋지 않다 (not good).", "example_in_sentence": "좋지 않다"}, {"type": "grammar", "label": "~다고 하다", "exp": "Quotative + auxiliary verb 하다. Reports what is said; ~다고 해요 is polite indirect speech form.", "example_in_sentence": "좋지 않다고 해요"}]}], "version": "s6"}', vocab = '[{"ko": "베이비샤워", "en": "baby shower", "note": ""}, {"ko": "비판", "en": "criticism", "note": ""}, {"ko": "받다", "en": "to receive", "note": ""}, {"ko": "태어나다", "en": "to be born", "note": ""}, {"ko": "축하", "en": "celebration", "note": ""}, {"ko": "파티", "en": "party", "note": ""}, {"ko": "임신", "en": "pregnancy", "note": ""}, {"ko": "소식", "en": "news", "note": ""}, {"ko": "올리다", "en": "to post; to upload", "note": ""}, {"ko": "많다", "en": "many; a lot", "note": ""}, {"ko": "게시물", "en": "post; article", "note": ""}, {"ko": "놀라다", "en": "to be surprised", "note": ""}, {"ko": "네티즌", "en": "netizen; internet user", "note": ""}, {"ko": "어리다", "en": "to be young", "note": ""}, {"ko": "걱정", "en": "concern; worry", "note": ""}, {"ko": "아직", "en": "still; yet", "note": ""}, {"ko": "출산", "en": "childbirth", "note": ""}, {"ko": "맞다", "en": "to be right; to be correct", "note": ""}, {"ko": "전문가", "en": "expert", "note": ""}, {"ko": "위험하다", "en": "to be dangerous; to be risky", "note": ""}, {"ko": "건강", "en": "health", "note": ""}, {"ko": "또한", "en": "also; furthermore", "note": ""}, {"ko": "정신적", "en": "mental; psychological", "note": ""}, {"ko": "신체적", "en": "physical; bodily", "note": ""}, {"ko": "발달", "en": "development", "note": ""}, {"word": "비판을 받다", "reading": "bipan-eul bad-da", "meaning": "to receive criticism; to be criticized", "context": "베이비샤워를 열어준 부모가 비판을 받고 있어요"}, {"word": "소셜미디어", "reading": "sosyal midiao", "meaning": "social media", "context": "딸의 임신 소식과 베이비샤워 사진을 소셜미디어에 올렸어요"}]', grammar = '{"patterns": [{"name": "~아/어 주다", "level": "Beginner", "exp": "Doing something for someone. 열다 (to hold) → 열어 주다 (to hold for someone); 열어준 부모 = parents who held (it) for her.", "ex_ko": "미국에서 12살 딸의 베이비샤워를 열어준 부모가 비판을 받고 있어요.", "ex_en": "Parents in the United States who held a baby shower for their 12-year-old daughter are receiving criticism."}, {"name": "~고 있다", "level": "Beginner", "exp": "Progressive aspect marker. Shows an ongoing action. Auxiliary 있다 attached to gerund ~고.", "ex_ko": "미국에서 12살 딸의 베이비샤워를 열어준 부모가 비판을 받고 있어요.", "ex_en": "Parents in the United States who held a baby shower for their 12-year-old daughter are receiving criticism."}, {"name": "~에서", "level": "Beginner", "exp": "Locative particle indicating target or destination of harm/risk.", "ex_ko": "미국에서 12살 딸의 베이비샤워를 열어준 부모가 비판을 받고 있어요.", "ex_en": "Parents in the United States who held a baby shower for their 12-year-old daughter are receiving criticism."}, {"name": "~기 전에", "level": "Beginner", "exp": "Temporal expression meaning ''before'' an action. Nominalized verb form ~기 + noun 전 (before) + particle 에.", "ex_ko": "베이비샤워는 아기가 태어나기 전에 하는 축하 파티예요.", "ex_en": "A baby shower is a celebration party held before a baby is born."}, {"name": "~는 (present participle)", "level": "Beginner", "exp": "Relative clause marker for present/general actions. Modifies the noun 파티.", "ex_ko": "베이비샤워는 아기가 태어나기 전에 하는 축하 파티예요.", "ex_en": "A baby shower is a celebration party held before a baby is born."}, {"name": "예요", "level": "Beginner", "exp": "Copula in polite present tense. Links the subject 베이비샤워 to the predicate nominative.", "ex_ko": "베이비샤워는 아기가 태어나기 전에 하는 축하 파티예요.", "ex_en": "A baby shower is a celebration party held before a baby is born."}, {"name": "~과/와", "level": "Beginner", "exp": "Conjunction particle linking two nouns. Connects 임신 소식 and 베이비샤워 사진.", "ex_ko": "부모는 딸의 임신 소식과 베이비샤워 사진을 소셜미디어에 올렸어요.", "ex_en": "The parents posted news of their daughter''s pregnancy and baby shower photos on social media."}, {"name": "~었어요", "level": "Beginner", "exp": "Past tense marker. Attached to 올리다 stem to form 올렸어요.", "ex_ko": "부모는 딸의 임신 소식과 베이비샤워 사진을 소셜미디어에 올렸어요.", "ex_en": "The parents posted news of their daughter''s pregnancy and baby shower photos on social media."}, {"name": "~고", "level": "Beginner", "exp": "Connective ending linking two actions in sequence. Shows 보고 (seeing) followed by 놀랐어요 (being surprised).", "ex_ko": "많은 사람들이 이 게시물을 보고 놀랐어요.", "ex_en": "Many people saw this post and were surprised."}, {"name": "~(이)라며", "level": "Beginner", "exp": "Quotes what people say while they do the next action: ''saying (that) ...''. 나이 + 라며 = saying it is (too young) an age.", "ex_ko": "네티즌들은 \"너무 어린 나이\"라며 걱정을 표했어요.", "ex_en": "Netizens expressed concern, saying she is \"too young.\""}, {"name": "~을 표하다", "level": "Beginner", "exp": "Expression: ''to express/show (emotion)''. Object particle ~을 marks the object 걱정.", "ex_ko": "네티즌들은 \"너무 어린 나이\"라며 걱정을 표했어요.", "ex_en": "Netizens expressed concern, saying she is \"too young.\""}, {"name": "~(으)ㄴ데 / 인데", "level": "Beginner", "exp": "Gives background before the main point. 아이이다 → 아이인데 (is a child, so...).", "ex_ko": "\"12살은 아직 아이인데 임신과 출산을 축하하는 것이 맞나요?\"라는 의견이 많았어요.", "ex_en": "Many people commented, \"A 12-year-old is still a child, so is it right to celebrate pregnancy and childbirth?\""}, {"name": "~는 것", "level": "Beginner", "exp": "Nominalized verb form. 축하하다 + ~는 것 creates a noun phrase (the act of celebrating).", "ex_ko": "\"12살은 아직 아이인데 임신과 출산을 축하하는 것이 맞나요?\"라는 의견이 많았어요.", "ex_en": "Many people commented, \"A 12-year-old is still a child, so is it right to celebrate pregnancy and childbirth?\""}, {"name": "~라는", "level": "Beginner", "exp": "Quotative + relative marker. Indicates reported opinion/statement that modifies 의견.", "ex_ko": "\"12살은 아직 아이인데 임신과 출산을 축하하는 것이 맞나요?\"라는 의견이 많았어요.", "ex_en": "Many people commented, \"A 12-year-old is still a child, so is it right to celebrate pregnancy and childbirth?\""}, {"name": "~(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses possibility: ''can / may''. 위험하다 → 위험할 수 있다 (can be dangerous).", "ex_ko": "전문가들은 어린 나이의 임신은 건강에 위험할 수 있다고 말해요.", "ex_en": "Experts say that pregnancy at a young age can be dangerous to health."}]}', updated_at = now() where article_id = 'mom3xhyo36m8' and md5(translation) = 'f8c2b0aa3b322fc4728617f9fac401a5';
update public.article_cache set translation = '{"texts": ["Something special happens in the UK when an organ donor passes away. The National Health Service (NHS) sends a letter to the donor''s family.", "This letter contains a detailed explanation of how the donated organs were used. You can also learn which patients benefited from the donation. Through this letter, families can confirm that their loved one''s organ donation saved other lives.", "Interest in organ donation is also growing in Korea. However, unlike the UK, there is not yet a system in place to send detailed letters like this. Experts say that such a system helps develop organ donation culture.", "Organ donation is a precious act where one person''s death can save multiple lives. We hope that the UK''s warm system like this will spread to more countries."], "sentences": [{"text": "영국에서는 장기 기증자가 사망하면 특별한 일이 일어납니다.", "translation": "In the UK, when an organ donor passes away, something special happens.", "vocab": [{"ko": "장기", "en": "organ"}, {"ko": "기증자", "en": "donor"}, {"ko": "사망하다", "en": "to pass away; to die"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~면", "exp": "Conditional suffix indicating ''when/if''. Connects condition to result: 사망하다 (base) → 사망하면 (if/when dies).", "example_in_sentence": "사망하면"}]}, {"text": "국가 의료 서비스(NHS)에서 기증자 가족에게 편지를 보냅니다.", "translation": "The National Health Service (NHS) sends a letter to the donor''s family.", "vocab": [{"ko": "국가", "en": "nation; state"}, {"ko": "의료", "en": "medical; healthcare"}, {"ko": "서비스", "en": "service"}, {"ko": "편지", "en": "letter"}], "analysis": [{"type": "grammar", "label": "~에서 (organization as subject)", "exp": "After an organization, 에서 marks it as the one doing the action. NHS에서 보냅니다 = the NHS sends.", "example_in_sentence": "서비스(NHS)에서"}]}, {"text": "이 편지에는 기증된 장기가 어떻게 사용되었는지가 자세히 설명되어 있습니다.", "translation": "This letter contains a detailed explanation of how the donated organs were used.", "vocab": [{"ko": "기증되다", "en": "to be donated"}, {"ko": "사용되다", "en": "to be used"}, {"ko": "자세히", "en": "in detail"}, {"ko": "설명되다", "en": "to be explained"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ", "exp": "Past participle modifying noun. 기증되다 → 기증된 (donated organs).", "example_in_sentence": "기증된 장기"}, {"type": "grammar", "label": "~았/었는지", "exp": "Nominalizing suffix expressing ''how/whether'' an action occurred. 사용되다 → 사용되었는지 (how [it] was used).", "example_in_sentence": "사용되었는지"}, {"type": "grammar", "label": "~어 있다", "exp": "Resultative state auxiliary. 설명되어 있습니다 = explanation is [currently] in place/provided.", "example_in_sentence": "설명되어 있습니다"}]}, {"text": "어떤 환자들이 도움을 받았는지도 알 수 있어요.", "translation": "You can also find out which patients received help.", "vocab": [{"ko": "환자", "en": "patient"}, {"ko": "도움을 받다", "en": "to receive help"}, {"ko": "알다", "en": "to know; to find out"}], "analysis": [{"type": "expression", "label": "도움을 받다", "exp": "Verb phrase meaning ''to receive aid/benefit''. Object-taking expression with 을/를.", "example_in_sentence": "도움을 받았는지"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Modal expressing possibility/ability: 알다 → 알 수 있어요 (can know).", "example_in_sentence": "알 수 있어요"}]}, {"text": "가족들은 이 편지를 통해 사랑하는 사람의 장기 기증이 다른 생명을 구했다는 것을 확인할 수 있습니다.", "translation": "Through this letter, families can confirm that their loved one''s organ donation saved other lives.", "vocab": [{"ko": "사랑하다", "en": "to love"}, {"ko": "구하다", "en": "to save; to rescue"}, {"ko": "확인하다", "en": "to confirm; to verify"}], "analysis": [{"type": "grammar", "label": "~는", "exp": "Present participle modifying noun: 사랑하는 사람 (loved one/the person who is loved).", "example_in_sentence": "사랑하는 사람"}, {"type": "grammar", "label": "~았다는 것", "exp": "Nominalization of past fact: 구했다 (saved) + ~는 것 (fact/thing that) = ''the fact that [it] saved''.", "example_in_sentence": "구했다는 것"}, {"type": "grammar", "label": "~을/를 통해", "exp": "Means/medium particle: 편지를 통해 (through/via the letter).", "example_in_sentence": "통해"}]}, {"text": "한국에서도 장기 기증에 대한 관심이 높아지고 있습니다.", "translation": "Interest in organ donation is also rising in South Korea.", "vocab": [{"ko": "관심", "en": "interest; concern"}, {"ko": "높아지다", "en": "to rise; to increase; to grow"}], "analysis": [{"type": "grammar", "label": "~에 대한", "exp": "Relational particle marking target of interest/concern: 기증에 대한 관심 (interest regarding/toward donation).", "example_in_sentence": "대한"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect: 높아지다 → 높아지고 있습니다 (is rising/in the process of rising).", "example_in_sentence": "높아지고 있습니다"}]}, {"text": "하지만 영국처럼 자세한 편지를 보내는 제도는 아직 없어요.", "translation": "However, there is still no system that sends detailed letters like in the UK.", "vocab": [{"ko": "제도", "en": "system; institution"}, {"ko": "아직", "en": "still; yet"}], "analysis": [{"type": "grammar", "label": "~처럼", "exp": "Comparison particle: 영국처럼 (like/as in the UK).", "example_in_sentence": "처럼"}, {"type": "grammar", "label": "~는", "exp": "Present participle in relative clause modifying noun: 보내는 제도 (system that sends).", "example_in_sentence": "보내는"}]}, {"text": "전문가들은 이런 제도가 장기 기증 문화를 발전시키는 데 도움이 된다고 말합니다.", "translation": "Experts say that such systems help develop organ donation culture.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "발전시키다", "en": "to develop; to advance"}, {"ko": "문화", "en": "culture"}], "analysis": [{"type": "expression", "label": "도움이 되다", "exp": "Verb phrase meaning ''to be helpful/beneficial''. Nominalized: ~는 데 도움이 된다.", "example_in_sentence": "도움이 된다"}, {"type": "grammar", "label": "~는 데", "exp": "Nominalizing suffix + locative particle marking where/how help is given: 발전시키는 데 도움이 된다 (is helpful in developing).", "example_in_sentence": "발전시키는 데"}, {"type": "grammar", "label": "~다고 말하다", "exp": "Quotation pattern: 된다 (becomes) → ~다고 말합니다 (say that [it] becomes/is).", "example_in_sentence": "된다고 말합니다"}]}, {"text": "장기 기증은 한 사람의 죽음이 여러 생명을 살릴 수 있는 소중한 일입니다.", "translation": "Organ donation is a precious act through which one person''s death can save many lives.", "vocab": [{"ko": "죽음", "en": "death"}, {"ko": "살리다", "en": "to save; to keep alive"}, {"ko": "소중하다", "en": "to be precious; to be valuable"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있는", "exp": "Potential participle modifying noun: 살릴 수 있는 일 (an act that can save).", "example_in_sentence": "살릴 수 있는"}]}, {"text": "영국의 이런 따뜻한 제도가 더 많은 나라에 퍼지기를 기대합니다.", "translation": "We hope this warm system from the UK spreads to more countries.", "vocab": [{"ko": "따뜻하다", "en": "to be warm; to be kind"}, {"ko": "퍼지다", "en": "to spread; to spread out"}, {"ko": "기대하다", "en": "to hope; to expect"}], "analysis": [{"type": "grammar", "label": "~기를 기대하다", "exp": "Nominalization + hope/wish expression: 퍼지다 → 퍼지기를 기대합니다 (hope that [it] spreads).", "example_in_sentence": "퍼지기를 기대합니다"}]}], "version": "s6"}', vocab = '[{"ko": "장기", "en": "organ", "note": ""}, {"ko": "기증자", "en": "donor", "note": ""}, {"ko": "사망하다", "en": "to pass away; to die", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}, {"ko": "국가", "en": "nation; state", "note": ""}, {"ko": "의료", "en": "medical; healthcare", "note": ""}, {"ko": "서비스", "en": "service", "note": ""}, {"ko": "편지", "en": "letter", "note": ""}, {"ko": "기증되다", "en": "to be donated", "note": ""}, {"ko": "사용되다", "en": "to be used", "note": ""}, {"ko": "자세히", "en": "in detail", "note": ""}, {"ko": "설명되다", "en": "to be explained", "note": ""}, {"ko": "환자", "en": "patient", "note": ""}, {"ko": "도움을 받다", "en": "to receive help", "note": ""}, {"ko": "알다", "en": "to know; to find out", "note": ""}, {"ko": "사랑하다", "en": "to love", "note": ""}, {"ko": "구하다", "en": "to save; to rescue", "note": ""}, {"ko": "확인하다", "en": "to confirm; to verify", "note": ""}, {"ko": "관심", "en": "interest; concern", "note": ""}, {"ko": "높아지다", "en": "to rise; to increase; to grow", "note": ""}, {"ko": "제도", "en": "system; institution", "note": ""}, {"ko": "아직", "en": "still; yet", "note": ""}, {"ko": "전문가", "en": "expert; specialist", "note": ""}, {"ko": "발전시키다", "en": "to develop; to advance", "note": ""}, {"ko": "문화", "en": "culture", "note": ""}, {"ko": "죽음", "en": "death", "note": ""}, {"ko": "살리다", "en": "to save; to keep alive", "note": ""}, {"ko": "소중하다", "en": "to be precious; to be valuable", "note": ""}, {"ko": "따뜻하다", "en": "to be warm; to be kind", "note": ""}, {"ko": "퍼지다", "en": "to spread; to spread out", "note": ""}, {"ko": "기대하다", "en": "to hope; to expect", "note": ""}]', grammar = '{"patterns": [{"name": "~면", "level": "Intermediate", "exp": "Conditional suffix indicating ''when/if''. Connects condition to result: 사망하다 (base) → 사망하면 (if/when dies).", "ex_ko": "영국에서는 장기 기증자가 사망하면 특별한 일이 일어납니다.", "ex_en": "In the UK, when an organ donor passes away, something special happens."}, {"name": "~에서 (organization as subject)", "level": "Intermediate", "exp": "After an organization, 에서 marks it as the one doing the action. NHS에서 보냅니다 = the NHS sends.", "ex_ko": "국가 의료 서비스(NHS)에서 기증자 가족에게 편지를 보냅니다.", "ex_en": "The National Health Service (NHS) sends a letter to the donor''s family."}, {"name": "~(으)ㄴ", "level": "Intermediate", "exp": "Past participle modifying noun. 기증되다 → 기증된 (donated organs).", "ex_ko": "이 편지에는 기증된 장기가 어떻게 사용되었는지가 자세히 설명되어 있습니다.", "ex_en": "This letter contains a detailed explanation of how the donated organs were used."}, {"name": "~았/었는지", "level": "Intermediate", "exp": "Nominalizing suffix expressing ''how/whether'' an action occurred. 사용되다 → 사용되었는지 (how [it] was used).", "ex_ko": "이 편지에는 기증된 장기가 어떻게 사용되었는지가 자세히 설명되어 있습니다.", "ex_en": "This letter contains a detailed explanation of how the donated organs were used."}, {"name": "~어 있다", "level": "Intermediate", "exp": "Resultative state auxiliary. 설명되어 있습니다 = explanation is [currently] in place/provided.", "ex_ko": "이 편지에는 기증된 장기가 어떻게 사용되었는지가 자세히 설명되어 있습니다.", "ex_en": "This letter contains a detailed explanation of how the donated organs were used."}, {"name": "~ㄹ 수 있다", "level": "Intermediate", "exp": "Modal expressing possibility/ability: 알다 → 알 수 있어요 (can know).", "ex_ko": "어떤 환자들이 도움을 받았는지도 알 수 있어요.", "ex_en": "You can also find out which patients received help."}, {"name": "~는", "level": "Intermediate", "exp": "Present participle in relative clause modifying noun: 보내는 제도 (system that sends).", "ex_ko": "가족들은 이 편지를 통해 사랑하는 사람의 장기 기증이 다른 생명을 구했다는 것을 확인할 수 있습니다.", "ex_en": "Through this letter, families can confirm that their loved one''s organ donation saved other lives."}, {"name": "~았다는 것", "level": "Intermediate", "exp": "Nominalization of past fact: 구했다 (saved) + ~는 것 (fact/thing that) = ''the fact that [it] saved''.", "ex_ko": "가족들은 이 편지를 통해 사랑하는 사람의 장기 기증이 다른 생명을 구했다는 것을 확인할 수 있습니다.", "ex_en": "Through this letter, families can confirm that their loved one''s organ donation saved other lives."}, {"name": "~을/를 통해", "level": "Intermediate", "exp": "Means/medium particle: 편지를 통해 (through/via the letter).", "ex_ko": "가족들은 이 편지를 통해 사랑하는 사람의 장기 기증이 다른 생명을 구했다는 것을 확인할 수 있습니다.", "ex_en": "Through this letter, families can confirm that their loved one''s organ donation saved other lives."}, {"name": "~에 대한", "level": "Intermediate", "exp": "Relational particle marking target of interest/concern: 기증에 대한 관심 (interest regarding/toward donation).", "ex_ko": "한국에서도 장기 기증에 대한 관심이 높아지고 있습니다.", "ex_en": "Interest in organ donation is also rising in South Korea."}, {"name": "~고 있다", "level": "Intermediate", "exp": "Progressive aspect: 높아지다 → 높아지고 있습니다 (is rising/in the process of rising).", "ex_ko": "한국에서도 장기 기증에 대한 관심이 높아지고 있습니다.", "ex_en": "Interest in organ donation is also rising in South Korea."}, {"name": "~처럼", "level": "Intermediate", "exp": "Comparison particle: 영국처럼 (like/as in the UK).", "ex_ko": "하지만 영국처럼 자세한 편지를 보내는 제도는 아직 없어요.", "ex_en": "However, there is still no system that sends detailed letters like in the UK."}, {"name": "~는 데", "level": "Intermediate", "exp": "Nominalizing suffix + locative particle marking where/how help is given: 발전시키는 데 도움이 된다 (is helpful in developing).", "ex_ko": "전문가들은 이런 제도가 장기 기증 문화를 발전시키는 데 도움이 된다고 말합니다.", "ex_en": "Experts say that such systems help develop organ donation culture."}, {"name": "~다고 말하다", "level": "Intermediate", "exp": "Quotation pattern: 된다 (becomes) → ~다고 말합니다 (say that [it] becomes/is).", "ex_ko": "전문가들은 이런 제도가 장기 기증 문화를 발전시키는 데 도움이 된다고 말합니다.", "ex_en": "Experts say that such systems help develop organ donation culture."}, {"name": "~ㄹ 수 있는", "level": "Intermediate", "exp": "Potential participle modifying noun: 살릴 수 있는 일 (an act that can save).", "ex_ko": "장기 기증은 한 사람의 죽음이 여러 생명을 살릴 수 있는 소중한 일입니다.", "ex_en": "Organ donation is a precious act through which one person''s death can save many lives."}]}', updated_at = now() where article_id = 'mom3y5n066sn' and md5(translation) = '2c84ca58c083528414ac102cd512c16e';
update public.article_cache set translation = '{"sentences": [{"text": "한국 정부가 중동 지역의 긴장 상황에 대응하기 위해 특별사절단을 파견하기로 했습니다.", "idx": 0, "translation": "The Korean government has decided to dispatch a special envoy to respond to the tense situation in the Middle East region.", "vocab": [{"ko": "긴장", "en": "tension; strain", "note": "noun"}, {"ko": "대응하다", "en": "to respond; to cope", "note": "action taken in reaction"}, {"ko": "특별사절단", "en": "special envoy delegation", "note": "official diplomatic mission"}, {"ko": "파견하다", "en": "to dispatch; to send", "note": "official deployment"}], "grammar": [{"pattern": "~기 위해", "exp": "In order to do X; for the purpose of doing X.", "example_in_sentence": "긴장 상황에 대응하기 위해"}], "analysis": []}, {"text": "쿠웨이트, 이라크, 바레인 등 주요 국가들을 방문할 예정입니다.", "idx": 1, "translation": "They plan to visit major countries including Kuwait, Iraq, and Bahrain.", "vocab": [{"ko": "쿠웨이트", "en": "Kuwait", "note": "country name"}, {"ko": "주요", "en": "major; main; key", "note": "adjective"}, {"ko": "방문하다", "en": "to visit", "note": "formal visitation"}], "grammar": [{"pattern": "~등", "exp": "and so on; including; such as (lists examples).", "example_in_sentence": "쿠웨이트, 이라크, 바레인 등"}], "analysis": []}, {"text": "특사단은 현지 상황을 직접 파악하고 한국 교민들의 안전을 점검할 계획입니다.", "idx": 2, "translation": "The envoy delegation plans to directly grasp the local situation and check the safety of Korean residents.", "vocab": [{"ko": "파악하다", "en": "to grasp; to understand; to ascertain", "note": "to gain clear knowledge of"}, {"ko": "교민", "en": "Korean residents abroad; diaspora", "note": "nationals living overseas"}, {"ko": "점검하다", "en": "to check; to inspect; to examine", "note": "verification/inspection"}], "grammar": [{"pattern": "~고", "exp": "and; in addition to (connects two actions/states in sequence).", "example_in_sentence": "파악하고 한국 교민들의 안전을 점검할"}], "analysis": []}, {"text": "또한 각국 정부와 외교적 협력 방안을 논의할 것으로 알려졌습니다.", "idx": 3, "translation": "Additionally, it is reported that they will discuss diplomatic cooperation measures with each country''s government.", "vocab": [{"ko": "각국", "en": "each country; various countries", "note": "multiple nations"}, {"ko": "외교적", "en": "diplomatic", "note": "adjective form"}, {"ko": "협력 방안", "en": "cooperation measures; ways to collaborate", "note": "methods of joint work"}], "grammar": [{"pattern": "~는 것으로 알려지다", "exp": "It is known/reported that X; it is said that X.", "example_in_sentence": "논의할 것으로 알려졌습니다"}], "analysis": []}, {"text": "중동 지역은 최근 정치적 불안정이 지속되고 있는 상황입니다.", "idx": 4, "translation": "The Middle East region is in a situation where political instability has been continuing recently.", "vocab": [{"ko": "정치적", "en": "political", "note": "adjective"}, {"ko": "불안정", "en": "instability; insecurity", "note": "noun"}, {"ko": "지속되다", "en": "to persist; to continue; to be sustained", "note": "ongoing state"}], "grammar": [{"pattern": "~는 상황이다", "exp": "It is a situation/state where X is happening (descriptive noun phrase modifier).", "example_in_sentence": "불안정이 지속되고 있는 상황입니다"}], "analysis": []}, {"text": "한국은 이 지역과 경제적으로 밀접한 관계를 유지하고 있어 신중한 대응이 필요한 상태입니다.", "idx": 5, "translation": "Korea maintains economically close relations with this region, so a careful response is necessary.", "vocab": [{"ko": "경제적", "en": "economic; economically", "note": "adjective/adverb form"}, {"ko": "밀접하다", "en": "to be close; to be closely related", "note": "closely connected"}, {"ko": "관계", "en": "relationship; relation", "note": "connection between entities"}, {"ko": "신중하다", "en": "to be careful; to be cautious; prudent", "note": "adjective"}], "grammar": [{"pattern": "~어/아 있다", "exp": "to be in a state of X; to have been doing X (resultant state).", "example_in_sentence": "유지하고 있어"}], "analysis": []}, {"text": "외교부는 특사 파견을 통해 한국의 입장을 명확히 전달하고 지역 안정에 기여하겠다고 밝혔습니다.", "idx": 6, "translation": "The Ministry of Foreign Affairs said that by sending the special envoy, it will clearly convey Korea''s position and contribute to regional stability.", "vocab": [{"ko": "외교부", "en": "Ministry of Foreign Affairs", "note": "government department"}, {"ko": "입장", "en": "position; stance; standpoint", "note": "official viewpoint"}, {"ko": "명확히", "en": "clearly; distinctly; explicitly", "note": "adverb"}], "grammar": [{"pattern": "~을/를 통해", "exp": "through; by means of; via (indicating method or medium).", "example_in_sentence": "특사 파견을 통해"}], "analysis": []}, {"text": "특사단의 구체적인 일정과 구성원은 조만간 공개될 예정입니다.", "idx": 7, "translation": "The delegation''s specific schedule and members are expected to be announced soon.", "vocab": [{"ko": "구체적", "en": "concrete; specific; detailed", "note": "adjective"}, {"ko": "일정", "en": "schedule; itinerary; plan", "note": "timetable of events"}, {"ko": "구성원", "en": "member", "note": "people who make up a group"}], "grammar": [{"pattern": "~을/를 예정이다", "exp": "to be scheduled to do X; to plan to do X (future arrangement).", "example_in_sentence": "공개될 예정입니다"}], "analysis": []}], "version": "p2"}', vocab = '[{"ko": "긴장", "en": "tension; strain", "note": "noun"}, {"ko": "대응하다", "en": "to respond; to cope", "note": "action taken in reaction"}, {"ko": "특별사절단", "en": "special envoy delegation", "note": "official diplomatic mission"}, {"ko": "파견하다", "en": "to dispatch; to send", "note": "official deployment"}, {"ko": "쿠웨이트", "en": "Kuwait", "note": "country name"}, {"ko": "주요", "en": "major; main; key", "note": "adjective"}, {"ko": "방문하다", "en": "to visit", "note": "formal visitation"}, {"ko": "파악하다", "en": "to grasp; to understand; to ascertain", "note": "to gain clear knowledge of"}, {"ko": "교민", "en": "Korean residents abroad; diaspora", "note": "nationals living overseas"}, {"ko": "점검하다", "en": "to check; to inspect; to examine", "note": "verification/inspection"}, {"ko": "각국", "en": "each country; various countries", "note": "multiple nations"}, {"ko": "외교적", "en": "diplomatic", "note": "adjective form"}, {"ko": "협력 방안", "en": "cooperation measures; ways to collaborate", "note": "methods of joint work"}, {"ko": "정치적", "en": "political", "note": "adjective"}, {"ko": "불안정", "en": "instability; insecurity", "note": "noun"}, {"ko": "지속되다", "en": "to persist; to continue; to be sustained", "note": "ongoing state"}, {"ko": "경제적", "en": "economic; economically", "note": "adjective/adverb form"}, {"ko": "밀접하다", "en": "to be close; to be closely related", "note": "closely connected"}, {"ko": "관계", "en": "relationship; relation", "note": "connection between entities"}, {"ko": "신중하다", "en": "to be careful; to be cautious; prudent", "note": "adjective"}, {"ko": "외교부", "en": "Ministry of Foreign Affairs", "note": "government department"}, {"ko": "입장", "en": "position; stance; standpoint", "note": "official viewpoint"}, {"ko": "명확히", "en": "clearly; distinctly; explicitly", "note": "adverb"}, {"ko": "구체적", "en": "concrete; specific; detailed", "note": "adjective"}, {"ko": "일정", "en": "schedule; itinerary; plan", "note": "timetable of events"}, {"ko": "구성원", "en": "member", "note": "people who make up a group"}, {"word": "기여하다", "reading": "gi-yeo-ha-da", "meaning": "to contribute (to); to make a contribution", "context": "지역 안정에 기여하겠다고 밝혔습니다"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mom3zfzpd6rg' and md5(translation) = '0d1ecbb901d5114c450f8bf80a201085';
update public.article_cache set translation = '{"texts": ["In China, food delivery apps are undergoing major changes. A system where robots handle orders instead of people is being introduced.", "These robots find food items ordered by customers in warehouses and package them. They can process work faster and more accurately than people.", "Online shopping and delivery services are also popular in Korea. It appears that this change in China will have an impact on Korea''s delivery market as well.", "Experts say that in the future, more countries will increase delivery systems using robots. It is worth paying attention to how technological advancement will change our lives."], "sentences": [{"text": "중국에서 식료품 배달 앱(app)이 큰 변화를 맞고 있어요.", "translation": "Delivery apps for groceries in China are undergoing major changes.", "vocab": [{"ko": "식료품", "en": "groceries; food products"}, {"ko": "배달", "en": "delivery"}, {"ko": "변화", "en": "change; transformation"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker indicating ongoing action. Combines auxiliary verb 있다 with ~고 to show continuous state.", "example_in_sentence": "맞고 있어요"}]}, {"text": "사람 대신 로봇이 주문을 처리하는 시스템이 도입되고 있습니다.", "translation": "A system in which robots process orders instead of people is being introduced.", "vocab": [{"ko": "대신", "en": "instead of; in place of"}, {"ko": "로봇", "en": "robot"}, {"ko": "주문", "en": "order"}, {"ko": "처리하다", "en": "to process; to handle"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Describes a noun with a present action. 처리하다 → 처리하는 시스템 (a system that processes).", "example_in_sentence": "주문을 처리하는 시스템"}, {"type": "grammar", "label": "~고 있습니다", "exp": "Formal progressive aspect. Shows ongoing action with formal politeness level.", "example_in_sentence": "도입되고 있습니다"}]}, {"text": "이 로봇들은 창고에서 고객이 주문한 식료품을 찾아서 포장해요.", "translation": "These robots find groceries ordered by customers in the warehouse and package them.", "vocab": [{"ko": "창고", "en": "warehouse; storage"}, {"ko": "고객", "en": "customer; client"}, {"ko": "포장하다", "en": "to pack; to package"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 주문하다 → 주문한 식료품 (groceries that were ordered).", "example_in_sentence": "주문한 식료품"}, {"type": "grammar", "label": "~아서/어서", "exp": "Connective ending showing sequential action. Action 1 (찾아서) → Action 2 (포장). Derived from 찾다 → 찾아서.", "example_in_sentence": "찾아서 포장"}]}, {"text": "사람보다 빠르고 정확하게 일을 처리할 수 있다고 합니다.", "translation": "It is said that they can process work faster and more accurately than people.", "vocab": [{"ko": "빠르다", "en": "to be fast; to be quick"}, {"ko": "정확하다", "en": "to be accurate; to be precise"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Joins two descriptions with ''and''. 빠르다 → 빠르고 정확하게 (quickly and accurately).", "example_in_sentence": "빠르고 정확하게"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability/possibility modifier. 처리하다 → 처리할 수 있다 (can process). Expresses capability.", "example_in_sentence": "처리할 수 있다"}, {"type": "expression", "label": "~다고 합니다", "exp": "Reportive ending indicating indirect speech or secondhand information. Conveys hearsay or general claim.", "example_in_sentence": "처리할 수 있다고 합니다"}]}, {"text": "한국에서도 온라인 쇼핑과 배달 서비스가 인기가 많아요.", "translation": "Online shopping and delivery services are also very popular in Korea.", "vocab": [{"ko": "온라인", "en": "online"}, {"ko": "쇼핑", "en": "shopping"}, {"ko": "인기", "en": "popularity; fame"}], "analysis": [{"type": "expression", "label": "인기가 많다", "exp": "Colloquial expression meaning ''to be very popular.'' Literally ''popularity is abundant.'' Alternative: 인기가 높다.", "example_in_sentence": "인기가 많아요"}]}, {"text": "중국의 이런 변화가 한국 배달 시장에도 영향을 줄 것으로 보입니다.", "translation": "It appears that such changes in China will also influence Korea''s delivery market.", "vocab": [{"ko": "영향", "en": "influence; impact"}, {"ko": "시장", "en": "market"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것으로 보이다", "exp": "A formal way to say something is expected: ''it looks like ... will''. 주다 → 줄 것으로 보입니다 (is expected to have).", "example_in_sentence": "줄 것으로 보입니다"}, {"type": "expression", "label": "영향을 주다", "exp": "Verb phrase meaning ''to exert influence; to have an impact.'' Fixed collocation with direct object marker 을/를.", "example_in_sentence": "영향을 줄"}]}, {"text": "전문가들은 앞으로 더 많은 나라에서 로봇을 활용한 배달 시스템이 늘어날 것이라고 말해요.", "translation": "Experts say that delivery systems utilizing robots will increase in more countries in the future.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "앞으로", "en": "in the future; from now on"}, {"ko": "활용하다", "en": "to use; to make use of"}, {"ko": "늘어나다", "en": "to increase; to grow"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (verb modifier)", "exp": "Describes a noun with an action. 활용하다 → 로봇을 활용한 배달 시스템 (delivery systems that use robots).", "example_in_sentence": "활용한 배달 시스템"}, {"type": "grammar", "label": "~(으)ㄹ 것이라고 말하다", "exp": "Reports someone''s prediction: ''say that ... will''. 늘어나다 → 늘어날 것이라고 말해요 (say it will increase).", "example_in_sentence": "늘어날 것이라고 말해요"}]}, {"text": "기술 발전이 우리 생활을 어떻게 바꿀지 주목됩니다.", "translation": "People are watching closely to see how technological progress will change our lives.", "vocab": [{"ko": "기술", "en": "technology; technique"}, {"ko": "발전", "en": "development; progress"}, {"ko": "주목되다", "en": "to draw attention; to be watched closely"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ지", "exp": "Forms an indirect question about the future: ''how / whether ... will''. 바꾸다 → 바꿀지 (how it will change).", "example_in_sentence": "바꿀지"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "되다 makes many 하다 verbs passive. 주목하다 (to pay attention to) → 주목되다 (to draw attention).", "example_in_sentence": "주목됩니다"}]}], "version": "s6"}', vocab = '[{"ko": "식료품", "en": "groceries; food products", "note": ""}, {"ko": "배달", "en": "delivery", "note": ""}, {"ko": "변화", "en": "change; transformation", "note": ""}, {"ko": "대신", "en": "instead of; in place of", "note": ""}, {"ko": "로봇", "en": "robot", "note": ""}, {"ko": "주문", "en": "order", "note": ""}, {"ko": "처리하다", "en": "to process; to handle", "note": ""}, {"ko": "창고", "en": "warehouse; storage", "note": ""}, {"ko": "고객", "en": "customer; client", "note": ""}, {"ko": "포장하다", "en": "to pack; to package", "note": ""}, {"ko": "빠르다", "en": "to be fast; to be quick", "note": ""}, {"ko": "정확하다", "en": "to be accurate; to be precise", "note": ""}, {"ko": "온라인", "en": "online", "note": ""}, {"ko": "쇼핑", "en": "shopping", "note": ""}, {"ko": "인기", "en": "popularity; fame", "note": ""}, {"ko": "영향", "en": "influence; impact", "note": ""}, {"ko": "시장", "en": "market", "note": ""}, {"ko": "전문가", "en": "expert; specialist", "note": ""}, {"ko": "앞으로", "en": "in the future; from now on", "note": ""}, {"ko": "활용하다", "en": "to use; to make use of", "note": ""}, {"ko": "늘어나다", "en": "to increase; to grow", "note": ""}, {"ko": "기술", "en": "technology; technique", "note": ""}, {"ko": "발전", "en": "development; progress", "note": ""}, {"ko": "주목되다", "en": "to draw attention; to be watched closely", "note": ""}, {"word": "도입되다", "reading": "doinip-doeda", "meaning": "to be introduced / to be adopted", "context": "로봇이 주문을 처리하는 시스템이 도입되고"}]', grammar = '{"patterns": [{"name": "~고 있어요", "level": "Intermediate", "exp": "Progressive aspect marker indicating ongoing action. Combines auxiliary verb 있다 with ~고 to show continuous state.", "ex_ko": "중국에서 식료품 배달 앱(app)이 큰 변화를 맞고 있어요.", "ex_en": "Delivery apps for groceries in China are undergoing major changes."}, {"name": "~는 (verb modifier)", "level": "Intermediate", "exp": "Describes a noun with a present action. 처리하다 → 처리하는 시스템 (a system that processes).", "ex_ko": "사람 대신 로봇이 주문을 처리하는 시스템이 도입되고 있습니다.", "ex_en": "A system in which robots process orders instead of people is being introduced."}, {"name": "~고 있습니