update public.article_cache set translation = '{"texts": ["What does the scenery outside the window look like when a high-speed train travels at 350 kilometers per hour? There''s a video that became a hot topic on the internet.", "The video shows footage taken from inside a high-speed train. Trees and buildings outside the window pass by very quickly. It''s like watching a movie on fast-forward.", "South Korea''s KTX also travels at a maximum speed of 300 kilometers per hour. You can get from Seoul to Busan in two and a half hours.", "Many people were amazed after watching this video. There were many comments saying \"It''s really fast\" and \"How amazing.\" It''s a video that lets you really feel the high speed of a high-speed train."], "sentences": [{"text": "고속열차가 시속 350킬로미터로 달릴 때 창밖 풍경이 어떻게 보일까요?", "translation": "When a high-speed train runs at 350 kilometers per hour, how does the scenery outside the window look?", "vocab": [{"ko": "고속열차", "en": "high-speed train"}, {"ko": "시속", "en": "speed per hour"}, {"ko": "창밖", "en": "outside the window"}, {"ko": "풍경", "en": "scenery"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "Means ''when''. 달리다 (to run) → 달릴 때 (when it runs).", "example_in_sentence": "달릴 때"}, {"type": "grammar", "label": "~(으)ㄹ까요?", "exp": "Asks a question while wondering. 보이다 (to look) → 보일까요? (how would it look?).", "example_in_sentence": "보일까요"}]}, {"text": "인터넷에서 화제가 된 영상이 있어요.", "translation": "There is a video that has become a hot topic online.", "vocab": [{"ko": "인터넷", "en": "internet"}, {"ko": "화제", "en": "topic of conversation; hot topic"}, {"ko": "영상", "en": "video"}], "analysis": [{"type": "grammar", "label": "~이/가 되다", "exp": "Means ''to become (something)''. 화제가 되다 = to become a hot topic; 화제가 된 영상 = a video that went viral.", "example_in_sentence": "화제가 된"}]}, {"text": "영상에서는 고속열차 안에서 촬영한 모습을 보여줘요.", "translation": "The video shows footage filmed inside a high-speed train.", "vocab": [{"ko": "영상", "en": "video"}, {"ko": "촬영하다", "en": "to film; to shoot"}, {"ko": "모습", "en": "appearance; scene"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 촬영하다 (to film) → 촬영한 모습 (scenes that were filmed).", "example_in_sentence": "촬영한 모습"}]}, {"text": "창밖의 나무와 건물들이 매우 빠르게 지나가요.", "translation": "The trees and buildings outside the window pass very quickly.", "vocab": [{"ko": "창밖", "en": "outside the window"}, {"ko": "나무", "en": "tree"}, {"ko": "건물", "en": "building"}], "analysis": [{"type": "grammar", "label": "~와", "exp": "Coordinating particle joining two nouns. 나무 (tree) + 와 + 건물들 (buildings) = trees and buildings.", "example_in_sentence": "나무와 건물들이"}, {"type": "grammar", "label": "~게", "exp": "Adverbial suffix converting adjectives/verbs to adverbs. 빠르다 (fast) + 게 = quickly/fast (modifying the verb 지나가다).", "example_in_sentence": "빠르게"}]}, {"text": "마치 영화를 빨리 돌려보는 것 같아요.", "translation": "It''s just like watching a movie in fast-forward.", "vocab": [{"ko": "마치", "en": "as if; as though"}, {"ko": "영화", "en": "movie"}, {"ko": "돌려보다", "en": "to play back (a video)"}], "analysis": [{"type": "expression", "label": "~는 것 같다", "exp": "Says that something seems or feels like something. 돌려보다 → 돌려보는 것 같아요 (it''s like playing a video).", "example_in_sentence": "돌려보는 것 같아요"}]}, {"text": "우리나라 케이티엑스(KTX)도 최고 시속 300킬로미터로 달려요.", "translation": "Korea''s KTX also runs at a maximum speed of 300 kilometers per hour.", "vocab": [{"ko": "우리나라", "en": "our country; Korea"}, {"ko": "최고", "en": "maximum; highest"}, {"ko": "시속", "en": "speed per hour"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Particle indicating ''also'' or ''too''. 케이티엑스 (KTX) + 도 = KTX also.", "example_in_sentence": "케이티엑스(KTX)도"}]}, {"text": "서울에서 부산까지 2시간 반이면 갈 수 있어요.", "translation": "You can go from Seoul to Busan in two and a half hours.", "vocab": [{"ko": "서울", "en": "Seoul"}, {"ko": "부산", "en": "Busan"}, {"ko": "시간", "en": "hour"}], "analysis": [{"type": "grammar", "label": "~에서...까지", "exp": "Particle pair marking starting point and ending point. 서울 (Seoul) + 에서 + 부산 (Busan) + 까지 = from Seoul to Busan.", "example_in_sentence": "서울에서 부산까지"}, {"type": "grammar", "label": "~(이)면", "exp": "Means ''if it is''. With an amount of time it means ''in just that much time''. 2시간 반이면 = in two and a half hours.", "example_in_sentence": "2시간 반이면"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Auxiliary expressing possibility or ability. 가다 (to go) + ㄹ 수 있어요 = can go.", "example_in_sentence": "갈 수 있어요"}]}, {"text": "많은 사람들이 이 영상을 보고 놀라워했어요.", "translation": "Many people watched this video and were surprised.", "vocab": [{"ko": "많다", "en": "many; a lot"}, {"ko": "사람", "en": "person"}, {"ko": "놀라워하다", "en": "to be surprised"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Coordinating connective joining two actions in sequence. 보다 (to watch) + 고 + 놀라워했어요 (were surprised) = watched and were surprised.", "example_in_sentence": "보고 놀라워했어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 놀라워하다 (to be surprised) + 았어요 = were surprised (in past).", "example_in_sentence": "놀라워했어요"}]}, {"text": "\"정말 빠르다\", \"신기하다\"라는 댓글이 많았어요.", "translation": "There were many comments saying \"Really fast\" and \"Amazing.\"", "vocab": [{"ko": "정말", "en": "really; very"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "신기하다", "en": "to be amazing; to be novel"}, {"ko": "댓글", "en": "comment"}], "analysis": [{"type": "grammar", "label": "~라는", "exp": "Quotative modifier meaning ''that says/means''. Quote + 라는 = that says (modifying 댓글/comment).", "example_in_sentence": "\"정말 빠르다\", \"신기하다\"라는 댓글"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 많다 (to be many) + 았어요 = were many (in past).", "example_in_sentence": "많았어요"}]}, {"text": "고속열차의 빠른 속도를 실감할 수 있는 영상이에요.", "translation": "It is a video that allows you to actually feel the fast speed of the high-speed train.", "vocab": [{"ko": "고속열차", "en": "high-speed train"}, {"ko": "속도", "en": "speed"}, {"ko": "실감하다", "en": "to actually feel; to realize"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있는", "exp": "Possibility modifier. 실감하다 (to actually feel) + ㄹ 수 있는 = that allows (you) to actually feel.", "example_in_sentence": "실감할 수 있는 영상"}]}], "version": "s6"}', vocab = '[{"ko": "고속열차", "en": "high-speed train", "note": ""}, {"ko": "시속", "en": "speed per hour", "note": ""}, {"ko": "창밖", "en": "outside the window", "note": ""}, {"ko": "풍경", "en": "scenery", "note": ""}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "화제", "en": "topic of conversation; hot topic", "note": ""}, {"ko": "영상", "en": "video", "note": ""}, {"ko": "촬영하다", "en": "to film; to shoot", "note": ""}, {"ko": "모습", "en": "appearance; scene", "note": ""}, {"ko": "나무", "en": "tree", "note": ""}, {"ko": "건물", "en": "building", "note": ""}, {"ko": "마치", "en": "as if; as though", "note": ""}, {"ko": "영화", "en": "movie", "note": ""}, {"ko": "돌려보다", "en": "to play back (a video)", "note": ""}, {"ko": "우리나라", "en": "our country; Korea", "note": ""}, {"ko": "최고", "en": "maximum; highest", "note": ""}, {"ko": "서울", "en": "Seoul", "note": ""}, {"ko": "부산", "en": "Busan", "note": ""}, {"ko": "시간", "en": "hour", "note": ""}, {"ko": "많다", "en": "many; a lot", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "놀라워하다", "en": "to be surprised", "note": ""}, {"ko": "정말", "en": "really; very", "note": ""}, {"ko": "빠르다", "en": "to be fast", "note": ""}, {"ko": "신기하다", "en": "to be amazing; to be novel", "note": ""}, {"ko": "댓글", "en": "comment", "note": ""}, {"ko": "속도", "en": "speed", "note": ""}, {"ko": "실감하다", "en": "to actually feel; to realize", "note": ""}, {"word": "지나가다", "reading": "jinagada", "meaning": "to pass by; to go past", "context": "창밖의 나무와 건물들이 매우 빠르게 지나가요"}, {"word": "놀라다", "reading": "nollada", "meaning": "to be surprised; to be astonished", "context": "많은 사람들이 이 영상을 보고 놀라워했어요"}]', grammar = '{"patterns": [{"name": "~(으)ㄹ 때",