update public.article_cache set translation = '{"texts": ["There is a wonderful picture in Dublin, Ireland. It is a special work drawn on a street wall.", "The person who drew this picture is ACHES. He is called a street artist.", "Many people come to see this picture. It is really beautiful and fun.", "Street art makes the city more beautiful. There are similar pictures in our country too."], "sentences": [{"text": "아일랜드 더블린에 멋진 그림이 있어요.", "translation": "There is a wonderful picture in Dublin, Ireland.", "vocab": [{"ko": "아일랜드", "en": "Ireland"}, {"ko": "멋지다", "en": "to be wonderful; to be cool"}, {"ko": "그림", "en": "picture; drawing"}], "analysis": [{"type": "grammar", "label": "~에", "exp": "Locative particle marking location where something exists.", "example_in_sentence": "아일랜드 더블린에"}, {"type": "grammar", "label": "~이/가 있어요", "exp": "Says that something exists: ''there is''. 그림 + 이 있어요 → there is a picture.", "example_in_sentence": "그림이 있어요"}]}, {"text": "거리 벽에 그려진 특별한 작품이에요.", "translation": "It is a special work drawn on a street wall.", "vocab": [{"ko": "거리", "en": "street"}, {"ko": "벽", "en": "wall"}, {"ko": "그려지다", "en": "to be drawn; to be painted"}, {"ko": "특별하다", "en": "to be special"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 그려지다 (to be drawn) → 그려진 작품 (a work that was drawn).", "example_in_sentence": "그려진"}, {"type": "grammar", "label": "~이에요", "exp": "Polite form of 이다 (to be) after a consonant. 작품 → 작품이에요 (is a work).", "example_in_sentence": "작품이에요"}]}, {"text": "이 그림을 그린 사람은 에이치이에스(ACHES)예요.", "translation": "The person who drew this picture is ACHES.", "vocab": [{"ko": "그리다", "en": "to draw; to paint"}, {"ko": "사람", "en": "person"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Accusative particle marking direct object of transitive verb.", "example_in_sentence": "그림을"}, {"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 그리다 (to draw) → 그린 사람 (the person who drew).", "example_in_sentence": "그린 사람"}, {"type": "grammar", "label": "~은/는", "exp": "Topic particle marking the subject/topic of the sentence.", "example_in_sentence": "사람은"}]}, {"text": "거리 예술가(street artist)라고 불러요.", "translation": "He is called a street artist.", "vocab": [{"ko": "거리", "en": "street"}, {"ko": "예술가", "en": "artist"}, {"ko": "부르다", "en": "to call; to name"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다", "exp": "Says what someone is called. 거리 예술가 + 라고 부르다 → to call (him) a street artist.", "example_in_sentence": "라고 불러요"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 부르다 is 르-irregular: 부르다 → 불러요 (call).", "example_in_sentence": "불러요"}]}, {"text": "많은 사람들이 이 그림을 보러 와요.", "translation": "Many people come to see this picture.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "사람", "en": "person"}, {"ko": "보다", "en": "to see; to watch"}, {"ko": "오다", "en": "to come"}], "analysis": [{"type": "grammar", "label": "~어요", "exp": "Present tense polite ending.", "example_in_sentence": "와요"}, {"type": "expression", "label": "~(으)러 오다", "exp": "Shows the purpose of coming. 보다 (to see) → 보러 와요 (come to see).", "example_in_sentence": "보러 와요"}]}, {"text": "정말 아름답고 재미있어요.", "translation": "It is truly beautiful and interesting.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "아름답다", "en": "to be beautiful"}, {"ko": "재미있다", "en": "to be interesting; to be fun"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending joining two adjectives in sequence.", "example_in_sentence": "아름답고"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending for adjectives.", "example_in_sentence": "재미있어요"}]}, {"text": "거리 예술은 도시를 더 예쁘게 만들어요.", "translation": "Street art makes the city more beautiful.", "vocab": [{"ko": "거리", "en": "street"}, {"ko": "예술", "en": "art"}, {"ko": "도시", "en": "city"}, {"ko": "예쁘다", "en": "to be p